import React from 'react';
import { Search, SlidersHorizontal, Leaf, Flame, Fish, Drumstick, WheatOff } from 'lucide-react';
import { FilterState } from '../types';

interface FilterBarProps {
  filters: FilterState;
  onFilterChange: (filters: FilterState) => void;
}

export const FilterBar: React.FC<FilterBarProps> = ({ filters, onFilterChange }) => {
  const dietaryOptions = ['Vegetarian', 'Vegan', 'Gluten Free', 'Lactose Free'];
  const categoryOptions = [
    { name: 'Carne', icon: Drumstick },
    { name: 'Pesce', icon: Fish },
    { name: 'Piccante', icon: Flame },
  ];

  const toggleDietary = (option: string) => {
    const current = filters.dietary;
    const next = current.includes(option)
      ? current.filter(d => d !== option)
      : [...current, option];
    onFilterChange({ ...filters, dietary: next });
  };

  const toggleCategory = (option: string) => {
    const current = filters.categories || [];
    const next = current.includes(option)
      ? current.filter(c => c !== option)
      : [...current, option];
    onFilterChange({ ...filters, categories: next });
  };

  return (
    <div className="bg-white border-b border-orange-100 py-4 sticky top-20 z-40 shadow-sm">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 space-y-4">

        {/* Search Input */}
        <div className="relative">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-gray-400" />
          </div>
          <input
            type="text"
            placeholder="Cerca piatti, ingredienti o chef..."
            className="block w-full pl-10 pr-3 py-2 border border-gray-200 rounded-xl leading-5 bg-gray-50 placeholder-gray-400 focus:outline-none focus:bg-white focus:ring-1 focus:ring-orange-500 focus:border-orange-500 sm:text-sm transition duration-150 ease-in-out"
            value={filters.search}
            onChange={(e) => onFilterChange({ ...filters, search: e.target.value })}
          />
        </div>

        {/* Filters Row */}
        <div className="flex flex-col gap-3">

          <div className="flex flex-wrap items-center gap-4">
            {/* Price Range */}
            <div className="flex items-center space-x-2 bg-gray-50 px-3 py-2 rounded-lg border border-gray-100">
               <span className="text-sm text-gray-600 font-medium whitespace-nowrap">Max € {filters.maxPrice}</span>
               <input
                 type="range"
                 min="5"
                 max="50"
                 step="1"
                 value={filters.maxPrice}
                 onChange={(e) => onFilterChange({ ...filters, maxPrice: parseInt(e.target.value) })}
                 className="w-24 md:w-32 h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-600"
               />
            </div>

            {/* Category Filters (Meat, Fish, Spicy) */}
            <div className="flex flex-wrap gap-2">
              {categoryOptions.map(cat => {
                const Icon = cat.icon;
                const isSelected = filters.categories?.includes(cat.name);
                return (
                  <button
                    key={cat.name}
                    onClick={() => toggleCategory(cat.name)}
                    className={`flex items-center space-x-1 px-3 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider transition-colors border ${
                      isSelected
                        ? 'bg-orange-100 text-orange-800 border-orange-200'
                        : 'bg-white text-gray-600 border-gray-200 hover:bg-orange-50'
                    }`}
                  >
                    <Icon className="w-3.5 h-3.5" />
                    <span>{cat.name}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Dietary Filters */}
          <div className="flex flex-wrap gap-2">
            {dietaryOptions.map(option => (
              <button
                key={option}
                onClick={() => toggleDietary(option)}
                className={`flex items-center space-x-1 px-3 py-1.5 rounded-full text-xs font-semibold transition-colors border ${
                  filters.dietary.includes(option)
                    ? 'bg-green-100 text-green-700 border-green-200'
                    : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                }`}
              >
                <Leaf className="w-3 h-3" />
                <span>{option}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

