import React, { useState, useMemo } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef } from './types';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);

  // Booking State
  const [bookingDish, setBookingDish] = useState<Dish | null>(null);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  // Open booking modal instead of adding directly
  const handleInitiateBooking = (dish: Dish) => {
    setBookingDish(dish);
  };

  const handleConfirmBooking = (date: string, time: string) => {
    if (!bookingDish) return;

    setCart(prev => {
      // Logic: If same dish AND same time/date, increment qty. Otherwise add new item.
      const existing = prev.find(item => 
        item.id === bookingDish.id && 
        item.scheduledDate === date && 
        item.scheduledTime === time
      );

      if (existing) {
        return prev.map(item => 
          (item.id === bookingDish.id && item.scheduledDate === date && item.scheduledTime === time)
            ? { ...item, quantity: item.quantity + 1 } 
            : item
        );
      }
      return [...prev, { ...bookingDish, quantity: 1, scheduledDate: date, scheduledTime: time }];
    });

    setBookingDish(null);
    setIsCartOpen(true);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : null;
        }
        return item;
      }).filter(Boolean) as CartItem[];
    });
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo(0, 0);
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  // Helper to find chef for booking modal
  const getChefForDish = (dish: Dish | null) => {
    if (!dish) return undefined;
    return MOCK_CHEFS.find(c => c.id === dish.chefId);
  };

  // Filtering Logic
  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      // Filter dishes within the chef first
      const matchingDishes = chef.dishes.filter(dish => {
        // Price Filter
        const matchesPrice = dish.price <= filters.maxPrice;

        // Dietary Filter (Vegan, Gluten Free etc) - checks dish.dietary
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));

        // Category Filter (Carne, Pesce, Piccante) - checks dish.tags
        const matchesCategory = (filters.categories || []).length === 0 ||
          (filters.categories || []).every(cat => dish.tags?.includes(cat));

        // Search Filter
        const searchLower = filters.search.toLowerCase();
        const matchesSearch = !filters.search || 
          dish.name.toLowerCase().includes(searchLower) ||
          dish.description.toLowerCase().includes(searchLower) ||
          chef.name.toLowerCase().includes(searchLower) ||
          dish.tags.some(tag => tag.toLowerCase().includes(searchLower));

        return matchesPrice && matchesDietary && matchesCategory && matchesSearch;
      });

      // Return chef with filtered dishes if any exist
      // Note: If user searches for Chef Name, we might want to show all dishes? 
      // Current logic: Show only matching dishes. If searching by chef name, all dishes usually match 'matchesSearch' but pass price filters etc.
      if (matchingDishes.length > 0) {
        return { ...chef, dishes: matchingDishes };
      }
      return null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  // Check if any filters are active to toggle Hero vs Specials
  const isFiltering = filters.search || filters.dietary.length > 0 || (filters.categories && filters.categories.length > 0);

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900">
      <Header 
        cartCount={cartCount} 
        onCartClick={() => setIsCartOpen(true)}
        currentView={currentView}
        onNavigate={(view) => {
          setCurrentView(view);
          if (view === ViewState.HOME) setSelectedChef(null);
        }}
      />

      {currentView === ViewState.HOME && (
        <FilterBar filters={filters} onFilterChange={setFilters} />
      )}

      <main className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {/* Hero Section (Only show if no search/filter active) */}
            {!isFiltering && (
              <>
                <div className="text-center mb-12 py-10 bg-black rounded-3xl text-white shadow-2xl overflow-hidden relative">
                  <div className="absolute top-0 left-0 w-full h-full opacity-20 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center"></div>
                  <div className="relative z-10 px-4">
                    <h1 className="text-4xl md:text-6xl font-extrabold mb-4 tracking-tight">
                      MESA
                    </h1>
                    <p className="text-xl md:text-2xl font-light text-gray-300 max-w-2xl mx-auto mb-8">
                      La vera cucina casalinga,<br/>
                      <span className="text-orange-500 font-bold">su prenotazione.</span>
                    </p>
                    <button className="px-8 py-3 bg-orange-600 text-white font-bold rounded-full hover:bg-orange-700 transition shadow-lg shadow-orange-900/50 transform hover:-translate-y-1">
                      Scopri i Menu
                    </button>
                  </div>
                </div>

                {/* Daily Specials Carousel */}
                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} />
              </>
            )}

            {/* Results Info */}
            <div className="mb-6 flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900 border-l-4 border-orange-600 pl-3">
                {filteredChefs.length} Chef Disponibili
              </h2>
            </div>

            {/* Chef List */}
            <div className="space-y-6">
               {filteredChefs.map(chef => (
                 <ChefCard 
                   key={chef.id} 
                   chef={chef} 
                   onAddDish={handleInitiateBooking}
                   onViewProfile={handleViewProfile}
                 />
               ))}
               {filteredChefs.length === 0 && (
                 <div className="text-center py-20 bg-gray-50 rounded-3xl border-2 border-dashed border-gray-200">
                   <p className="text-gray-500 text-lg">Nessun piatto trovato con questi filtri.</p>
                   <button 
                    onClick={() => setFilters({ search: '', maxPrice: 50, dietary: [], categories: [] })}
                    className="mt-4 text-orange-600 font-bold hover:underline"
                   >
                     Resetta filtri
                   </button>
                 </div>
               )}
            </div>
          </div>
        )}

        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile 
            chef={selectedChef} 
            onBack={() => setCurrentView(ViewState.HOME)}
            onAddDish={handleInitiateBooking}
          />
        )}

        {currentView === ViewState.AI_MENU_CREATOR && (
          <div className="animate-fade-in">
            <AiMenuCreator />
          </div>
        )}

      </main>

      <BookingModal 
        isOpen={!!bookingDish}
        onClose={() => setBookingDish(null)}
        dish={bookingDish!}
        chef={getChefForDish(bookingDish)}
        onConfirm={handleConfirmBooking}
      />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        cart={cart}
        onUpdateQuantity={handleUpdateQuantity}
      />
    </div>
  );
}

