import React, { useState } from 'react';
import { X, Calendar, Clock, ChefHat, Truck, ShoppingBag, Flame, Utensils, MessageSquare } from 'lucide-react';
import { Dish, Chef } from '../types';

interface BookingModalProps {
  isOpen: boolean;
  onClose: () => void;
  dish: Dish;
  chef: Chef | undefined;
  onConfirm: (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => void;
}

export const BookingModal: React.FC<BookingModalProps> = ({ isOpen, onClose, dish, chef, onConfirm }) => {
  const [date, setDate] = useState('');
  const [time, setTime] = useState('');
  const [deliveryMode, setDeliveryMode] = useState<'delivery' | 'pickup'>('pickup');

  // Customization State
  const [spiceLevel, setSpiceLevel] = useState(1); // 0=None, 1=Low, 2=Med, 3=High
  const [saltLevel, setSaltLevel] = useState<'Low' | 'Normal' | 'High'>('Normal');
  const [notes, setNotes] = useState('');

  if (!isOpen) return null;

  const timeSlots = [
    '12:00', '12:30', '13:00', '13:30', '14:00',
    '19:00', '19:30', '20:00', '20:30', '21:00', '21:30'
  ];

  const handleConfirm = () => {
    if (date && time) {
      onConfirm(date, time, deliveryMode, { spiceLevel, saltLevel, notes });
      // Reset
      setSpiceLevel(1);
      setSaltLevel('Normal');
      setNotes('');
      setDeliveryMode('pickup');
      setDate('');
      setTime('');
    }
  };

  return (
    <div className="fixed inset-0 z-[60] overflow-y-auto">
      <div className="flex min-h-full items-center justify-center p-4 text-center">
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm transition-opacity" onClick={onClose} />

        <div className="relative transform overflow-hidden rounded-2xl bg-white text-left shadow-2xl transition-all w-full max-w-2xl border-t-8 border-orange-500">

          {/* Header */}
          <div className="bg-gray-50 px-6 py-4 flex items-center justify-between border-b border-gray-100">
            <h3 className="text-xl font-bold text-gray-900 flex items-center">
              <Utensils className="w-5 h-5 mr-2 text-orange-600" />
              Personalizza & Prenota
            </h3>
            <button onClick={onClose} className="p-2 text-gray-400 hover:text-gray-600 bg-white rounded-full shadow-sm hover:shadow-md transition-all">
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="p-6 max-h-[70vh] overflow-y-auto">
            {/* Dish Info */}
            <div className="flex items-start space-x-4 mb-8 p-4 bg-orange-50/50 rounded-xl border border-orange-100">
              <img src={dish.image} alt={dish.name} className="w-24 h-24 rounded-lg object-cover shadow-sm" />
              <div>
                <h4 className="font-bold text-gray-900 text-lg">{dish.name}</h4>
                <div className="flex items-center text-sm text-gray-600 mt-1">
                  <ChefHat className="w-4 h-4 mr-1 text-orange-500" />
                  <span>Cucinato da <span className="font-semibold">{chef?.name}</span> {chef?.nationality}</span>
                </div>
                <p className="text-sm text-gray-500 mt-2 leading-relaxed line-clamp-2">{dish.description}</p>
                <div className="mt-2 text-orange-600 font-bold">€ {dish.price.toFixed(2)}</div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

              {/* Left Col: Customization */}
              <div className="space-y-6">
                <h4 className="font-bold text-gray-900 border-b pb-2">1. Personalizza il Piatto</h4>

                {/* Spice Level */}
                <div>
                   <label className="flex items-center text-sm font-semibold text-gray-700 mb-2">
                     <Flame className="w-4 h-4 mr-1 text-red-500" />
                     Livello Piccantezza
                   </label>
                   <div className="flex items-center space-x-2 bg-gray-100 p-1 rounded-lg">
                      {[0, 1, 2, 3].map((level) => (
                        <button
                          key={level}
                          onClick={() => setSpiceLevel(level)}
                          className={`flex-1 py-1 text-xs font-bold rounded-md transition-colors ${
                            spiceLevel === level ? 'bg-white text-red-600 shadow-sm' : 'text-gray-400 hover:text-gray-600'
                          }`}
                        >
                          {level === 0 ? 'Zero' : level === 1 ? 'Poco' : level === 2 ? 'Medio' : 'Fuoco'}
                        </button>
                      ))}
                   </div>
                </div>

                {/* Salt Level */}
                <div>
                   <label className="flex items-center text-sm font-semibold text-gray-700 mb-2">
                     Sale
                   </label>
                   <div className="flex items-center space-x-2">
                      {(['Low', 'Normal', 'High'] as const).map((level) => (
                        <button
                          key={level}
                          onClick={() => setSaltLevel(level)}
                          className={`flex-1 py-2 px-3 text-xs font-bold rounded-lg border transition-all ${
                            saltLevel === level 
                              ? 'bg-blue-50 border-blue-200 text-blue-700' 
                              : 'bg-white border-gray-200 text-gray-500 hover:border-blue-200'
                          }`}
                        >
                          {level === 'Low' ? 'Poco' : level === 'Normal' ? 'Giusto' : 'Saporito'}
                        </button>
                      ))}
                   </div>
                </div>

                {/* Notes */}
                <div>
                  <label className="flex items-center text-sm font-semibold text-gray-700 mb-2">
                    <MessageSquare className="w-4 h-4 mr-1 text-gray-400" />
                    Note per lo Chef
                  </label>
                  <textarea 
                    className="w-full text-sm p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-gray-50"
                    placeholder="Allergie, intolleranze o richieste speciali..."
                    rows={3}
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                  />
                </div>
              </div>

              {/* Right Col: Logistics */}
              <div className="space-y-6">
                <h4 className="font-bold text-gray-900 border-b pb-2">2. Consegna e Data</h4>

                {/* Delivery Mode */}
                <div className="flex p-1 bg-gray-100 rounded-xl">
                  <button
                    onClick={() => setDeliveryMode('pickup')}
                    className={`flex-1 flex items-center justify-center py-2 text-sm font-bold rounded-lg transition-all ${
                      deliveryMode === 'pickup' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-400'
                    }`}
                  >
                    <ShoppingBag className="w-4 h-4 mr-2" />
                    Ritiro
                  </button>
                  <button
                    onClick={() => setDeliveryMode('delivery')}
                    className={`flex-1 flex items-center justify-center py-2 text-sm font-bold rounded-lg transition-all ${
                      deliveryMode === 'delivery' ? 'bg-white text-orange-600 shadow-sm' : 'text-gray-400'
                    }`}
                  >
                    <Truck className="w-4 h-4 mr-2" />
                    Domicilio (+€2.50)
                  </button>
                </div>

                {/* Date */}
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Data</label>
                  <input
                    type="date"
                    className="block w-full px-4 py-2 border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none bg-gray-50 text-sm"
                    value={date}
                    onChange={(e) => setDate(e.target.value)}
                    min={new Date().toISOString().split('T')[0]}
                  />
                </div>

                {/* Time */}
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Orario</label>
                  <div className="grid grid-cols-4 gap-2">
                    {timeSlots.map(slot => (
                      <button
                        key={slot}
                        onClick={() => setTime(slot)}
                        className={`py-1.5 px-1 text-xs font-medium rounded-lg border transition-all ${
                          time === slot
                            ? 'bg-orange-600 text-white border-orange-600'
                            : 'bg-white text-gray-700 border-gray-200 hover:bg-orange-50'
                        }`}
                      >
                        {slot}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="bg-gray-50 px-6 py-4 flex justify-between items-center">
            <div className="text-sm text-gray-500">
              {deliveryMode === 'delivery' ? 'Consegna a Domicilio inclusa' : 'Ritiro presso Chef'}
            </div>
            <div className="flex space-x-3">
              <button
                onClick={onClose}
                className="px-5 py-2.5 text-gray-600 font-medium hover:bg-gray-200 rounded-xl transition-colors"
              >
                Annulla
              </button>
              <button
                onClick={handleConfirm}
                disabled={!date || !time}
                className="px-6 py-2.5 bg-black text-white font-bold rounded-xl shadow-lg hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed transition-all active:scale-95 flex items-center"
              >
                Conferma
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

