interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  onUpdateQuantity: (id: string, delta: number) => void;
  onCheckout: (total: number) => void;
}

export const CartDrawer: React.FC<CartDrawerProps> = ({ isOpen, onClose, cart, onUpdateQuantity, onCheckout }) => {
  const deliveryFeeBase = 2.50;

  // Calculate delivery fee: sum of delivery fees for items marked as 'delivery'. 
  // Simplified logic: If ANY item is delivery, we charge fee once per chef? Or per item? 
  // Let's assume standard logic: If an item is 'delivery', we add fee.
  // Actually, usually fee is per order, but here we have mixed chefs. 
  // Let's implement: €2.50 fee for EACH unique delivery order instance. 
  // To keep simple: Sum of fees for items marked delivery (assuming distinct deliveries).
  const deliveryTotal = cart.reduce((acc, item) => item.deliveryMode === 'delivery' ? acc + deliveryFeeBase : acc, 0);

  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const total = subtotal + deliveryTotal;

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

      <div className="absolute inset-y-0 right-0 max-w-md w-full flex">
