  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  const handleInitiateBooking = (dish: Dish) => {
    setBookingDish(dish);
  };

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;

    setCart(prev => {
      // Check for identical item (including customization)
      // For simplicity, we just check ID/Date/Time/DeliveryMode
      const existing = prev.find(item => 
        item.id === bookingDish.id && 
        item.scheduledDate === date && 
        item.scheduledTime === time &&
        item.deliveryMode === deliveryMode
      );

      if (existing) {
        return prev.map(item => 
          item === existing ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        ...bookingDish, 
        quantity: 1, 
        scheduledDate: date, 
        scheduledTime: time,
        deliveryMode,
        preferences
      }];
    });

    setBookingDish(null);
    setIsCartOpen(true);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : null;
        }
        return item;
      }).filter(Boolean) as CartItem[];
    });
