export interface Dish {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  chefId: string;
  tags: string[]; // Used for categories like 'Carne', 'Pesce', 'Piccante'
  calories?: number;
  dietary?: ('Vegetarian' | 'Vegan' | 'Gluten Free' | 'Lactose Free')[];
}

export interface Chef {
  id: string;
  name: string;
  nationality: string; // Emoji flag e.g. "🇮🇹"
  bio: string;
  fullBio?: string;
  avatar: string;
  rating: number;
  location: string;
  distance: number; // km
  specialties: string[];
  availability: string[]; // Text description
  availableDays: number[]; // 0=Sun, 1=Mon, ..., 6=Sat
  reviews: Review[];
  dishes: Dish[];
}

export interface CartItem extends Dish {
  quantity: number;
  scheduledDate: string; // YYYY-MM-DD
  scheduledTime: string; // HH:MM
  deliveryMode: 'delivery' | 'pickup';
  preferences: {
    spiceLevel: number; // 0-3
    saltLevel: 'Low' | 'Normal' | 'High';
    notes: string;
  };
}

export interface CultureStory {
  id: string;
  title: string;
  country: string;
  flag: string;
  image: string;
  content: string;
  funFact: string;
}

export enum ViewState {
  HOME = 'HOME',
  CHEFS = 'CHEFS',
  CULTURE = 'CULTURE',
  CHEF_PROFILE = 'CHEF_PROFILE',
  AI_MENU_CREATOR = 'AI_MENU_CREATOR',
}

export interface AiMenuResponse {
  dishName: string;
  description: string;
  suggestedPrice: number;
  tags: string[];
}

export interface FilterState {
  search: string;
  maxPrice: number;
  dietary: string[];
  categories: string[];
}

