import React, { useState, useMemo } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef } from './types';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);

  // Modals State
  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  const handleInitiateBooking = (dish: Dish) => {
    setBookingDish(dish);
  };

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;

    setCart(prev => {
      // Check for identical item (including customization)
      const existing = prev.find(item => 
        item.id === bookingDish.id && 
        item.scheduledDate === date && 
        item.scheduledTime === time &&
        item.deliveryMode === deliveryMode
      );

      if (existing) {
        return prev.map(item => 
          item === existing ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { 
        ...bookingDish, 
        quantity: 1, 
        scheduledDate: date, 
        scheduledTime: time,
        deliveryMode,
        preferences
      }];
    });

    setBookingDish(null);
    setIsCartOpen(true);
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : null;
        }
        return item;
      }).filter(Boolean) as CartItem[];
    });
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentClose = () => {
    setIsPaymentOpen(false);
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo(0, 0);
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  const getChefForDish = (dish: Dish | null) => {
    if (!dish) return undefined;
    return MOCK_CHEFS.find(c => c.id === dish.chefId);
  };

  // Filtering Logic
  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));
        const matchesCategory = (filters.categories || []).length === 0 ||
          (filters.categories || []).every(cat => dish.tags?.includes(cat));

        const searchLower = filters.search.toLowerCase();
        const matchesSearch = !filters.search || 
          dish.name.toLowerCase().includes(searchLower) ||
          dish.description.toLowerCase().includes(searchLower) ||
          chef.name.toLowerCase().includes(searchLower) ||
          dish.tags.some(tag => tag.toLowerCase().includes(searchLower));

        return matchesPrice && matchesDietary && matchesCategory && matchesSearch;
      });

      if (matchingDishes.length > 0) {
        return { ...chef, dishes: matchingDishes };
      }
      return null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  const isFiltering = filters.search || filters.dietary.length > 0 || (filters.categories && filters.categories.length > 0);

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900">
      <Header 
        cartCount={cartCount} 
        onCartClick={() => setIsCartOpen(true)}
        currentView={currentView}
        onNavigate={(view) => {
          setCurrentView(view);
          if (view === ViewState.HOME) setSelectedChef(null);
        }}
        onAuthClick={() => setIsAuthOpen(true)}
      />

      {currentView === ViewState.HOME && (
        <FilterBar filters={filters} onFilterChange={setFilters} />
      )}

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!isFiltering && (
              <>
                <div className="text-center mb-12 py-16 bg-black rounded-3xl text-white shadow-2xl overflow-hidden relative border-b-4 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center mix-blend-overlay"></div>
                  <div className="relative z-10 px-4">
                    <h1 className="text-5xl md:text-7xl font-extrabold mb-6 tracking-tight">
                      MESA
                    </h1>
                    <p className="text-xl md:text-2xl font-light text-gray-300 max-w-2xl mx-auto mb-10 leading-relaxed">
                      La vera cucina casalinga, certificata e autentica.<br/>
                      <span className="text-orange-500 font-bold">Dai nostri cuochi, alla tua tavola.</span>
                    </p>
                    <button className="px-10 py-4 bg-orange-600 text-black font-extrabold rounded-full hover:bg-white hover:text-black transition-all shadow-lg shadow-orange-900/50 transform hover:-translate-y-1">
                      Esplora i Menu
                    </button>
                  </div>
                </div>
                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} />
              </>
            )}

            <div className="mb-6 flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900 border-l-4 border-orange-600 pl-3">
                {filteredChefs.length} Chef Disponibili
              </h2>
            </div>

            <div className="space-y-6">
               {filteredChefs.map(chef => (
                 <ChefCard 
                   key={chef.id} 
                   chef={chef} 
                   onAddDish={handleInitiateBooking}
                   onViewProfile={handleViewProfile}
                 />
               ))}
               {filteredChefs.length === 0 && (
                 <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-gray-200">
                   <p className="text-gray-500 text-lg">Nessun piatto trovato con questi filtri.</p>
                   <button 
                    onClick={() => setFilters({ search: '', maxPrice: 50, dietary: [], categories: [] })}
                    className="mt-4 text-orange-600 font-bold hover:underline"
                   >
                     Resetta filtri
                   </button>
                 </div>
               )}
            </div>
          </div>
        )}

        {currentView === ViewState.CHEFS && (
          <MesaChefs 
            chefs={MOCK_CHEFS}
            onViewProfile={handleViewProfile}
          />
        )}

        {currentView === ViewState.CULTURE && (
          <CultureSection />
        )}

        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile 
            chef={selectedChef} 
            onBack={() => setCurrentView(ViewState.HOME)}
            onAddDish={handleInitiateBooking}
          />
        )}

        {currentView === ViewState.AI_MENU_CREATOR && (
          <div className="animate-fade-in">
            <AiMenuCreator />
          </div>
        )}
      </main>

      <BookingModal 
        isOpen={!!bookingDish}
        onClose={() => setBookingDish(null)}
        dish={bookingDish!}
        chef={getChefForDish(bookingDish)}
        onConfirm={handleConfirmBooking}
      />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        cart={cart}
        onUpdateQuantity={handleUpdateQuantity}
        onCheckout={handleCheckout}
      />

      <PaymentModal 
        isOpen={isPaymentOpen} 
        onClose={handlePaymentClose} 
        total={checkoutTotal}
      />

      <AuthModal
        isOpen={isAuthOpen}
        onClose={() => setIsAuthOpen(false)}
      />
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { X, User, ChefHat, LogIn } from 'lucide-react';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose }) => {
  const [role, setRole] = useState<'client' | 'chef'>('client');
  const [mode, setMode] = useState<'login' | 'register'>('login');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert(`Simulazione: ${mode === 'login' ? 'Accesso' : 'Registrazione'} effettuata come ${role === 'client' ? 'Cliente' : 'Cuoco'}!`);
    onClose();
  };

  const handleGuestLogin = () => {
    alert("Accesso effettuato in Modalità Demo Ospite.\nBenvenuto su MESA!");
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[80] overflow-y-auto">
      <div className="flex min-h-full items-center justify-center p-4">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

        <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
          <button onClick={onClose} className="absolute top-4 right-4 text-gray-400 hover:text-gray-600 z-10">
            <X className="w-6 h-6" />
          </button>

          <div className="flex border-b border-gray-100">
            <button
              onClick={() => setRole('client')}
              className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex items-center justify-center space-x-2 transition-colors ${
                role === 'client' ? 'bg-white text-orange-600 border-b-2 border-orange-600' : 'bg-gray-50 text-gray-500 hover:bg-gray-100'
              }`}
            >
              <User className="w-4 h-4" />
              <span>Cliente</span>
            </button>
            <button
              onClick={() => setRole('chef')}
              className={`flex-1 py-4 text-sm font-bold uppercase tracking-wider flex items-center justify-center space-x-2 transition-colors ${
                role === 'chef' ? 'bg-white text-orange-600 border-b-2 border-orange-600' : 'bg-gray-50 text-gray-500 hover:bg-gray-100'
              }`}
            >
              <ChefHat className="w-4 h-4" />
              <span>Cuoco</span>
            </button>
          </div>

          <div className="p-8">
            <h2 className="text-2xl font-bold text-gray-900 mb-2">
              {mode === 'login' ? 'Bentornato!' : role === 'client' ? 'Unisciti a MESA' : 'Diventa un Cuoco'}
            </h2>
            <p className="text-gray-500 text-sm mb-6">
              {mode === 'login' 
                ? 'Accedi per gestire i tuoi ordini e preferenze.' 
                : role === 'client' 
                  ? 'Registrati per ordinare piatti fatti in casa.' 
                  : 'Condividi la tua passione e guadagna cucinando.'}
            </p>

            <form onSubmit={handleSubmit} className="space-y-4">
              {mode === 'register' && (
                <div className="grid grid-cols-2 gap-4">
                  <input type="text" placeholder="Nome" className="w-full p-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500 outline-none transition-all" required />
                  <input type="text" placeholder="Cognome" className="w-full p-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500 outline-none transition-all" required />
                </div>
              )}

              <input type="email" placeholder="Email" className="w-full p-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500 outline-none transition-all" required />
              <input type="password" placeholder="Password" className="w-full p-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500 outline-none transition-all" required />

              {mode === 'register' && role === 'chef' && (
                 <input type="text" placeholder="Specialità Culinaria (es. Pasta, Sushi)" className="w-full p-3 border border-gray-200 rounded-lg focus:ring-2 focus:ring-orange-500 outline-none transition-all" />
              )}

              <button type="submit" className="w-full py-3 bg-black text-white font-bold rounded-lg hover:bg-gray-800 transition-all shadow-md">
                {mode === 'login' ? 'Accedi' : 'Registrati'}
              </button>
            </form>

            <div className="mt-4 flex items-center justify-between">
              <div className="h-px bg-gray-200 flex-1"></div>
              <span className="px-3 text-xs text-gray-400 font-medium">OPPURE</span>
              <div className="h-px bg-gray-200 flex-1"></div>
            </div>

            <button 
              onClick={handleGuestLogin}
              className="w-full mt-4 py-3 bg-orange-50 text-orange-700 font-bold rounded-lg hover:bg-orange-100 transition-all border border-orange-200 flex items-center justify-center space-x-2"
            >
              <LogIn className="w-4 h-4" />
              <span>Prova Demo come Ospite</span>
            </button>

            <div className="mt-6 text-center text-sm text-gray-500">
              {mode === 'login' ? 'Non hai un account? ' : 'Hai già un account? '}
              <button 
                onClick={() => setMode(mode === 'login' ? 'register' : 'login')}
                className="font-bold text-orange-600 hover:underline"
              >
                {mode === 'login' ? 'Registrati' : 'Accedi'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

