import React, { useState, useMemo } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { Footer } from './components/Footer';
import { NotificationToast } from './components/NotificationToast';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef } from './types';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);

  // Modals State
  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  // Notification State
  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const handleInitiateBooking = (dish: Dish) => {
    setBookingDish(dish);
  };

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;

    setCart(prev => {
      // Improved logic: Check for identical item INCLUDING preferences.
      // If a user orders "Spicy Level 3" and then "Spicy Level 0" of the same dish, they should be separate items.
      const existingIndex = prev.findIndex(item => 
        item.id === bookingDish.id && 
        item.scheduledDate === date && 
        item.scheduledTime === time &&
        item.deliveryMode === deliveryMode &&
        // Deep compare preferences
        JSON.stringify(item.preferences) === JSON.stringify(preferences)
      );

      if (existingIndex >= 0) {
        // Update quantity of existing item
        const newCart = [...prev];
        newCart[existingIndex] = {
          ...newCart[existingIndex],
          quantity: newCart[existingIndex].quantity + 1
        };
        return newCart;
      }

      // Add new item
      return [...prev, { 
        ...bookingDish, 
        quantity: 1, 
        scheduledDate: date, 
        scheduledTime: time,
        deliveryMode,
        preferences
      }];
    });

    setBookingDish(null);
    // Removed setIsCartOpen(true) to allow continuing shopping
    showNotification("Piatto aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : null;
        }
        return item;
      }).filter(Boolean) as CartItem[];
    });
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentClose = () => {
    setIsPaymentOpen(false);
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo(0, 0);
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  const getChefForDish = (dish: Dish | null) => {
    if (!dish) return undefined;
    return MOCK_CHEFS.find(c => c.id === dish.chefId);
  };

  // Filtering Logic
  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));
        const matchesCategory = (filters.categories || []).length === 0 ||
          (filters.categories || []).every(cat => dish.tags?.includes(cat));

        const searchLower = filters.search.toLowerCase();
        const matchesSearch = !filters.search || 
          dish.name.toLowerCase().includes(searchLower) ||
          dish.description.toLowerCase().includes(searchLower) ||
          chef.name.toLowerCase().includes(searchLower) ||
          dish.tags.some(tag => tag.toLowerCase().includes(searchLower));

        return matchesPrice && matchesDietary && matchesCategory && matchesSearch;
      });

      if (matchingDishes.length > 0) {
        return { ...chef, dishes: matchingDishes };
      }
      return null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  const isFiltering = filters.search || filters.dietary.length > 0 || (filters.categories && filters.categories.length > 0);

  return (
    <div className="min-h-screen bg-gray-50 font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900 flex flex-col">
      <Header 
        cartCount={cartCount} 
        onCartClick={() => setIsCartOpen(true)}
        currentView={currentView}
        onNavigate={(view) => {
          setCurrentView(view);
          if (view === ViewState.HOME) setSelectedChef(null);
        }}
        onAuthClick={() => setIsAuthOpen(true)}
      />

      {currentView === ViewState.HOME && (
        <FilterBar filters={filters} onFilterChange={setFilters} />
      )}

      <main className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8 flex-grow w-full">

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!isFiltering && (
              <>
                <div className="text-center mb-12 py-16 bg-black rounded-3xl text-white shadow-2xl overflow-hidden relative border-b-4 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center mix-blend-overlay"></div>
                  <div className="relative z-10 px-4">
                    <h1 className="text-5xl md:text-7xl font-extrabold mb-6 tracking-tight">
                      MESA
                    </h1>
                    <p className="text-xl md:text-2xl font-light text-gray-300 max-w-2xl mx-auto mb-10 leading-relaxed">
                      La vera cucina casalinga, certificata e autentica.<br/>
                      <span className="text-orange-500 font-bold">Dai nostri cuochi, alla tua tavola.</span>
                    </p>
                    <button className="px-10 py-4 bg-orange-600 text-black font-extrabold rounded-full hover:bg-white hover:text-black transition-all shadow-lg shadow-orange-900/50 transform hover:-translate-y-1">
                      Esplora i Menu
                    </button>
                  </div>
                </div>
                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} />
              </>
            )}

            <div className="mb-6 flex items-center justify-between">
              <h2 className="text-xl font-bold text-gray-900 border-l-4 border-orange-600 pl-3">
                {filteredChefs.length} Chef Disponibili
              </h2>
            </div>

            <div className="space-y-6">
               {filteredChefs.map(chef => (
                 <ChefCard 
                   key={chef.id} 
                   chef={chef} 
                   onAddDish={handleInitiateBooking}
                   onViewProfile={handleViewProfile}
                 />
               ))}
               {filteredChefs.length === 0 && (
                 <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-gray-200">
                   <p className="text-gray-500 text-lg">Nessun piatto trovato con questi filtri.</p>
                   <button 
                    onClick={() => setFilters({ search: '', maxPrice: 50, dietary: [], categories: [] })}
                    className="mt-4 text-orange-600 font-bold hover:underline"
                   >
                     Resetta filtri
                   </button>
                 </div>
               )}
            </div>
          </div>
        )}

        {currentView === ViewState.CHEFS && (
          <MesaChefs 
            chefs={MOCK_CHEFS}
            onViewProfile={handleViewProfile}
          />
        )}

        {currentView === ViewState.CULTURE && (
          <CultureSection />
        )}

        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile 
            chef={selectedChef} 
            onBack={() => setCurrentView(ViewState.HOME)}
            onAddDish={handleInitiateBooking}
          />
        )}

        {currentView === ViewState.AI_MENU_CREATOR && (
          <div className="animate-fade-in">
            <AiMenuCreator />
          </div>
        )}
      </main>

      <Footer />

      <BookingModal 
        isOpen={!!bookingDish}
        onClose={() => setBookingDish(null)}
        dish={bookingDish!}
        chef={getChefForDish(bookingDish)}
        onConfirm={handleConfirmBooking}
      />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        cart={cart}
        onUpdateQuantity={handleUpdateQuantity} 
        onCheckout={handleCheckout}
        onAddDish={handleInitiateBooking}
        availableChefs={MOCK_CHEFS}
      />

      <PaymentModal 
        isOpen={isPaymentOpen} 
        onClose={handlePaymentClose} 
        total={checkoutTotal}
      />

      <AuthModal
        isOpen={isAuthOpen}
        onClose={() => setIsAuthOpen(false)}
      />

      <NotificationToast 
        message={toastMessage}
        isVisible={isToastVisible}
        onClose={() => setIsToastVisible(false)}
      />
    </div>
  );
}

export default App;

import React, { useMemo } from 'react';
import { X, Minus, Plus, ShoppingBag, CalendarClock, Truck, Store, Info, Sparkles } from 'lucide-react';
import { CartItem, Dish, Chef } from '../types';

interface CartDrawerProps {
  isOpen: boolean;
  onClose: () => void;
  cart: CartItem[];
  onUpdateQuantity: (id: string, delta: number) => void;
  onCheckout: (total: number) => void;
  onAddDish: (dish: Dish) => void;
  availableChefs: Chef[];
}

export const CartDrawer: React.FC<CartDrawerProps> = ({ 
  isOpen, 
  onClose, 
  cart, 
  onUpdateQuantity, 
  onCheckout,
  onAddDish,
  availableChefs 
}) => {
  const deliveryFeeBase = 2.50;

  const deliveryTotal = cart.reduce((acc, item) => item.deliveryMode === 'delivery' ? acc + deliveryFeeBase : acc, 0);
  const subtotal = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const total = subtotal + deliveryTotal;

  // Logic to find suggested items: 
  // 1. Identify chefs currently in the cart.
  // 2. Suggest other dishes from these chefs that are NOT in the cart (or just popular ones).
  // 3. If cart is empty, suggest random specials.
  const suggestedDishes = useMemo(() => {
    const activeChefIds = Array.from(new Set(cart.map(item => item.chefId)));

    let candidates: Dish[] = [];

    if (activeChefIds.length > 0) {
      // Suggest dishes from the same chefs
      activeChefIds.forEach(id => {
        const chef = availableChefs.find(c => c.id === id);
        if (chef) {
           candidates.push(...chef.dishes);
        }
      });
    } else {
      // Suggest random dishes if cart is empty
       candidates = availableChefs.flatMap(c => c.dishes);
    }

    // Filter out dishes that are already in the cart (by ID) to encourage variety,
    // or keep them to allow easy re-add with different specs. 
    // Let's filter out exact ID matches to show *new* options.
    const cartDishIds = new Set(cart.map(i => i.id));
    const filtered = candidates.filter(d => !cartDishIds.has(d.id));

    // Shuffle and take 3
    return filtered.sort(() => 0.5 - Math.random()).slice(0, 3);
  }, [cart, availableChefs]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

      <div className="absolute inset-y-0 right-0 max-w-md w-full flex">
        <div className="w-full h-full flex flex-col bg-white shadow-2xl animate-slide-in-right">

          <div className="flex items-center justify-between p-5 border-b border-gray-100 bg-white">
            <h2 className="text-xl font-extrabold text-black flex items-center">
              <ShoppingBag className="w-6 h-6 mr-2 text-orange-600" />
              Le tue Prenotazioni
            </h2>
            <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-500 transition-colors">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-5 bg-gray-50/50">
            {cart.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 space-y-4">
                <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center">
                  <ShoppingBag className="w-10 h-10 text-gray-300" />
                </div>
                <p className="text-center font-medium">Il tuo carrello MESA è vuoto.<br/>Prenota il tuo primo piatto!</p>
              </div>
            ) : (
              <div className="space-y-4">
                {cart.map((item, idx) => (
                  <div key={`${item.id}-${idx}`} className="flex flex-col bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
                    <div className="flex items-start space-x-4">
                      <img src={item.image} alt={item.name} className="w-16 h-16 rounded-xl object-cover" />
                      <div className="flex-1 min-w-0">
                        <div className="flex justify-between items-start">
                           <h3 className="text-sm font-bold text-gray-900 line-clamp-1">{item.name}</h3>
                           {item.deliveryMode === 'delivery' ? (
                             <Truck className="w-4 h-4 text-orange-500" />
                           ) : (
                             <Store className="w-4 h-4 text-gray-400" />
                           )}
                        </div>
                        <p className="text-sm font-medium text-orange-600 mb-1">€ {item.price.toFixed(2)}</p>

                        <div className="flex items-center text-xs text-gray-500 mb-2 bg-gray-50 px-2 py-1 rounded-md w-fit">
                          <CalendarClock className="w-3 h-3 mr-1.5" />
                          <span>{item.scheduledDate} - {item.scheduledTime}</span>
                        </div>

                        {/* Customizations display */}
                        {(item.preferences.spiceLevel > 0 || item.preferences.notes) && (
                          <div className="text-[10px] text-gray-400 bg-gray-50 p-2 rounded mb-2 space-y-1">
                            {item.preferences.spiceLevel > 0 && <div>🌶️ Piccantezza: {item.preferences.spiceLevel}/3</div>}
                            {item.preferences.notes && <div className="italic">"{item.preferences.notes}"</div>}
                          </div>
                        )}

                        <div className="flex items-center justify-between mt-2">
                          <div className="flex items-center space-x-3 bg-gray-50 rounded-lg p-1">
                            <button 
                              onClick={() => onUpdateQuantity(item.id, -1)}
                              className="w-6 h-6 rounded-md bg-white border border-gray-200 flex items-center justify-center text-gray-600 hover:text-orange-600 shadow-sm"
                            >
                              <Minus className="w-3 h-3" />
                            </button>
                            <span className="text-sm font-bold w-4 text-center">{item.quantity}</span>
                            <button 
                              onClick={() => onUpdateQuantity(item.id, 1)}
                              className="w-6 h-6 rounded-md bg-white border border-gray-200 flex items-center justify-center text-gray-600 hover:text-orange-600 shadow-sm"
                            >
                              <Plus className="w-3 h-3" />
                            </button>
                          </div>
                          <div className="font-bold text-gray-900 text-sm">
                            € {(item.price * item.quantity).toFixed(2)}
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}

            {/* Suggested Dishes Section */}
            {suggestedDishes.length > 0 && (
              <div className="mt-8 pt-6 border-t border-gray-200">
                <h3 className="text-sm font-bold text-gray-900 mb-4 flex items-center">
                  <Sparkles className="w-4 h-4 mr-2 text-yellow-500" />
                  Completa il tuo ordine
                </h3>
                <div className="space-y-3">
                  {suggestedDishes.map((dish) => (
                    <div key={dish.id} className="flex items-center bg-white p-2 rounded-xl border border-gray-100 hover:border-orange-200 transition-colors">
                      <img src={dish.image} alt={dish.name} className="w-12 h-12 rounded-lg object-cover mr-3" />
                      <div className="flex-1 min-w-0">
                        <h4 className="text-xs font-bold text-gray-900 truncate">{dish.name}</h4>
                        <p className="text-xs text-orange-600 font-medium">€ {dish.price.toFixed(2)}</p>
                      </div>
                      <button 
                        onClick={() => onAddDish(dish)}
                        className="p-2 bg-gray-100 hover:bg-orange-600 hover:text-white rounded-lg text-gray-600 transition-colors ml-2"
                      >
                        <Plus className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {cart.length > 0 && (
            <div className="border-t border-gray-100 p-6 bg-white shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
              <div className="space-y-3 mb-6">
                <div className="flex justify-between text-sm text-gray-600 font-medium">
                  <span>Subtotale</span>
                  <span>€ {subtotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-sm text-gray-600 font-medium">
                  <span className="flex items-center">
                    Costi di Consegna
                    <Info className="w-3 h-3 ml-1 text-gray-400" />
                  </span>
                  <span>€ {deliveryTotal.toFixed(2)}</span>
                </div>
                <div className="flex justify-between text-xl font-extrabold text-gray-900 pt-3 border-t border-dashed border-gray-200">
                  <span>Totale</span>
                  <span className="text-orange-600">€ {total.toFixed(2)}</span>
                </div>
              </div>
              <button 
                onClick={() => onCheckout(total)}
                className="w-full py-4 bg-black hover:bg-gray-900 text-white font-bold text-lg rounded-2xl shadow-xl hover:shadow-2xl transition-all active:scale-95 flex items-center justify-center space-x-2"
              >
                <span>Vai al Pagamento</span>
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

