import { ViewState } from '../types';

interface BottomNavProps {
  currentView: ViewState;
  onNavigate: (view: ViewState) => void;
}

export const BottomNav: React.FC<BottomNavProps> = ({ currentView, onNavigate }) => {
  const navItems = [
    { view: ViewState.HOME, label: 'Home', icon: Home },
    { view: ViewState.CHEFS, label: 'Cuochi', icon: ChefHat },
    { view: ViewState.AI_MENU_CREATOR, label: 'Chef AI', icon: PlusCircle },
    { view: ViewState.FAVORITES, label: 'Preferiti', icon: Heart },
    { view: ViewState.CULTURE, label: 'Cultura', icon: Globe },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-50 bg-black/90 backdrop-blur-lg border-t border-white/10 px-2 pb-safe-area-inset-bottom md:hidden shadow-[0_-10px_20px_-5px_rgba(0,0,0,0.3)]">
      <div className="flex justify-around items-center h-16 max-w-md mx-auto">
        {navItems.map((item) => {
          const Icon = item.icon;
          const isActive = currentView === item.view;

          return (
            <button
              key={item.view}
              onClick={() => onNavigate(item.view)}
              className={`flex flex-col items-center justify-center w-full h-full transition-all duration-300 transform ${
                isActive ? 'text-orange-500 scale-110' : 'text-gray-500 hover:text-gray-300'
              }`}
            >
              <div className={`relative ${isActive ? 'mb-0' : ''}`}>
                <Icon className={`w-6 h-6 ${isActive ? 'fill-orange-500/10' : ''}`} />
                {isActive && (
                  <span className="absolute -top-1 -right-1 w-2 h-2 bg-orange-500 rounded-full animate-pulse" />
                )}
              </div>
              <span className={`text-[10px] font-black uppercase tracking-tighter mt-1 ${isActive ? 'opacity-100' : 'opacity-0 h-0 overflow-hidden'}`}>
                {item.label}
              </span>
            </button>
          );
        })}
      </div>
    </nav>
  );
};

