              <button 
                onClick={() => onNavigate(ViewState.AI_MENU_CREATOR)}
                className={`flex items-center space-x-1 text-sm font-bold uppercase tracking-wide transition-colors ${currentView === ViewState.AI_MENU_CREATOR ? 'bg-orange-600 text-black px-3 py-1.5 rounded-full hover:bg-orange-500' : 'text-gray-400 hover:text-orange-500'}`}
              >
                <PlusCircle className="w-4 h-4" />
                <span>Chef AI</span>
              </button>
            </div>

            {/* Desktop only Icons (Bottom nav handles mobile) */}
            <button 
              onClick={() => onNavigate(ViewState.FAVORITES)}
              className={`hidden md:block p-2 rounded-full transition-colors ${currentView === ViewState.FAVORITES ? 'text-red-500 bg-white/10' : 'text-gray-400 hover:text-white hover:bg-white/10'}`}
              title="Preferiti"
            >
              <Heart className={`w-5 h-5 ${currentView === ViewState.FAVORITES ? 'fill-current' : ''}`} />
            </button>

            <button 
              onClick={onAuthClick}
              className="p-2 text-gray-400 hover:text-white hover:bg-white/10 rounded-full transition-colors"
            >
              <User className="w-5 h-5" />
            </button>

            <button 
              className="relative p-3 bg-white hover:bg-gray-200 rounded-full text-black transition-colors shadow-md transform active:scale-95"
              onClick={onCartClick}
            >
              <ShoppingBag className="w-5 h-5" />
              {cartCount > 0 && (
                <span className="absolute -top-1 -right-1 inline-flex items-center justify-center w-5 h-5 text-xs font-bold leading-none text-white bg-orange-600 rounded-full border-2 border-black">
                  {cartCount}
                </span>
              )}
            </button>
          </div>
        </div>
      </div>
    </header>
  );
};

