  name: string;
}

export interface Review {
  id: string;
  author: string;
  rating: number;
  comment: string;
  date: string;
}

export interface Dish {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  chefId: string;
  tags: string[]; // Used for categories like 'Carne', 'Pesce', 'Piccante'
  calories?: number;
  dietary?: ('Vegetarian' | 'Vegan' | 'Gluten Free' | 'Lactose Free')[];
  ingredients?: string[];
  preparation?: string;
}

