  id: string;
  name: string;
  nationality: string; // Emoji flag e.g. "🇮🇹"
  bio: string;
  fullBio?: string;
  avatar: string;
  rating: number;
  location: string;
  distance: number; // km
  specialties: string[];
  availability: string[]; // Text description
