import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { FavoritesSection } from './components/FavoritesSection';
import { Footer } from './components/Footer';
import { NotificationToast } from './components/NotificationToast';
import { BottomNav } from './components/BottomNav';
import { InfoPage } from './components/InfoPage';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef } from './types';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);

  // Modals State
  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  // Notification State
  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  // Gestione navigazione fluida
  const navigateTo = (view: ViewState) => {
    setCurrentView(view);
    if (view !== ViewState.CHEF_PROFILE) {
      setSelectedChef(null);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const handleToggleFavorite = (dishId: string) => {
    setFavorites(prev => {
      if (prev.includes(dishId)) {
        showNotification("Rimosso dai preferiti");
        return prev.filter(id => id !== dishId);
      } else {
        showNotification("Aggiunto ai preferiti ❤️");
        return [...prev, dishId];
      }
    });
  };

  const handleInitiateBooking = (dish: Dish) => {
    setBookingDish(dish);
  };

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;

    setCart(prev => {
      const existingIndex = prev.findIndex(item => 
        item.id === bookingDish.id && 
        item.scheduledDate === date && 
        item.scheduledTime === time &&
        item.deliveryMode === deliveryMode &&
        JSON.stringify(item.preferences) === JSON.stringify(preferences)
      );

      if (existingIndex >= 0) {
        const newCart = [...prev];
        newCart[existingIndex] = {
          ...newCart[existingIndex],
          quantity: newCart[existingIndex].quantity + 1
        };
        return newCart;
      }

      return [...prev, { 
        ...bookingDish, 
        quantity: 1, 
        scheduledDate: date, 
        scheduledTime: time,
        deliveryMode,
        preferences
      }];
    });

    setBookingDish(null);
    showNotification("Piatto aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => {
      return prev.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : null;
        }
        return item;
      }).filter(Boolean) as CartItem[];
    });
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentClose = () => {
    setIsPaymentOpen(false);
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  const getChefForDish = (dish: Dish | null) => {
    if (!dish) return undefined;
    return MOCK_CHEFS.find(c => c.id === dish.chefId);
  };

  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));
        const matchesCategory = (filters.categories || []).length === 0 ||
          (filters.categories || []).every(cat => dish.tags?.includes(cat));

        const searchLower = filters.search.toLowerCase();
        const matchesSearch = !filters.search || 
          dish.name.toLowerCase().includes(searchLower) ||
          dish.description.toLowerCase().includes(searchLower) ||
          chef.name.toLowerCase().includes(searchLower) ||
          dish.tags.some(tag => tag.toLowerCase().includes(searchLower));

        return matchesPrice && matchesDietary && matchesCategory && matchesSearch;
      });

      if (matchingDishes.length > 0) {
        return { ...chef, dishes: matchingDishes };
      }
      return null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  const isFiltering = filters.search || filters.dietary.length > 0 || (filters.categories && filters.categories.length > 0) || filters.maxPrice < 50;

  // Render content based on current view
  const renderMainContent = () => {
    switch (currentView) {
      case ViewState.HOME:
        return (
          <div className="animate-fade-in">
            {!isFiltering && (
              <>
                <div className="text-center mb-10 py-12 bg-black rounded-[2.5rem] text-white shadow-2xl overflow-hidden relative border-b-8 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center mix-blend-overlay"></div>
                  <div className="relative z-10 px-6">
                    <h1 className="text-6xl md:text-8xl font-black mb-4 tracking-tighter">
                      MESA
                    </h1>
                    <p className="text-lg md:text-xl font-medium text-gray-300 max-w-xl mx-auto mb-8 leading-tight">
                      Cucina casalinga, <span className="text-orange-500 font-black">autentica e vicina.</span>
                    </p>
                    <button 
                      onClick={() => window.scrollTo({ top: 600, behavior: 'smooth' })}
                      className="px-8 py-4 bg-white text-black font-black uppercase tracking-widest rounded-2xl hover:bg-orange-600 hover:text-white transition-all transform hover:-translate-y-1 active:scale-95"
                    >
                      Ordina ora
                    </button>
                  </div>
                </div>
                <DailySpecials 
                  chefs={MOCK_CHEFS} 
                  onAddDish={handleInitiateBooking} 
                  favorites={favorites}
                  onToggleFavorite={handleToggleFavorite}
                />
              </>
            )}

            <div className="mb-8 flex items-center justify-between px-1">
              <h2 className="text-xl font-black text-gray-900 flex items-center">
                <span className="w-1.5 h-6 bg-orange-600 mr-3 rounded-full"></span>
                {isFiltering ? 'Risultati ricerca' : 'Chef nella tua zona'}
              </h2>
              <span className="text-xs font-bold text-gray-400">{filteredChefs.length} cuochi trovati</span>
            </div>

            <div className="space-y-6">
               {filteredChefs.map(chef => (
                 <ChefCard 
                   key={chef.id} 
                   chef={chef} 
                   onAddDish={handleInitiateBooking}
                   onViewProfile={handleViewProfile}
                   favorites={favorites}
                   onToggleFavorite={handleToggleFavorite}
                 />
               ))}
               {filteredChefs.length === 0 && (
                 <div className="text-center py-24 bg-gray-50 rounded-[3rem] border-4 border-dashed border-gray-100">
                   <p className="text-gray-400 font-bold text-lg">Nessun piatto trovato.</p>
                   <button 
                    onClick={() => setFilters({ search: '', maxPrice: 50, dietary: [], categories: [] })}
                    className="mt-6 px-6 py-2 bg-black text-white rounded-xl font-black text-xs uppercase tracking-widest active:scale-95 transition-transform"
                   >
                     Resetta tutto
                   </button>
                 </div>
               )}
            </div>
          </div>
        );
      case ViewState.CHEFS:
        return <MesaChefs chefs={MOCK_CHEFS} onViewProfile={handleViewProfile} />;
      case ViewState.CULTURE:
        return <CultureSection />;
      case ViewState.FAVORITES:
        return <FavoritesSection favorites={favorites} chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} onToggleFavorite={handleToggleFavorite} />;
      case ViewState.CHEF_PROFILE:
        return selectedChef ? <ChefProfile chef={selectedChef} onBack={() => navigateTo(ViewState.HOME)} onAddDish={handleInitiateBooking} favorites={favorites} onToggleFavorite={handleToggleFavorite} /> : null;
      case ViewState.AI_MENU_CREATOR:
        return <AiMenuCreator />;
      case ViewState.ABOUT:
      case ViewState.SAFETY:
      case ViewState.TERMS:
      case ViewState.PRIVACY:
      case ViewState.HELP:
      case ViewState.BECOME_CHEF:
        return <InfoPage view={currentView} onBack={() => navigateTo(ViewState.HOME)} />;
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900 flex flex-col pb-20 md:pb-0">
      <Header 
        cartCount={cartCount} 
        onCartClick={() => setIsCartOpen(true)}
        currentView={currentView}
        onNavigate={navigateTo}
        onAuthClick={() => setIsAuthOpen(true)}
      />

      {currentView === ViewState.HOME && (
        <FilterBar filters={filters} onFilterChange={setFilters} />
      )}

      <main className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full mb-8">
        {renderMainContent()}
      </main>

      <Footer onNavigate={navigateTo} />

      <BottomNav currentView={currentView} onNavigate={navigateTo} />

      <BookingModal 
        isOpen={!!bookingDish}
        onClose={() => setBookingDish(null)}
        dish={bookingDish!}
        chef={getChefForDish(bookingDish)}
        onConfirm={handleConfirmBooking}
      />

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        cart={cart}
        onUpdateQuantity={handleUpdateQuantity} 
        onCheckout={handleCheckout}
        onAddDish={handleInitiateBooking}
        availableChefs={MOCK_CHEFS}
      />

      <PaymentModal 
        isOpen={isPaymentOpen} 
        onClose={handlePaymentClose} 
        total={checkoutTotal}
      />

      <AuthModal
        isOpen={isAuthOpen}
        onClose={() => setIsAuthOpen(false)}
      />

      <NotificationToast 
        message={toastMessage}
        isVisible={isToastVisible}
        onClose={() => setIsToastVisible(false)}
      />
    </div>
  );
}

export default App;

