import { PackageCheck, Utensils, Bike, CheckCircle, Clock, MapPin, Phone, MessageSquare, ChevronRight } from 'lucide-react';
import { Order, OrderStatus } from '../types';

interface OrderTrackingProps {
  order: Order;
  onBack: () => void;
}

export const OrderTracking: React.FC<OrderTrackingProps> = ({ order, onBack }) => {
  const steps: { status: OrderStatus; label: string; icon: any; description: string }[] = [
    { status: 'PLACED', label: 'Ricevuto', icon: PackageCheck, description: 'Lo chef ha accettato il tuo ordine' },
    { status: 'PREPARING', label: 'In Cucina', icon: Utensils, description: 'Ingredienti freschi in preparazione' },
    { status: 'READY', label: 'Pronto', icon: CheckCircle, description: 'Il tuo piatto è pronto per il ritiro' },
    { status: 'DELIVERING', label: 'In Consegna', icon: Bike, description: 'Il rider è per strada' },
    { status: 'COMPLETED', label: 'Consegnato', icon: HeartIcon, description: 'Buon appetito!' }
  ];

  // Filtriamo gli step in base alla modalità di consegna
  const activeSteps = order.deliveryMode === 'pickup' 
    ? steps.filter(s => s.status !== 'DELIVERING')
    : steps;

  const currentStepIndex = activeSteps.findIndex(s => s.status === order.status);

  return (
    <div className="animate-fade-in space-y-6">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-2xl font-black text-gray-900">Tracciamento Ordine</h2>
        <span className="text-xs font-black text-orange-600 bg-orange-50 px-3 py-1 rounded-full border border-orange-100 uppercase">
          #{order.id.split('-')[0]}
        </span>
      </div>

      {/* Main Tracking Card */}
      <div className="bg-white rounded-[2.5rem] shadow-xl border border-gray-100 overflow-hidden">
        <div className="bg-black p-8 text-white relative">
          <div className="absolute top-0 right-0 w-32 h-32 bg-orange-600 rounded-full opacity-20 blur-3xl -mr-16 -mt-16"></div>
          <div className="flex justify-between items-end relative z-10">
            <div>
              <p className="text-orange-500 text-xs font-black uppercase tracking-widest mb-1">Arrivo Stimato</p>
              <h3 className="text-4xl font-black">{order.estimatedTime}</h3>
            </div>
            <div className="text-right">
              <p className="text-gray-400 text-xs font-black uppercase tracking-widest mb-1">Stato</p>
              <p className="text-lg font-bold">{activeSteps[currentStepIndex]?.label}</p>
            </div>
          </div>
        </div>

        <div className="p-8">
          {/* Progress Bar */}
          <div className="relative mb-12">
            <div className="absolute top-5 left-0 w-full h-1 bg-gray-100"></div>
            <div 
              className="absolute top-5 left-0 h-1 bg-orange-500 transition-all duration-1000"
              style={{ width: `${(currentStepIndex / (activeSteps.length - 1)) * 100}%` }}
            ></div>

            <div className="flex justify-between relative z-10">
              {activeSteps.map((step, idx) => {
                const Icon = step.icon;
                const isCompleted = idx <= currentStepIndex;
                const isActive = idx === currentStepIndex;

                return (
                  <div key={step.status} className="flex flex-col items-center">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-500 ${
                      isCompleted ? 'bg-orange-600 text-white shadow-lg shadow-orange-200' : 'bg-white border-2 border-gray-100 text-gray-300'
                    } ${isActive ? 'scale-125 ring-4 ring-orange-50' : ''}`}>
                      <Icon className="w-5 h-5" />
                    </div>
                    <span className={`mt-3 text-[10px] font-black uppercase tracking-tighter ${isCompleted ? 'text-gray-900' : 'text-gray-400'}`}>
                      {step.label}
                    </span>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="bg-gray-50 rounded-3xl p-6 flex items-start gap-4 border border-gray-100">
            <div className="bg-white p-3 rounded-2xl shadow-sm">
              <Clock className="w-6 h-6 text-orange-600 animate-pulse" />
            </div>
            <div>
              <h4 className="font-bold text-gray-900">{activeSteps[currentStepIndex]?.label}</h4>
              <p className="text-sm text-gray-500">{activeSteps[currentStepIndex]?.description}</p>
            </div>
          </div>
        </div>
      </div>

      {/* Chef & Help Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-sm flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center font-black text-orange-600 overflow-hidden border-2 border-white shadow-md">
              <span className="text-xl">👨‍🍳</span>
            </div>
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Il tuo Chef</p>
              <h4 className="font-bold text-gray-900">{order.chefName}</h4>
            </div>
          </div>
          <div className="flex gap-2">
            <button className="p-3 bg-gray-50 rounded-xl text-gray-600 hover:bg-orange-50 hover:text-orange-600 transition-colors">
              <MessageSquare className="w-5 h-5" />
            </button>
            <button className="p-3 bg-gray-50 rounded-xl text-gray-600 hover:bg-orange-50 hover:text-orange-600 transition-colors">
              <Phone className="w-5 h-5" />
            </button>
          </div>
        </div>

        <div className="bg-white rounded-[2rem] p-6 border border-gray-100 shadow-sm flex items-center justify-between">
           <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-orange-50 rounded-full flex items-center justify-center">
              <MapPin className="w-6 h-6 text-orange-600" />
            </div>
            <div>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Destinazione</p>
              <h4 className="font-bold text-gray-900">{order.deliveryMode === 'delivery' ? 'Il tuo indirizzo' : 'Punto di ritiro Chef'}</h4>
            </div>
          </div>
          <button className="text-orange-600 font-black text-xs uppercase tracking-widest flex items-center gap-1">
            Mappa <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>

      <button 
        onClick={onBack}
        className="w-full py-4 bg-gray-100 text-gray-600 font-black uppercase tracking-widest text-xs rounded-2xl hover:bg-gray-200 transition-colors"
      >
        Torna ai miei ordini
      </button>
    </div>
  );
};

