import { ShareModal } from './components/ShareModal';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef, Order, OrderStatus } from './types';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);

  // Orders State
  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [reviewOrder, setReviewOrder] = useState<Order | null>(null);

  // Modals State
  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [isShareOpen, setIsShareOpen] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  // Notification State
  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  // Simulazione avanzamento ordini
  useEffect(() => {
    const activeOrders = orders.filter(o => o.status !== 'COMPLETED');
    if (activeOrders.length === 0) return;

    const timer = setInterval(() => {
      setOrders(prevOrders => {
        return prevOrders.map(order => {
          if (order.status === 'COMPLETED') return order;

          const statusFlow: OrderStatus[] = order.deliveryMode === 'pickup' 
            ? ['PLACED', 'PREPARING', 'READY', 'COMPLETED']
            : ['PLACED', 'PREPARING', 'READY', 'DELIVERING', 'COMPLETED'];

          const currentIndex = statusFlow.indexOf(order.status);
          if (currentIndex < statusFlow.length - 1) {
            const nextStatus = statusFlow[currentIndex + 1];

            // Notifica
            if (order.id === orders[0].id) {
              const messages = {
                'PREPARING': `👨‍🍳 ${order.chefName} ha iniziato a cucinare!`,
                'READY': `✅ Il tuo piatto è pronto!`,
                'DELIVERING': `🛵 Il rider è partito con il tuo ordine!`,
                'COMPLETED': `🎉 Ordine completato! Buon appetito!`
              };
              showNotification(messages[nextStatus as keyof typeof messages] || "Stato ordine aggiornato");

              if (nextStatus === 'COMPLETED') {
                setTimeout(() => setReviewOrder(order), 2000);
              }
            }

            return { ...order, status: nextStatus };
          }
          return order;
        });
      });
    }, 15000);

    return () => clearInterval(timer);
  }, [orders]);

  const navigateTo = (view: ViewState) => {
    setCurrentView(view);
    if (view !== ViewState.CHEF_PROFILE) setSelectedChef(null);
    if (view !== ViewState.ORDERS) setSelectedOrder(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const handleToggleFavorite = (dishId: string) => {
    setFavorites(prev => {
      if (prev.includes(dishId)) {
        showNotification("Rimosso dai preferiti");
        return prev.filter(id => id !== dishId);
      } else {
        showNotification("Aggiunto ai preferiti ❤️");
        return [...prev, dishId];
      }
    });
  };

  const handleInitiateBooking = (dish: Dish) => setBookingDish(dish);

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;
    setCart(prev => [...prev, { ...bookingDish, quantity: 1, scheduledDate: date, scheduledTime: time, deliveryMode, preferences }]);
    setBookingDish(null);
    showNotification("Piatto aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(i => i.quantity > 0));
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentSuccess = () => {
    const firstChefId = cart[0]?.chefId || 'c1';
    const chefName = MOCK_CHEFS.find(c => c.id === firstChefId)?.name || 'Chef';
    const newOrder: Order = {
      id: `ORDER-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      items: [...cart],
      total: checkoutTotal,
      status: 'PLACED',
      timestamp: new Date(),
      chefId: firstChefId,
      chefName: chefName,
      deliveryMode: cart[0]?.deliveryMode || 'pickup',
      estimatedTime: '20:45'
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setSelectedOrder(newOrder);
    setCurrentView(ViewState.ORDERS);
    showNotification("Ordine ricevuto! Seguilo live.");
  };

  const handleReviewSubmit = (rating: number, comment: string) => {
    if (!reviewOrder) return;
    setOrders(prev => prev.map(o => o.id === reviewOrder.id ? { ...o, isReviewed: true } : o));
    setReviewOrder(null);
    showNotification("Grazie per la tua recensione! ⭐");
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const activeOrdersCount = orders.filter(o => o.status !== 'COMPLETED').length;

  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));
        const searchLower = filters.search.toLowerCase();
        return matchesPrice && matchesDietary && (!filters.search || dish.name.toLowerCase().includes(searchLower) || chef.name.toLowerCase().includes(searchLower));
      });
      return matchingDishes.length > 0 ? { ...chef, dishes: matchingDishes } : null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900 flex flex-col pb-20 md:pb-0">
      <Header 
        cartCount={cartCount} 
        orderCount={activeOrdersCount} 
        onCartClick={() => setIsCartOpen(true)} 
        currentView={currentView} 
        onNavigate={navigateTo} 
        onAuthClick={() => setIsAuthOpen(true)}
        onShareClick={() => setIsShareOpen(true)}
      />

      {currentView === ViewState.HOME && <FilterBar filters={filters} onFilterChange={setFilters} />}

      <main className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full mb-8">
        {currentView === ViewState.HOME && !filters.search && <ActivityFeed />}

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!filters.search && (
              <>
                <div className="text-center mb-12 py-10 bg-black rounded-[3rem] text-white shadow-2xl relative overflow-hidden border-b-8 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center"></div>
                  <div className="relative z-10 px-6">
                    <h1 className="text-5xl md:text-7xl font-black mb-2 tracking-tighter italic">MESA</h1>
                    <p className="text-lg font-bold text-orange-500 uppercase tracking-widest mb-6">Home Cooked. Hand Picked.</p>
                    <div className="flex justify-center space-x-4">
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Cuochi Attivi</p>
                          <p className="text-xl font-black">124</p>
                       </div>
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Piatti Oggi</p>
                          <p className="text-xl font-black">450+</p>
                       </div>
                    </div>
                  </div>
                </div>
                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
              </>
            )}
            <div className="mb-8 flex items-center justify-between">
              <h2 className="text-2xl font-black text-gray-900">Chef Vicini a Te</h2>
            </div>
            <div className="space-y-10">
               {filteredChefs.map(chef => (
                 <ChefCard key={chef.id} chef={chef} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
               ))}
            </div>
          </div>
        )}

        {currentView === ViewState.CHEFS && <MesaChefs chefs={MOCK_CHEFS} onViewProfile={handleViewProfile} />}
        {currentView === ViewState.CULTURE && <CultureSection />}
        {currentView === ViewState.FAVORITES && <FavoritesSection favorites={favorites} chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} onToggleFavorite={handleToggleFavorite} />}
        {currentView === ViewState.ORDERS && (
          selectedOrder 
            ? <OrderTracking order={orders.find(o => o.id === selectedOrder.id) || selectedOrder} onBack={() => setSelectedOrder(null)} />
            : (
              <div className="animate-fade-in space-y-6">
                <h2 className="text-3xl font-black text-gray-900 mb-8 tracking-tight">I Miei Ordini</h2>
                {orders.length === 0 ? <p className="text-gray-400 font-bold py-20 text-center bg-gray-50 rounded-[3rem]">Nessun ordine trovato.</p> : orders.map(order => (
                  <div key={order.id} onClick={() => setSelectedOrder(order)} className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm hover:shadow-xl transition-all cursor-pointer flex justify-between items-center group">
                    <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">#{order.id.split('-')[0]}</p>
                      <h4 className="font-bold text-xl text-gray-900">{order.chefName}</h4>
                      <p className="text-xs text-gray-500">{order.items.length} piatti • € {order.total.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center space-x-4">
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${order.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700 animate-pulse'}`}>{order.status}</span>
                      {order.status === 'COMPLETED' && !order.isReviewed && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); setReviewOrder(order); }}
                          className="bg-orange-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-black transition-colors"
                        >Recensisci</button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )
        )}
        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile 
            chef={selectedChef} 
            onBack={() => navigateTo(ViewState.HOME)} 
            onAddDish={handleInitiateBooking} 
            favorites={favorites} 
            onToggleFavorite={handleToggleFavorite}
            onNavigateToCulture={() => navigateTo(ViewState.CULTURE)}
          />
        )}
        {currentView === ViewState.AI_MENU_CREATOR && <AiMenuCreator />}
        {[ViewState.ABOUT, ViewState.SAFETY, ViewState.BECOME_CHEF, ViewState.HELP, ViewState.TERMS, ViewState.PRIVACY].includes(currentView) && (
          <InfoPage view={currentView} onBack={() => navigateTo(ViewState.HOME)} />
        )}
      </main>

      <Footer onNavigate={navigateTo} />
      <BottomNav currentView={currentView} onNavigate={navigateTo} />

      <BookingModal isOpen={!!bookingDish} onClose={() => setBookingDish(null)} dish={bookingDish!} chef={MOCK_CHEFS.find(c => c.id === bookingDish?.chefId)} onConfirm={handleConfirmBooking} />
      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} onUpdateQuantity={handleUpdateQuantity} onCheckout={handleCheckout} onAddDish={handleInitiateBooking} availableChefs={MOCK_CHEFS} />
      <PaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} total={checkoutTotal} onSuccess={handlePaymentSuccess} />
      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} />
      <OrderReviewModal isOpen={!!reviewOrder} onClose={() => setReviewOrder(null)} order={reviewOrder!} onSubmit={handleReviewSubmit} />
      <ShareModal isOpen={isShareOpen} onClose={() => setIsShareOpen(false)} />
      <NotificationToast message={toastMessage} isVisible={isToastVisible} onClose={() => setIsToastVisible(false)} />
    </div>
  );
}

export default App;

import React, { useState, useEffect } from 'react';
import { X, Copy, Check, Share2, QrCode, Mail, MessageCircle, Twitter, Globe, ExternalLink } from 'lucide-react';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose }) => {
  const [copied, setCopied] = useState(false);
  const [currentUrl, setCurrentUrl] = useState('');

  useEffect(() => {
    if (typeof window !== 'undefined') {
      setCurrentUrl(window.location.href);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleCopy = () => {
    navigator.clipboard.writeText(currentUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleNativeShare = () => {
    if (navigator.share) {
      navigator.share({
        title: 'MESA - App di Cucina Casalinga (Demo)',
        text: 'Guarda questa anteprima dell\'app MESA per la prenotazione di piatti da cuochi casalinghi!',
        url: currentUrl,
      }).catch(() => {
        handleCopy();
      });
    } else {
      handleCopy();
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/90 backdrop-blur-md animate-fade-in" onClick={onClose} />

      <div className="relative bg-white w-full max-w-md rounded-[3rem] shadow-2xl overflow-hidden animate-fade-in-up">
        {/* Header Decor */}
        <div className="h-40 bg-gradient-to-br from-orange-500 via-orange-600 to-black relative flex flex-col items-center justify-center overflow-hidden">
          <div className="absolute inset-0 opacity-20 bg-[url('https://www.transparenttextures.com/patterns/food.png')]"></div>
          <div className="relative z-10 flex flex-col items-center">
             <div className="bg-white/20 backdrop-blur-md p-4 rounded-3xl mb-3 border border-white/30">
                <QrCode className="w-12 h-12 text-white" />
             </div>
             <span className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Preview Link Generator</span>
          </div>

          <button 
            onClick={onClose}
            className="absolute top-6 right-6 p-2 bg-white/10 hover:bg-white/20 text-white rounded-full backdrop-blur-md transition-colors z-20"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-8 text-center">
          <div className="inline-flex items-center gap-2 px-3 py-1 bg-orange-100 text-orange-700 rounded-full text-[9px] font-black uppercase tracking-widest mb-4">
            <Globe className="w-3 h-3" />
            Pronto per la condivisione
          </div>

          <h2 className="text-3xl font-black text-gray-900 mb-2 tracking-tighter italic leading-none">Accesso alla Demo</h2>
          <p className="text-gray-500 text-sm font-medium mb-8 px-4">
            Invia questo link ai tuoi partner o investitori per mostrare il prototipo funzionale di <span className="text-orange-600 font-bold">MESA</span>.
          </p>

          {/* Real Link Box */}
          <div className="bg-gray-50 border-2 border-gray-100 rounded-[2rem] p-5 mb-8 flex flex-col items-center gap-4 group hover:border-orange-300 transition-all">
            <div className="w-full text-center overflow-hidden">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Il tuo URL unico di test</p>
              <p className="text-xs font-bold text-orange-600 break-all bg-white p-3 rounded-xl border border-gray-100 shadow-sm">
                {currentUrl}
              </p>
            </div>

            <div className="flex w-full gap-3">
              <button 
                onClick={handleCopy}
                className={`flex-1 flex items-center justify-center gap-2 py-3.5 rounded-2xl font-black uppercase tracking-widest text-[10px] transition-all shadow-lg active:scale-95 ${
                  copied ? 'bg-green-500 text-white' : 'bg-black text-white hover:bg-orange-600'
                }`}
              >
                {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                {copied ? 'Copiato!' : 'Copia Link'}
              </button>

              <button 
                onClick={() => window.open(currentUrl, '_blank')}
                className="p-3.5 bg-gray-100 text-gray-600 rounded-2xl hover:bg-gray-200 transition-colors shadow-sm"
                title="Apri in nuova finestra"
              >
                <ExternalLink className="w-5 h-5" />
              </button>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4 mb-8">
            <button onClick={handleNativeShare} className="flex flex-col items-center gap-2 group">
              <div className="w-12 h-12 bg-green-100 rounded-2xl flex items-center justify-center text-green-600 group-hover:scale-110 transition-transform shadow-sm">
                <MessageCircle className="w-6 h-6" />
              </div>
              <span className="text-[9px] font-black uppercase tracking-widest text-gray-400">WhatsApp</span>
            </button>
            <button onClick={handleNativeShare} className="flex flex-col items-center gap-2 group">
              <div className="w-12 h-12 bg-blue-100 rounded-2xl flex items-center justify-center text-blue-600 group-hover:scale-110 transition-transform shadow-sm">
                <Twitter className="w-6 h-6" />
              </div>
              <span className="text-[9px] font-black uppercase tracking-widest text-gray-400">Twitter</span>
            </button>
            <button onClick={handleNativeShare} className="flex flex-col items-center gap-2 group">
              <div className="w-12 h-12 bg-orange-100 rounded-2xl flex items-center justify-center text-orange-600 group-hover:scale-110 transition-transform shadow-sm">
                <Mail className="w-6 h-6" />
              </div>
              <span className="text-[9px] font-black uppercase tracking-widest text-gray-400">Email</span>
            </button>
          </div>

          <div className="pt-6 border-t border-gray-100 flex items-center justify-center gap-6">
             <div className="flex items-center gap-2">
               <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
               <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">Server Live</span>
             </div>
             <div className="flex items-center gap-2">
               <div className="flex -space-x-2">
                 {[1,2,3].map(i => (
                   <div key={i} className="w-4 h-4 rounded-full border border-white bg-gray-200 overflow-hidden">
                     <img src={`https://i.pravatar.cc/100?img=${i+10}`} alt="user" />
                   </div>
                 ))}
               </div>
               <span className="text-[9px] font-black text-gray-400 uppercase tracking-widest">3 Test Attivi</span>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { FavoritesSection } from './components/FavoritesSection';
import { Footer } from './components/Footer';
import { NotificationToast } from './components/NotificationToast';
import { BottomNav } from './components/BottomNav';
import { InfoPage } from './components/InfoPage';
import { OrderTracking } from './components/OrderTracking';
import { ActivityFeed } from './components/ActivityFeed';
import { OrderReviewModal } from './components/OrderReviewModal';
import { ShareModal } from './components/ShareModal';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef, Order, OrderStatus } from './types';
import { Share2, QrCode, Copy, Check, Globe } from 'lucide-react';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);

  // Orders State
  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [reviewOrder, setReviewOrder] = useState<Order | null>(null);

  // Modals State
  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [isShareOpen, setIsShareOpen] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  // Notification State
  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);

  // Filter State
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  const currentUrl = typeof window !== 'undefined' ? window.location.href : '';

  // Simulazione avanzamento ordini
  useEffect(() => {
    const activeOrders = orders.filter(o => o.status !== 'COMPLETED');
    if (activeOrders.length === 0) return;

    const timer = setInterval(() => {
      setOrders(prevOrders => {
        return prevOrders.map(order => {
          if (order.status === 'COMPLETED') return order;

          const statusFlow: OrderStatus[] = order.deliveryMode === 'pickup' 
            ? ['PLACED', 'PREPARING', 'READY', 'COMPLETED']
            : ['PLACED', 'PREPARING', 'READY', 'DELIVERING', 'COMPLETED'];

          const currentIndex = statusFlow.indexOf(order.status);
          if (currentIndex < statusFlow.length - 1) {
            const nextStatus = statusFlow[currentIndex + 1];

            // Notifica
            if (order.id === orders[0].id) {
              const messages = {
                'PREPARING': `👨‍🍳 ${order.chefName} ha iniziato a cucinare!`,
                'READY': `✅ Il tuo piatto è pronto!`,
                'DELIVERING': `🛵 Il rider è partito con il tuo ordine!`,
                'COMPLETED': `🎉 Ordine completato! Buon appetito!`
              };
              showNotification(messages[nextStatus as keyof typeof messages] || "Stato ordine aggiornato");

              if (nextStatus === 'COMPLETED') {
                setTimeout(() => setReviewOrder(order), 2000);
              }
            }

            return { ...order, status: nextStatus };
          }
          return order;
        });
      });
    }, 15000);

    return () => clearInterval(timer);
  }, [orders]);

  const navigateTo = (view: ViewState) => {
    setCurrentView(view);
    if (view !== ViewState.CHEF_PROFILE) setSelectedChef(null);
    if (view !== ViewState.ORDERS) setSelectedOrder(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const copyDemoLink = () => {
    navigator.clipboard.writeText(currentUrl);
    setLinkCopied(true);
    showNotification("Link demo copiato negli appunti! 🔗");
    setTimeout(() => setLinkCopied(false), 3000);
  };

  const handleToggleFavorite = (dishId: string) => {
    setFavorites(prev => {
      if (prev.includes(dishId)) {
        showNotification("Rimosso dai preferiti");
        return prev.filter(id => id !== dishId);
      } else {
        showNotification("Aggiunto ai preferiti ❤️");
        return [...prev, dishId];
      }
    });
  };

  const handleInitiateBooking = (dish: Dish) => setBookingDish(dish);

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;
    setCart(prev => [...prev, { ...bookingDish, quantity: 1, scheduledDate: date, scheduledTime: time, deliveryMode, preferences }]);
    setBookingDish(null);
    showNotification("Piatto aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(i => i.quantity > 0));
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentSuccess = () => {
    const firstChefId = cart[0]?.chefId || 'c1';
    const chefName = MOCK_CHEFS.find(c => c.id === firstChefId)?.name || 'Chef';
    const newOrder: Order = {
      id: `ORDER-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      items: [...cart],
      total: checkoutTotal,
      status: 'PLACED',
      timestamp: new Date(),
      chefId: firstChefId,
      chefName: chefName,
      deliveryMode: cart[0]?.deliveryMode || 'pickup',
      estimatedTime: '20:45'
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setSelectedOrder(newOrder);
    setCurrentView(ViewState.ORDERS);
    showNotification("Ordine ricevuto! Seguilo live.");
  };

  const handleReviewSubmit = (rating: number, comment: string) => {
    if (!reviewOrder) return;
    setOrders(prev => prev.map(o => o.id === reviewOrder.id ? { ...o, isReviewed: true } : o));
    setReviewOrder(null);
    showNotification("Grazie per la tua recensione! ⭐");
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const activeOrdersCount = orders.filter(o => o.status !== 'COMPLETED').length;

  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));
        const searchLower = filters.search.toLowerCase();
        return matchesPrice && matchesDietary && (!filters.search || dish.name.toLowerCase().includes(searchLower) || chef.name.toLowerCase().includes(searchLower));
      });
      return matchingDishes.length > 0 ? { ...chef, dishes: matchingDishes } : null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900 flex flex-col pb-20 md:pb-0">
      <Header 
        cartCount={cartCount} 
        orderCount={activeOrdersCount} 
        onCartClick={() => setIsCartOpen(true)} 
        currentView={currentView} 
        onNavigate={navigateTo} 
        onAuthClick={() => setIsAuthOpen(true)}
        onShareClick={() => setIsShareOpen(true)}
      />

      {currentView === ViewState.HOME && <FilterBar filters={filters} onFilterChange={setFilters} />}

      <main className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full mb-8">
        {/* Entrepreneur Share Dashboard - Visible only on Home */}
        {currentView === ViewState.HOME && !filters.search && (
          <div className="mb-8 animate-fade-in">
            <div className="bg-black rounded-[2.5rem] p-6 text-white border-2 border-orange-600/30 shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-64 h-64 bg-orange-600 rounded-full blur-[100px] opacity-20 -mr-32 -mt-32"></div>
              <div className="flex flex-col md:flex-row items-center gap-6 relative z-10">
                <div className="bg-orange-600 p-4 rounded-3xl shadow-lg rotate-3 group-hover:rotate-0 transition-transform">
                  <QrCode className="w-10 h-10 text-black" />
                </div>
                <div className="flex-1 text-center md:text-left">
                  <div className="flex items-center justify-center md:justify-start gap-2 mb-1">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                    <h3 className="text-xs font-black uppercase tracking-[0.2em] text-orange-500">Investor Preview Dashboard</h3>
                  </div>
                  <h2 className="text-2xl font-black mb-2 italic">Pronto per il pitch? Genera il tuo link.</h2>
                  <p className="text-gray-400 text-sm font-medium max-w-lg">
                    Copia questo link e invialo via WhatsApp o Email per far testare l'esperienza <span className="text-white font-bold">MESA</span> in tempo reale.
                  </p>
                </div>
                <div className="flex gap-3 w-full md:w-auto">
                  <button 
                    onClick={copyDemoLink}
                    className={`flex-1 md:flex-none flex items-center justify-center gap-3 px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-xl active:scale-95 ${
                      linkCopied ? 'bg-green-500 text-white' : 'bg-white text-black hover:bg-orange-600 hover:text-white'
                    }`}
                  >
                    {linkCopied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                    {linkCopied ? 'Copiato!' : 'Copia Link Demo'}
                  </button>
                  <button 
                    onClick={() => setIsShareOpen(true)}
                    className="p-4 bg-orange-600/10 border border-orange-600/30 rounded-2xl text-orange-500 hover:bg-orange-600 hover:text-black transition-all"
                  >
                    <Share2 className="w-6 h-6" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}

        {currentView === ViewState.HOME && !filters.search && <ActivityFeed />}

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!filters.search && (
              <>
                <div className="text-center mb-12 py-10 bg-black rounded-[3rem] text-white shadow-2xl relative overflow-hidden border-b-8 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center"></div>
                  <div className="relative z-10 px-6">
                    <h1 className="text-5xl md:text-7xl font-black mb-2 tracking-tighter italic">MESA</h1>
                    <p className="text-lg font-bold text-orange-500 uppercase tracking-widest mb-6">Home Cooked. Hand Picked.</p>
                    <div className="flex justify-center space-x-4">
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Cuochi Attivi</p>
                          <p className="text-xl font-black">124</p>
                       </div>
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
