import React, { useState } from 'react';
import { X, User, ChefHat, LogIn, ShieldCheck } from 'lucide-react';

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onAdminLogin?: () => void;
}

export const AuthModal: React.FC<AuthModalProps> = ({ isOpen, onClose, onAdminLogin }) => {
  const [role, setRole] = useState<'client' | 'chef' | 'admin'>('client');
  const [mode, setMode] = useState<'login' | 'register'>('login');

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (role === 'admin') {
      onAdminLogin?.();
      onClose();
      return;
    }
    alert(`Simulazione: ${mode === 'login' ? 'Accesso' : 'Registrazione'} effettuata come ${role === 'client' ? 'Cliente' : 'Cuoco'}!`);
    onClose();
  };

  const handleGuestLogin = () => {
    alert("Accesso effettuato in Modalità Demo Ospite.\nBenvenuto su MESA!");
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[80] overflow-y-auto">
      <div className="flex min-h-full items-center justify-center p-4">
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />

        <div className="relative bg-white rounded-[3rem] shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
          <button onClick={onClose} className="absolute top-8 right-8 text-gray-400 hover:text-gray-600 z-10">
            <X className="w-6 h-6" />
          </button>

          <div className="flex border-b border-gray-100">
            <button
              onClick={() => { setRole('client'); setMode('login'); }}
              className={`flex-1 py-5 text-[10px] font-black uppercase tracking-widest flex flex-col items-center justify-center gap-1 transition-colors ${
                role === 'client' ? 'bg-white text-orange-600 border-b-4 border-orange-600' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'
              }`}
            >
              <User className="w-4 h-4" />
              <span>Cliente</span>
            </button>
            <button
              onClick={() => { setRole('chef'); setMode('login'); }}
              className={`flex-1 py-5 text-[10px] font-black uppercase tracking-widest flex flex-col items-center justify-center gap-1 transition-colors ${
                role === 'chef' ? 'bg-white text-orange-600 border-b-4 border-orange-600' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'
              }`}
            >
              <ChefHat className="w-4 h-4" />
              <span>Cuoco</span>
            </button>
            <button
              onClick={() => { setRole('admin'); setMode('login'); }}
              className={`flex-1 py-5 text-[10px] font-black uppercase tracking-widest flex flex-col items-center justify-center gap-1 transition-colors ${
                role === 'admin' ? 'bg-black text-orange-500 border-b-4 border-orange-500' : 'bg-gray-50 text-gray-400 hover:bg-gray-100'
              }`}
            >
              <ShieldCheck className="w-4 h-4" />
              <span>Admin</span>
            </button>
          </div>

          <div className="p-10">
            <h2 className="text-3xl font-black text-gray-900 mb-2 italic tracking-tight">
              {role === 'admin' ? 'Pannello di Controllo' : mode === 'login' ? 'Bentornato!' : role === 'client' ? 'Unisciti a MESA' : 'Diventa un Cuoco'}
            </h2>
            <p className="text-gray-500 text-sm font-medium mb-8 leading-relaxed">
              {role === 'admin' 
                ? 'Accedi alla visione a 360° del business MESA.'
                : mode === 'login' 
                  ? 'Accedi per gestire i tuoi ordini e preferenze.' 
                  : role === 'client' 
                    ? 'Registrati per ordinare piatti fatti in casa.' 
                    : 'Condividi la tua passione e guadagna cucinando.'}
            </p>

            <form onSubmit={handleSubmit} className="space-y-4">
              {mode === 'register' && role !== 'admin' && (
                <div className="grid grid-cols-2 gap-4">
                  <input type="text" placeholder="Nome" className="w-full p-4 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none transition-all bg-gray-50 text-sm font-bold" required />
                  <input type="text" placeholder="Cognome" className="w-full p-4 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none transition-all bg-gray-50 text-sm font-bold" required />
                </div>
              )}

              <input type="email" placeholder="Email" className="w-full p-4 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none transition-all bg-gray-50 text-sm font-bold" required />
              <input type="password" placeholder="Password" className="w-full p-4 border border-gray-100 rounded-2xl focus:ring-2 focus:ring-orange-500 outline-none transition-all bg-gray-50 text-sm font-bold" required />

              <button type="submit" className={`w-full py-4 font-black uppercase tracking-widest rounded-2xl shadow-xl transition-all active:scale-95 text-xs ${role === 'admin' ? 'bg-orange-600 text-black' : 'bg-black text-white hover:bg-orange-600'}`}>
                {role === 'admin' ? 'Entra nella Dashboard' : mode === 'login' ? 'Accedi' : 'Registrati'}
              </button>
            </form>

            {role !== 'admin' && (
              <>
                <div className="mt-6 flex items-center justify-between">
                  <div className="h-px bg-gray-100 flex-1"></div>
                  <span className="px-4 text-[10px] text-gray-400 font-black uppercase tracking-widest">OPPURE</span>
                  <div className="h-px bg-gray-100 flex-1"></div>
                </div>

                <button 
                  onClick={handleGuestLogin}
                  className="w-full mt-6 py-4 bg-orange-50 text-orange-700 font-black uppercase tracking-widest text-[10px] rounded-2xl hover:bg-orange-100 transition-all border border-orange-100 flex items-center justify-center space-x-2"
                >
                  <LogIn className="w-4 h-4" />
                  <span>Prova Demo come Ospite</span>
                </button>

                <div className="mt-8 text-center text-sm font-medium text-gray-500">
                  {mode === 'login' ? 'Non hai un account? ' : 'Hai già un account? '}
                  <button 
                    onClick={() => setMode(mode === 'login' ? 'register' : 'login')}
                    className="font-black text-orange-600 hover:underline"
                  >
                    {mode === 'login' ? 'Registrati' : 'Accedi'}
                  </button>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { 
