                  { l: "Stripe Connect", v: "100%", s: "ok" },
                  { l: "Chef Verification", v: "98%", s: "ok" },
                  { l: "HACCP Cloud", v: "100%", s: "ok" },
                  { l: "Server Scalability", v: "100%", s: "ok" }
                ].map((item, i) => (
                  <div key={i} className="flex justify-between items-center text-sm font-bold">
                    <span className="text-gray-400">{item.l}</span>
                    <span className="text-green-600">{item.v}</span>
                  </div>
                ))}
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

