                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Cuochi Certificati</p>
                          <p className="text-xl font-black">1.2k</p>
                       </div>
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Ordini oggi</p>
