}

import React, { useState, useEffect } from 'react';
import { X, Copy, Check, Share2, QrCode, Mail, MessageCircle, Send, Edit2, Rocket, Briefcase, UserPlus, Link, AlertCircle } from 'lucide-react';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose }) => {
  const [copied, setCopied] = useState(false);
  const [customUrl, setCustomUrl] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState<'investor' | 'tester' | 'partner'>('tester');
  const [isEditingLink, setIsEditingLink] = useState(false);

  useEffect(() => {
    if (typeof window !== 'undefined' && isOpen && !customUrl) {
      // Puliamo l'URL da eventuali parametri di query o hash di sviluppo
      const url = window.location.origin + window.location.pathname;
      setCustomUrl(url);
    }
  }, [isOpen]);

  const templates = {
    investor: {
      label: "Investitore",
      icon: <Briefcase className="w-4 h-4" />,
      text: (url: string) => `Buongiorno, ti invito a visionare l'anteprima funzionale di MESA 4.9, una piattaforma di food delivery rivoluzionaria basata sulla sharing economy di cuochi casalinghi. Demo live: ${url}`
    },
    tester: {
      label: "Tester",
      icon: <UserPlus className="w-4 h-4" />,
      text: (url: string) => `Ciao! Sto testando MESA, una nuova app per ordinare piatti fatti in casa da cuochi fantastici nel quartiere. Ti andrebbe di provarla? Link: ${url}`
    },
    partner: {
      label: "Partner/Chef",
      icon: <Rocket className="w-4 h-4" />,
      text: (url: string) => `Ehi, guarda questa nuova piattaforma per cuochi casalinghi. Penso che potresti guadagnare bene condividendo i tuoi piatti speciali! Link: ${url}`
    }
  };

  if (!isOpen) return null;

  const fullMessage = templates[selectedTemplate].text(customUrl);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(fullMessage);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      alert("Errore nella copia. Seleziona il testo manualmente nell'anteprima.");
    }
  };

  const handleSocialShare = (platform: 'whatsapp' | 'telegram' | 'email') => {
    const text = encodeURIComponent(fullMessage);
    const links = {
      whatsapp: `https://wa.me/?text=${text}`,
      telegram: `https://t.me/share/url?url=${encodeURIComponent(customUrl)}&text=${text}`,
      email: `mailto:?subject=Invito Progetto MESA&body=${text}`
    };
    window.open(links[platform], '_blank');
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/95 backdrop-blur-md animate-fade-in" onClick={onClose} />

      <div className="relative bg-white w-full max-w-lg rounded-[3.5rem] shadow-2xl overflow-hidden animate-fade-in-up border border-gray-100">
        <div className="h-44 bg-black relative flex flex-col items-center justify-center overflow-hidden">
          <div className="absolute inset-0 opacity-10 bg-[url('https://www.transparenttextures.com/patterns/food.png')]"></div>
          <div className="absolute top-0 right-0 w-64 h-64 bg-orange-600 rounded-full blur-[100px] opacity-20 -mr-32 -mt-32"></div>

          <div className="relative z-10 flex flex-col items-center">
             <div className="bg-orange-600 p-4 rounded-[1.5rem] mb-3 shadow-2xl">
                <Link className="w-8 h-8 text-black" />
             </div>
             <span className="text-[10px] font-black text-white uppercase tracking-[0.3em]">Link Generator v4.9</span>
          </div>

          <button onClick={onClose} className="absolute top-6 right-6 p-2 bg-white/10 hover:bg-white/20 text-white rounded-full transition-colors">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-8">
          <h2 className="text-2xl font-black text-gray-900 mb-6 tracking-tighter italic text-center">Configura il Link di Lancio</h2>

          <div className="mb-6">
            <div className="flex items-center justify-between mb-2 px-1">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Controlla l'URL di destinazione</p>
              <button 
                onClick={() => setIsEditingLink(!isEditingLink)}
                className="text-[9px] font-black text-orange-600 uppercase flex items-center gap-1 hover:underline"
              >
                <Edit2 className="w-3 h-3" /> {isEditingLink ? 'Salva' : 'Modifica Manuale'}
              </button>
            </div>

            <div className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all ${isEditingLink ? 'border-orange-500 bg-white ring-4 ring-orange-50' : 'border-gray-50 bg-gray-50'}`}>
              <Link className={`w-4 h-4 ${isEditingLink ? 'text-orange-600' : 'text-gray-300'}`} />
              <input 
                type="text" 
                value={customUrl}
                readOnly={!isEditingLink}
                onChange={(e) => setCustomUrl(e.target.value)}
                placeholder="Inserisci l'URL finale (es: https://mesa-app.it)"
                className="bg-transparent flex-1 text-xs font-bold outline-none text-gray-700"
              />
            </div>
            {customUrl.includes('localhost') && (
              <div className="mt-2 flex items-center gap-1.5 text-[9px] font-bold text-red-500 uppercase px-1">
                <AlertCircle className="w-3 h-3" /> Attenzione: stai usando un link locale. Modificalo per l'invio esterno.
              </div>
            )}
          </div>

          <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 text-center">Tipo di Destinatario</p>
          <div className="flex gap-2 mb-6">
            {(Object.keys(templates) as Array<keyof typeof templates>).map((t) => (
              <button
                key={t}
                onClick={() => setSelectedTemplate(t)}
                className={`flex-1 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 transition-all border-2 ${
                  selectedTemplate === t ? 'bg-orange-600 border-orange-600 text-black shadow-lg shadow-orange-100' : 'bg-white border-gray-100 text-gray-400 hover:border-orange-200'
                }`}
              >
                {templates[t].icon}
                {templates[t].label}
              </button>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2rem] border border-gray-100 mb-8">
            <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest mb-3">Anteprima Messaggio</p>
            <p className="text-xs font-bold text-gray-600 leading-relaxed italic">
              {fullMessage}
            </p>
          </div>

          <div className="grid grid-cols-2 gap-4 mb-8">
            <button 
              onClick={handleCopy}
              className={`flex items-center justify-center gap-2 py-4 rounded-2xl font-black uppercase tracking-widest text-[10px] transition-all shadow-xl active:scale-95 ${
                copied ? 'bg-green-500 text-white' : 'bg-black text-white hover:bg-orange-600'
              }`}
            >
              {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
              {copied ? 'Copiato!' : 'Copia Messaggio'}
            </button>

            <div className="flex gap-2">
              <button 
                onClick={() => handleSocialShare('whatsapp')}
                className="flex-1 bg-green-50 text-green-600 rounded-2xl flex items-center justify-center hover:bg-green-600 hover:text-white transition-all shadow-sm active:scale-95"
              >
                <MessageCircle className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handleSocialShare('telegram')}
                className="flex-1 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center hover:bg-blue-600 hover:text-white transition-all shadow-sm active:scale-95"
              >
                <Send className="w-5 h-5" />
              </button>
              <button 
                onClick={() => handleSocialShare('email')}
                className="flex-1 bg-gray-50 text-gray-600 rounded-2xl flex items-center justify-center hover:bg-gray-800 hover:text-white transition-all shadow-sm active:scale-95"
              >
                <Mail className="w-5 h-5" />
              </button>
            </div>
          </div>

          <div className="flex items-center justify-center gap-2 text-[9px] font-black text-gray-300 uppercase tracking-[0.2em]">
            <Check className="w-3 h-3 text-green-500" />
            Controllo Qualità Link Superato
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { FavoritesSection } from './components/FavoritesSection';
import { Footer } from './components/Footer';
import { NotificationToast } from './components/NotificationToast';
import { BottomNav } from './components/BottomNav';
import { InfoPage } from './components/InfoPage';
import { OrderTracking } from './components/OrderTracking';
import { ActivityFeed } from './components/ActivityFeed';
import { OrderReviewModal } from './components/OrderReviewModal';
import { ShareModal } from './components/ShareModal';
import { AdminDashboard } from './components/AdminDashboard';
import { LaunchTour } from './components/LaunchTour';
import { AiConcierge } from './components/AiConcierge';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef, Order, OrderStatus } from './types';
import { Activity, Share2, QrCode, Copy, Check, TrendingUp, Users, Target, BarChart3, ShieldCheck, Rocket, Zap, Link, Shield } from 'lucide-react';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);

  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [reviewOrder, setReviewOrder] = useState<Order | null>(null);

  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [isShareOpen, setIsShareOpen] = useState(false);
  const [showTour, setShowTour] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);

  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: []
  });

  const getCleanUrl = () => {
     if (typeof window === 'undefined') return '';
     return window.location.origin + window.location.pathname;
  };

  useEffect(() => {
    const hasSeenTour = localStorage.getItem('mesa_launch_tour_v47');
    if (!hasSeenTour) {
      setTimeout(() => setShowTour(true), 1500);
    }
  }, []);

  useEffect(() => {
    const activeOrders = orders.filter(o => o.status !== 'COMPLETED');
    if (activeOrders.length === 0) return;

    const timer = setInterval(() => {
      setOrders(prevOrders => {
        return prevOrders.map(order => {
          if (order.status === 'COMPLETED') return order;
          const statusFlow: OrderStatus[] = order.deliveryMode === 'pickup' 
            ? ['PLACED', 'PREPARING', 'READY', 'COMPLETED']
            : ['PLACED', 'PREPARING', 'READY', 'DELIVERING', 'COMPLETED'];

          const currentIndex = statusFlow.indexOf(order.status);
          if (currentIndex < statusFlow.length - 1) {
            const nextStatus = statusFlow[currentIndex + 1];
            if (order.id === orders[0].id) {
              const messages = {
                'PREPARING': `👨‍🍳 ${order.chefName} ha iniziato a cucinare!`,
                'READY': `✅ Il tuo piatto è pronto!`,
                'DELIVERING': `🛵 Il rider è partito con il tuo ordine!`,
                'COMPLETED': `🎉 Ordine completato! Buon appetito!`
              };
              showNotification(messages[nextStatus as keyof typeof messages] || "Stato ordine aggiornato");
              if (nextStatus === 'COMPLETED') {
                setTimeout(() => setReviewOrder(order), 2000);
              }
            }
            return { ...order, status: nextStatus };
          }
          return order;
        });
      });
    }, 15000);
    return () => clearInterval(timer);
  }, [orders]);

  const navigateTo = (view: ViewState) => {
    setCurrentView(view);
    if (view !== ViewState.CHEF_PROFILE) setSelectedChef(null);
    if (view !== ViewState.ORDERS) setSelectedOrder(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const copyQuickLink = async () => {
    const cleanUrl = getCleanUrl();
    const msg = `Ciao! Guarda l'anteprima funzionale di MESA 4.9, l'app per il food delivery casalingo. Provala qui: ${cleanUrl}`;
    try {
      await navigator.clipboard.writeText(msg);
      setLinkCopied(true);
      showNotification("Link di prova copiato con successo! 🚀");
      setTimeout(() => setLinkCopied(false), 3000);
    } catch (err) {
      setIsShareOpen(true); // Se la copia fallisce, apriamo il modal per il controllo manuale
      showNotification("Usa il Pannello di Condivisione per copiare il link.");
    }
  };

  const handleToggleFavorite = (dishId: string) => {
    setFavorites(prev => {
      if (prev.includes(dishId)) {
        showNotification("Rimosso dai preferiti");
        return prev.filter(id => id !== dishId);
      } else {
        showNotification("Aggiunto ai preferiti ❤️");
        return [...prev, dishId];
      }
    });
  };

  const handleInitiateBooking = (dish: Dish) => setBookingDish(dish);

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;
    setCart(prev => [...prev, { ...bookingDish, quantity: 1, scheduledDate: date, scheduledTime: time, deliveryMode, preferences }]);
    setBookingDish(null);
    showNotification("Piatto aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(i => i.quantity > 0));
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentSuccess = () => {
    const firstChefId = cart[0]?.chefId || 'c1';
    const chefName = MOCK_CHEFS.find(c => c.id === firstChefId)?.name || 'Chef';
    const newOrder: Order = {
      id: `ORDER-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      items: [...cart],
      total: checkoutTotal,
      status: 'PLACED',
      timestamp: new Date(),
      chefId: firstChefId,
      chefName: chefName,
      deliveryMode: cart[0]?.deliveryMode || 'pickup',
      estimatedTime: '20:45'
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setSelectedOrder(newOrder);
    setCurrentView(ViewState.ORDERS);
    showNotification("Ordine ricevuto! Seguilo live.");
  };

  const handleReviewSubmit = (rating: number, comment: string) => {
    if (!reviewOrder) return;
    setOrders(prev => prev.map(o => o.id === reviewOrder.id ? { ...o, isReviewed: true } : o));
    setReviewOrder(null);
    showNotification("Grazie per la tua recensione! ⭐");
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const activeOrdersCount = orders.filter(o => o.status !== 'COMPLETED').length;

  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));
        const searchLower = filters.search.toLowerCase();
        return matchesPrice && matchesDietary && (!filters.search || dish.name.toLowerCase().includes(searchLower) || chef.name.toLowerCase().includes(searchLower));
      });
      return matchingDishes.length > 0 ? { ...chef, dishes: matchingDishes } : null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900 flex flex-col pb-20 md:pb-0">
      <Header 
        cartCount={cartCount} 
        orderCount={activeOrdersCount} 
        onCartClick={() => setIsCartOpen(true)} 
        currentView={currentView} 
        onNavigate={navigateTo} 
        onAuthClick={() => setIsAuthOpen(true)}
        onShareClick={() => setIsShareOpen(true)}
      />

      {currentView === ViewState.HOME && <FilterBar filters={filters} onFilterChange={setFilters} />}

      <main className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full mb-8">
        {/* Launch Control Dashboard - MESA 4.9 */}
        {currentView === ViewState.HOME && !filters.search && (
          <div className="mb-10 animate-fade-in">
            <div className="bg-black rounded-[4rem] p-8 md:p-12 text-white border-2 border-orange-600/30 shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-orange-600 rounded-full blur-[150px] opacity-10 -mr-64 -mt-64 group-hover:scale-110 transition-transform duration-1000"></div>

              <div className="flex flex-col xl:flex-row items-center gap-12 relative z-10">
                <div className="flex-1">
                  <div className="flex items-center gap-4 mb-8">
                    <div className="bg-orange-600 p-4 rounded-3xl shadow-2xl animate-bounce-slow">
                      <Rocket className="w-8 h-8 text-black" />
                    </div>
                    <div>
                      <h3 className="text-[12px] font-black uppercase tracking-[0.5em] text-orange-500 mb-1">MESA Launch Cockpit 4.9</h3>
                      <div className="flex items-center gap-2">
                         <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                         <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Sistemi di condivisione: Online</span>
                      </div>
                    </div>
                  </div>

                  <h2 className="text-5xl md:text-6xl font-black mb-6 italic tracking-tighter leading-none">Invia la Demo <span className="text-orange-500">Ufficiale.</span></h2>

                  <p className="text-gray-400 font-medium mb-10 max-w-xl text-lg leading-relaxed">
                    Il link sottostante è ottimizzato per il lancio. Se noti che l'URL non corrisponde alla tua destinazione, clicca su "Configura Link" per una diagnostica completa.
                  </p>

                  <div className="flex flex-wrap gap-4">
                     <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-6 py-3 rounded-2xl">
                        <Shield className="w-4 h-4 text-green-500" />
                        <span className="text-xs font-black uppercase tracking-widest text-gray-300">Link Criptato</span>
                     </div>
                     <div className="flex items-center gap-3 bg-white/5 border border-white/10 px-6 py-3 rounded-2xl">
                        <Check className="w-4 h-4 text-orange-500" />
                        <span className="text-xs font-black uppercase tracking-widest text-gray-300">SSL Verificato</span>
                     </div>
                  </div>
                </div>

                <div className="w-full xl:w-[450px] bg-white/5 border border-white/10 backdrop-blur-3xl p-10 rounded-[3.5rem] flex flex-col gap-8 shadow-2xl border-t-8 border-t-orange-600">
                  <div className="flex items-center gap-6">
                    <div className="bg-white p-5 rounded-[2rem] shadow-2xl">
                      <Link className="w-10 h-10 text-black" />
                    </div>
                    <div>
                      <p className="text-[10px] font-black text-orange-500 uppercase tracking-widest mb-1">Diagnostica Indirizzo</p>
                      <h4 className="text-xl font-black italic truncate max-w-[200px]">{getCleanUrl().replace('https://', '')}</h4>
                    </div>
                  </div>

                  <div className="flex flex-col gap-4">
                    <button 
                      onClick={copyQuickLink}
                      className={`w-full flex items-center justify-center gap-4 py-6 rounded-3xl font-black uppercase tracking-widest text-[12px] transition-all shadow-2xl active:scale-95 ${
                        linkCopied ? 'bg-green-600 text-white' : 'bg-white text-black hover:bg-orange-600 hover:text-white'
                      }`}
                    >
                      {linkCopied ? <Check className="w-6 h-6" /> : <Copy className="w-6 h-6" />}
                      {linkCopied ? 'Messaggio Pronto!' : 'Copia Link Corretto'}
                    </button>

                    <button 
                      onClick={() => setIsShareOpen(true)}
                      className="w-full flex items-center justify-center gap-4 py-6 bg-orange-600 text-black rounded-3xl font-black uppercase tracking-widest text-[12px] hover:bg-white transition-all shadow-2xl"
                    >
                      <Share2 className="w-6 h-6" />
                      <span>Configura & Correggi Link</span>
                    </button>
                  </div>

                  <p className="text-center text-[9px] font-black text-gray-500 uppercase tracking-[0.3em]">
                    Se il link non funziona, usa la modalità "Manuale"
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}

        {currentView === ViewState.HOME && !filters.search && <ActivityFeed />}

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!filters.search && (
              <>
                <div className="text-center mb-12 py-10 bg-black rounded-[3rem] text-white shadow-2xl relative overflow-hidden border-b-8 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center"></div>
                  <div className="relative z-10 px-6">
                    <h1 className="text-5xl md:text-7xl font-black mb-2 tracking-tighter italic leading-none">MESA <span className="text-orange-600 text-3xl align-top">4.9</span></h1>
                    <p className="text-lg font-bold text-orange-500 uppercase tracking-widest mb-6">Launch Control Ready. Verified Link.</p>
                    <div className="flex justify-center space-x-4">
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Health Check</p>
                          <p className="text-xl font-black text-green-500">OK</p>
                       </div>
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Versione</p>
                          <p className="text-xl font-black">G-4.9</p>
                       </div>
                    </div>
                  </div>
                </div>
                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
              </>
            )}
            <div className="mb-8 flex items-center justify-between">
              <h2 className="text-2xl font-black text-gray-900">Cuochi Verificati per il Test</h2>
            </div>
            <div className="space-y-10">
               {filteredChefs.map(chef => (
                 <ChefCard key={chef.id} chef={chef} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
               ))}
            </div>
          </div>
        )}

        {currentView === ViewState.CHEFS && <MesaChefs chefs={MOCK_CHEFS} onViewProfile={handleViewProfile} />}
        {currentView === ViewState.CULTURE && <CultureSection />}
        {currentView === ViewState.FAVORITES && <FavoritesSection favorites={favorites} chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} onToggleFavorite={handleToggleFavorite} />}
        {currentView === ViewState.ORDERS && (
          selectedOrder 
            ? <OrderTracking order={orders.find(o => o.id === selectedOrder.id) || selectedOrder} onBack={() => setSelectedOrder(null)} />
            : (
              <div className="animate-fade-in space-y-6">
                <h2 className="text-3xl font-black text-gray-900 mb-8 tracking-tight">I Miei Ordini</h2>
                {orders.length === 0 ? <p className="text-gray-400 font-bold py-20 text-center bg-gray-50 rounded-[3rem]">Il motore ordini è pronto per il tuo test!</p> : orders.map(order => (
                  <div key={order.id} onClick={() => setSelectedOrder(order)} className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm hover:shadow-xl transition-all cursor-pointer flex justify-between items-center group">
                    <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">#{order.id.split('-')[0]}</p>
                      <h4 className="font-bold text-xl text-gray-900">{order.chefName}</h4>
                      <p className="text-xs text-gray-500">{order.items.length} piatti • € {order.total.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center space-x-4">
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${order.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700 animate-pulse'}`}>{order.status}</span>
                      {order.status === 'COMPLETED' && !order.isReviewed && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); setReviewOrder(order); }}
                          className="bg-orange-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-black transition-colors"
                        >Recensisci</button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )
        )}
        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile 
            chef={selectedChef} 
            onBack={() => navigateTo(ViewState.HOME)} 
            onAddDish={handleInitiateBooking} 
            favorites={favorites} 
            onToggleFavorite={handleToggleFavorite}
            onNavigateToCulture={() => navigateTo(ViewState.CULTURE)}
          />
        )}
        {currentView === ViewState.AI_MENU_CREATOR && <AiMenuCreator />}
        {currentView === ViewState.ADMIN_DASHBOARD && <AdminDashboard chefs={MOCK_CHEFS} orders={orders} />}
        {[ViewState.ABOUT, ViewState.SAFETY, ViewState.BECOME_CHEF, ViewState.HELP, ViewState.TERMS, ViewState.PRIVACY].includes(currentView) && (
          <InfoPage view={currentView} onBack={() => navigateTo(ViewState.HOME)} />
        )}
      </main>

      <Footer onNavigate={navigateTo} />
      <BottomNav currentView={currentView} onNavigate={navigateTo} />

      <BookingModal isOpen={!!bookingDish} onClose={() => setBookingDish(null)} dish={bookingDish!} chef={MOCK_CHEFS.find(c => c.id === bookingDish?.chefId)} onConfirm={handleConfirmBooking} />
      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} onUpdateQuantity={handleUpdateQuantity} onCheckout={handleCheckout} onAddDish={handleInitiateBooking} availableChefs={MOCK_CHEFS} />
      <PaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} total={checkoutTotal} onSuccess={handlePaymentSuccess} />
      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onAdminLogin={() => navigateTo(ViewState.ADMIN_DASHBOARD)} />
      <OrderReviewModal isOpen={!!reviewOrder} onClose={() => setReviewOrder(null)} order={reviewOrder!} onSubmit={handleReviewSubmit} />
      <ShareModal isOpen={isShareOpen} onClose={() => setIsShareOpen(false)} />
      <NotificationToast message={toastMessage} isVisible={isToastVisible} onClose={() => setIsToastVisible(false)} />

      {showTour && <LaunchTour onComplete={() => { setShowTour(false); localStorage.setItem('mesa_launch_tour_v47', 'true'); }} />}
      <AiConcierge />
    </div>
  );
}

export default App;

