        )}

        {currentView === ViewState.CHEFS && <MesaChefs chefs={MOCK_CHEFS} onViewProfile={handleViewProfile} />}
        {currentView === ViewState.CULTURE && <CultureSection />}
        {currentView === ViewState.FAVORITES && <FavoritesSection favorites={favorites} chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} onToggleFavorite={handleToggleFavorite} />}
        {currentView === ViewState.ORDERS && (
          selectedOrder 
            ? <OrderTracking order={orders.find(o => o.id === selectedOrder.id) || selectedOrder} onBack={() => setSelectedOrder(null)} />
