import { X, ChefHat, ShieldCheck, Camera, FileText, Check, ArrowRight, Sparkles, MapPin, Smartphone, Loader2 } from 'lucide-react';

interface ChefOnboardingProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ChefOnboarding: React.FC<ChefOnboardingProps> = ({ isOpen, onClose }) => {
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  if (!isOpen) return null;

  const handleNext = () => {
    if (step < 3) setStep(step + 1);
    else {
      setIsSubmitting(true);
      setTimeout(() => {
        setIsSubmitting(false);
        setIsSuccess(true);
        setTimeout(onClose, 2000);
      }, 2000);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/90 backdrop-blur-xl animate-fade-in" onClick={onClose} />

      <div className="relative bg-white w-full max-w-2xl rounded-[4rem] shadow-2xl overflow-hidden animate-fade-in-up border border-gray-100">

        {/* Header Branding */}
        <div className="bg-black p-10 text-white flex items-center justify-between border-b-8 border-orange-600">
           <div className="flex items-center gap-6">
              <div className="w-16 h-16 bg-orange-600 rounded-[1.5rem] flex items-center justify-center shadow-xl">
                 <ChefHat className="w-8 h-8 text-black" />
              </div>
              <div>
                 <p className="text-[10px] font-black text-orange-500 uppercase tracking-[0.4em] mb-1">MESA Partner Program</p>
                 <h2 className="text-3xl font-black italic tracking-tighter leading-none">Cucina con Noi</h2>
              </div>
           </div>
           <button onClick={onClose} className="p-3 hover:bg-white/10 rounded-full transition-colors text-gray-400">
             <X className="w-6 h-6" />
           </button>
        </div>

        <div className="p-10">
          {isSuccess ? (
            <div className="text-center py-20 animate-fade-in">
               <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-8">
                  <Check className="w-12 h-12 text-green-600" />
               </div>
               <h3 className="text-4xl font-black italic mb-4">Candidatura Inviata!</h3>
               <p className="text-gray-500 font-medium">Analizzeremo il tuo profilo e ti risponderemo entro 48 ore.</p>
            </div>
          ) : (
            <>
              <div className="flex gap-3 mb-12">
                 {[1, 2, 3].map(i => (
                   <div key={i} className={`h-2 flex-1 rounded-full transition-all ${step >= i ? 'bg-orange-600' : 'bg-gray-100'}`} />
                 ))}
              </div>

              {step === 1 && (
                <div className="animate-fade-in">
                   <h3 className="text-2xl font-black italic mb-6 tracking-tight flex items-center gap-3">
                      <Smartphone className="w-6 h-6 text-orange-600" /> Profilo Identità
                   </h3>
                   <div className="space-y-4">
                      <div className="grid grid-cols-2 gap-4">
                        <input type="text" placeholder="Nome d'Arte" className="w-full p-5 bg-gray-50 border border-gray-100 rounded-3xl outline-none focus:ring-2 focus:ring-orange-500 font-bold" />
                        <input type="text" placeholder="Nazionalità" className="w-full p-5 bg-gray-50 border border-gray-100 rounded-3xl outline-none focus:ring-2 focus:ring-orange-500 font-bold" />
                      </div>
                      <div className="flex items-center gap-4 p-6 bg-orange-50 rounded-[2rem] border border-orange-100">
                         <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-orange-600 shadow-sm"><Camera className="w-6 h-6" /></div>
                         <div>
                            <p className="text-sm font-black text-gray-900">Carica Foto Profilo</p>
                            <p className="text-[10px] text-gray-400 font-bold uppercase">Usa un'immagine solare e accogliente</p>
                         </div>
                      </div>
                   </div>
                </div>
              )}

              {step === 2 && (
                <div className="animate-fade-in">
                   <h3 className="text-2xl font-black italic mb-6 tracking-tight flex items-center gap-3">
                      <ShieldCheck className="w-6 h-6 text-green-600" /> Compliance & Sicurezza
                   </h3>
                   <div className="space-y-6">
                      <div className="p-8 border-2 border-dashed border-gray-200 rounded-[2.5rem] text-center hover:border-orange-500 transition-colors cursor-pointer group">
                         <FileText className="w-12 h-12 text-gray-300 mx-auto mb-4 group-hover:text-orange-500 transition-colors" />
                         <p className="font-black text-gray-900 mb-1">Carica Certificato HACCP</p>
                         <p className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">Obbligatorio per vendere cibo su MESA</p>
                      </div>
                      <div className="flex items-center gap-3">
                         <input type="checkbox" id="terms" className="w-5 h-5 rounded-md accent-orange-600" />
                         <label htmlFor="terms" className="text-xs font-bold text-gray-600">Accetto di sottoporre la mia cucina a controlli periodici MESA.</label>
                      </div>
                   </div>
                </div>
              )}

              {step === 3 && (
                <div className="animate-fade-in">
                   <h3 className="text-2xl font-black italic mb-6 tracking-tight flex items-center gap-3">
                      <Sparkles className="w-6 h-6 text-purple-600" /> Il Tuo Primo Menu AI
                   </h3>
                   <div className="space-y-4">
                      <p className="text-sm text-gray-500 font-medium mb-6">Raccontaci brevemente cosa sai cucinare meglio. L'AI di MESA genererà il tuo menu professionale pronto per il lancio.</p>
                      <textarea 
                        className="w-full p-8 bg-gray-50 border border-gray-100 rounded-[2.5rem] outline-none focus:ring-2 focus:ring-orange-500 font-bold text-sm resize-none"
                        placeholder="Esempio: Faccio una lasagna con ricetta segreta di mia nonna e una pasta al forno incredibile..."
                        rows={4}
                      />
                   </div>
                </div>
              )}

              <div className="mt-12 flex items-center justify-between">
                 <button 
                  onClick={() => step > 1 ? setStep(step-1) : onClose()}
                  className="px-8 py-5 text-gray-400 font-black uppercase tracking-widest text-[10px] hover:text-black"
                 >
                   {step === 1 ? 'Annulla' : 'Indietro'}
                 </button>

                 <button 
                  onClick={handleNext}
                  disabled={isSubmitting}
                  className="px-10 py-5 bg-black text-white rounded-3xl font-black uppercase tracking-widest text-xs flex items-center gap-3 hover:bg-orange-600 transition-all shadow-2xl active:scale-95 disabled:opacity-50"
                 >
                   {isSubmitting ? (
                     <Loader2 className="w-4 h-4 animate-spin" />
                   ) : (
                     <>
                        <span>{step === 3 ? 'Invia Candidatura' : 'Continua'}</span>
                        <ArrowRight className="w-4 h-4" />
                     </>
                   )}
                 </button>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

