import React, { useState } from 'react';
import { Search, SlidersHorizontal, Leaf, Flame, Fish, Drumstick, Globe, ChevronDown, ChevronUp } from 'lucide-react';
import { FilterState } from '../types';
import { MOCK_CHEFS } from '../constants';

interface FilterBarProps {
  filters: FilterState;
  onFilterChange: (filters: FilterState) => void;
}

export const FilterBar: React.FC<FilterBarProps> = ({ filters, onFilterChange }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const dietaryOptions = ['Vegetarian', 'Vegan', 'Gluten Free', 'Lactose Free'];
  const categoryOptions = [
    { name: 'Carne', icon: Drumstick },
    { name: 'Pesce', icon: Fish },
    { name: 'Piccante', icon: Flame },
  ];

  // Estrai dinamicamente tutte le nazionalità uniche dai cuochi mock
  const countryOptions = Array.from(new Set(MOCK_CHEFS.map(chef => chef.nationality))).sort();

  const toggleDietary = (option: string) => {
    const current = filters.dietary;
    const next = current.includes(option)
      ? current.filter(d => d !== option)
      : [...current, option];
    onFilterChange({ ...filters, dietary: next });
  };

  const toggleCategory = (option: string) => {
    const current = filters.categories || [];
    const next = current.includes(option)
      ? current.filter(c => c !== option)
      : [...current, option];
    onFilterChange({ ...filters, categories: next });
  };

  const toggleCountry = (option: string) => {
    const current = filters.countries || [];
    const next = current.includes(option)
      ? current.filter(c => c !== option)
      : [...current, option];
    onFilterChange({ ...filters, countries: next });
  };

  const activeFiltersCount = 
    filters.dietary.length + 
    (filters.categories?.length || 0) + 
    (filters.countries?.length || 0) + 
    (filters.maxPrice < 50 ? 1 : 0);

  return (
    <div className="bg-white border-b border-orange-100 py-3 sticky top-20 z-40 shadow-sm transition-all duration-300">
      <div className="max-w-6xl mx-auto px-4">
        <div className="flex items-center gap-2">
          {/* Search Input - Primary Action */}
          <div className="relative flex-1">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="h-4 w-4 text-gray-400" />
            </div>
            <input
              type="text"
              placeholder="Cerca piatti o chef..."
              className="block w-full pl-9 pr-3 py-2.5 border border-gray-200 rounded-2xl bg-gray-50 text-sm focus:outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all"
              value={filters.search}
              onChange={(e) => onFilterChange({ ...filters, search: e.target.value })}
            />
          </div>

          {/* Toggle Button for advanced filters */}
          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-2xl border text-sm font-bold transition-all ${
              isExpanded || activeFiltersCount > 0 
                ? 'bg-orange-600 border-orange-600 text-white' 
                : 'bg-white border-gray-200 text-gray-700 hover:border-orange-300'
            }`}
          >
            <SlidersHorizontal className="w-4 h-4" />
            <span className="hidden sm:inline">Filtri</span>
            {activeFiltersCount > 0 && (
              <span className="bg-white text-orange-600 w-5 h-5 rounded-full flex items-center justify-center text-[10px]">
                {activeFiltersCount}
              </span>
            )}
            {isExpanded ? <ChevronUp className="w-4 h-4 ml-1" /> : <ChevronDown className="w-4 h-4 ml-1" />}
          </button>
        </div>

        {/* Collapsible Section */}
        {isExpanded && (
          <div className="mt-4 pt-4 border-t border-gray-100 animate-fade-in space-y-6">

            {/* Row 1: Price and Categories */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Price Range */}
              <div>
                <div className="flex justify-between items-center mb-3">
                  <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Budget Massimo</span>
                  <span className="text-sm font-extrabold text-orange-600 bg-orange-50 px-3 py-1 rounded-xl border border-orange-100">€ {filters.maxPrice}</span>
                </div>
                <input
                  type="range"
                  min="5"
                  max="50"
                  step="1"
                  value={filters.maxPrice}
                  onChange={(e) => onFilterChange({ ...filters, maxPrice: parseInt(e.target.value) })}
                  className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-600"
                />
              </div>

              {/* Category Filters */}
              <div>
                <span className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-3">Tipo di Piatto</span>
                <div className="flex flex-wrap gap-2">
                  {categoryOptions.map(cat => {
                    const Icon = cat.icon;
                    const isSelected = filters.categories?.includes(cat.name);
                    return (
                      <button
                        key={cat.name}
                        onClick={() => toggleCategory(cat.name)}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all border-2 ${
                          isSelected
                            ? 'bg-orange-100 text-orange-800 border-orange-500 shadow-sm'
                            : 'bg-white text-gray-600 border-gray-100 hover:border-orange-200'
                        }`}
                      >
                        <Icon className="w-4 h-4" />
                        <span>{cat.name}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            {/* Row 2: Countries (The New Filter) */}
            <div>
              <div className="flex items-center gap-2 mb-3">
                 <Globe className="w-4 h-4 text-orange-600" />
                 <span className="text-xs font-black text-gray-400 uppercase tracking-widest block">Origine della Cucina</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {countryOptions.map(country => (
                  <button
                    key={country}
                    onClick={() => toggleCountry(country)}
                    className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-lg transition-all border-2 ${
                      filters.countries.includes(country)
                        ? 'bg-orange-50 border-orange-500 shadow-sm scale-105'
                        : 'bg-white border-gray-100 grayscale hover:grayscale-0 hover:border-orange-200'
                    }`}
                    title={`Filtra per cucina ${country}`}
                  >
                    {country}
                  </button>
                ))}
                {filters.countries.length > 0 && (
                   <button 
                    onClick={() => onFilterChange({ ...filters, countries: [] })}
                    className="px-4 py-2.5 text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-red-500"
                   >
                     Reset Origine
                   </button>
                )}
              </div>
            </div>

            {/* Row 3: Dietary Filters */}
            <div>
              <span className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-3">Esigenze Alimentari</span>
              <div className="flex flex-wrap gap-2">
                {dietaryOptions.map(option => (
                  <button
                    key={option}
                    onClick={() => toggleDietary(option)}
                    className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all border-2 ${
                      filters.dietary.includes(option)
                        ? 'bg-green-100 text-green-700 border-green-500'
                        : 'bg-white text-gray-600 border-gray-100 hover:border-green-200'
                    }`}
                  >
                    <Leaf className="w-3.5 h-3.5" />
                    <span>{option}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="flex justify-between items-center pt-4 border-t border-gray-100">
               <button 
                onClick={() => onFilterChange({ search: '', maxPrice: 50, dietary: [], categories: [], countries: [] })}
                className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-300 hover:text-red-500 transition-colors"
               >
                 Azzera tutto
               </button>
               <button 
                onClick={() => setIsExpanded(false)}
                className="px-8 py-3 bg-black text-white text-[10px] font-black uppercase tracking-widest rounded-xl shadow-lg hover:bg-orange-600 transition-all active:scale-95"
               >
                 Applica Filtri
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { FavoritesSection } from './components/FavoritesSection';
import { Footer } from './components/Footer';
import { NotificationToast } from './components/NotificationToast';
import { BottomNav } from './components/BottomNav';
import { InfoPage } from './components/InfoPage';
import { OrderTracking } from './components/OrderTracking';
import { ActivityFeed } from './components/ActivityFeed';
import { OrderReviewModal } from './components/OrderReviewModal';
import { ShareModal } from './components/ShareModal';
import { AdminDashboard } from './components/AdminDashboard';
import { LaunchTour } from './components/LaunchTour';
import { AiConcierge } from './components/AiConcierge';
import { ChefOnboarding } from './components/ChefOnboarding';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef, Order, OrderStatus } from './types';
// Fixed: Added missing ChefHat to the lucide-react imports.
import { Activity, Share2, QrCode, Copy, Check, TrendingUp, Users, Target, BarChart3, ShieldCheck, Rocket, Zap, Link, Shield, ExternalLink, Smartphone, ChefHat } from 'lucide-react';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);

  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [reviewOrder, setReviewOrder] = useState<Order | null>(null);

  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [isShareOpen, setIsShareOpen] = useState(false);
  const [isOnboardingOpen, setIsOnboardingOpen] = useState(false);
  const [showTour, setShowTour] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);

  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: [],
    countries: []
  });

  const getCleanUrl = () => {
     if (typeof window === 'undefined') return '';
     return window.location.origin + window.location.pathname;
  };

  useEffect(() => {
    const hasSeenTour = localStorage.getItem('mesa_launch_tour_v55');
    if (!hasSeenTour) {
      setTimeout(() => setShowTour(true), 1500);
    }
  }, []);

  useEffect(() => {
    const activeOrders = orders.filter(o => o.status !== 'COMPLETED');
    if (activeOrders.length === 0) return;

    const timer = setInterval(() => {
      setOrders(prevOrders => {
        return prevOrders.map(order => {
          if (order.status === 'COMPLETED') return order;
          const statusFlow: OrderStatus[] = order.deliveryMode === 'pickup' 
            ? ['PLACED', 'PREPARING', 'READY', 'COMPLETED']
            : ['PLACED', 'PREPARING', 'READY', 'DELIVERING', 'COMPLETED'];

          const currentIndex = statusFlow.indexOf(order.status);
          if (currentIndex < statusFlow.length - 1) {
            const nextStatus = statusFlow[currentIndex + 1];
            if (order.id === orders[0].id) {
              const messages = {
                'PREPARING': `👨‍🍳 ${order.chefName} ha iniziato a cucinare!`,
                'READY': `✅ Il tuo piatto è pronto!`,
                'DELIVERING': `🛵 Il rider è partito con il tuo ordine!`,
                'COMPLETED': `🎉 Ordine completato! Buon appetito!`
              };
              showNotification(messages[nextStatus as keyof typeof messages] || "Stato ordine aggiornato");
              if (nextStatus === 'COMPLETED') {
                setTimeout(() => setReviewOrder(order), 2000);
              }
            }
            return { ...order, status: nextStatus };
          }
          return order;
        });
      });
    }, 15000);
    return () => clearInterval(timer);
  }, [orders]);

  const navigateTo = (view: ViewState) => {
    setCurrentView(view);
    if (view !== ViewState.CHEF_PROFILE) setSelectedChef(null);
    if (view !== ViewState.ORDERS) setSelectedOrder(null);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const copyQuickLink = async () => {
    const cleanUrl = getCleanUrl();
    const msg = `Prova la demo commerciale di MESA 5.5, l'app per il food delivery casalingo: ${cleanUrl}`;

    if (navigator.share) {
       try {
         await navigator.share({
           title: 'MESA 5.5 - Market Ready',
           text: msg,
           url: cleanUrl
         });
       } catch (err) {
         console.log("Condivisione OS annullata");
       }
    } else {
      try {
        await navigator.clipboard.writeText(msg);
        setLinkCopied(true);
        showNotification("Messaggio pronto per il lancio! 🚀");
        setTimeout(() => setLinkCopied(false), 3000);
      } catch (err) {
        setIsShareOpen(true);
      }
    }
  };

  const handleToggleFavorite = (dishId: string) => {
    setFavorites(prev => {
      if (prev.includes(dishId)) {
        showNotification("Rimosso dai preferiti");
        return prev.filter(id => id !== dishId);
      } else {
        showNotification("Aggiunto ai preferiti ❤️");
        return [...prev, dishId];
      }
    });
  };

  const handleInitiateBooking = (dish: Dish) => setBookingDish(dish);

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;
    setCart(prev => [...prev, { ...bookingDish, quantity: 1, scheduledDate: date, scheduledTime: time, deliveryMode, preferences }]);
    setBookingDish(null);
    showNotification("Piatto aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(i => i.quantity > 0));
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentSuccess = () => {
    const firstChefId = cart[0]?.chefId || 'c1';
    const chefName = MOCK_CHEFS.find(c => c.id === firstChefId)?.name || 'Chef';
    const newOrder: Order = {
      id: `ORDER-${Math.random().toString(36).substr(2, 9).toUpperCase()}`,
      items: [...cart],
      total: checkoutTotal,
      status: 'PLACED',
      timestamp: new Date(),
      chefId: firstChefId,
      chefName: chefName,
      deliveryMode: cart[0]?.deliveryMode || 'pickup',
      estimatedTime: '20:45'
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setSelectedOrder(newOrder);
    setCurrentView(ViewState.ORDERS);
    showNotification("Ordine ricevuto! Seguilo live.");
  };

  const handleReviewSubmit = (rating: number, comment: string) => {
    if (!reviewOrder) return;
    setOrders(prev => prev.map(o => o.id === reviewOrder.id ? { ...o, isReviewed: true } : o));
    setReviewOrder(null);
    showNotification("Grazie per la tua recensione! ⭐");
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const activeOrdersCount = orders.filter(o => o.status !== 'COMPLETED').length;

  const filteredChefs = useMemo(() => {
    return MOCK_CHEFS.map(chef => {
      // Filtro per nazionalità (OR tra le selezionate, se presenti)
      const matchesCountry = filters.countries.length === 0 || filters.countries.includes(chef.nationality);

      if (!matchesCountry) return null;

      const matchingDishes = chef.dishes.filter(dish => {
        const matchesPrice = dish.price <= filters.maxPrice;

        // Filtro per dieta (AND: deve rispettare tutte le diete selezionate)
        const matchesDietary = filters.dietary.length === 0 || 
          filters.dietary.every(filter => dish.dietary?.includes(filter as any));

        // Filtro per categorie (OR: deve avere almeno uno dei tag selezionati)
        const matchesCategories = filters.categories.length === 0 ||
          filters.categories.some(cat => dish.tags.includes(cat));

        const searchLower = filters.search.toLowerCase();
        const matchesSearch = !filters.search || 
          dish.name.toLowerCase().includes(searchLower) || 
          chef.name.toLowerCase().includes(searchLower);

        return matchesPrice && matchesDietary && matchesCategories && matchesSearch;
      });

      return matchingDishes.length > 0 ? { ...chef, dishes: matchingDishes } : null;
    }).filter(Boolean) as Chef[];
  }, [filters]);

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 selection:bg-orange-100 selection:text-orange-900 flex flex-col pb-20 md:pb-0">
      <Header 
        cartCount={cartCount} 
        orderCount={activeOrdersCount} 
        onCartClick={() => setIsCartOpen(true)} 
        currentView={currentView} 
        onNavigate={navigateTo} 
        onAuthClick={() => setIsAuthOpen(true)}
        onShareClick={() => setIsShareOpen(true)}
      />

      {currentView === ViewState.HOME && <FilterBar filters={filters} onFilterChange={setFilters} />}

      <main className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full mb-8">
        {/* Market Readiness Banner - v5.5 */}
        {currentView === ViewState.HOME && !filters.search && (
          <div className="mb-10 animate-fade-in">
             <div className="bg-orange-600 rounded-[3rem] p-10 flex flex-col lg:flex-row items-center justify-between gap-8 shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-64 h-64 bg-white rounded-full blur-[100px] opacity-20 -mr-32 -mt-32"></div>
                <div className="flex-1 relative z-10">
                   <div className="inline-flex items-center gap-2 px-4 py-1.5 bg-black text-orange-500 rounded-full text-[10px] font-black uppercase tracking-[0.2em] mb-6">
                      <ShieldCheck className="w-3 h-3" /> Partner Exclusive
                   </div>
                   <h2 className="text-4xl md:text-5xl font-black italic tracking-tighter mb-4 leading-none text-black">Scala il Tuo <br/>Business in <span className="underline decoration-black decoration-8 underline-offset-8">Cucina.</span></h2>
                   <p className="text-orange-900 font-bold max-w-lg text-lg mb-8 leading-relaxed opacity-80">
                      Unisciti a oltre 500 cuochi casalinghi che hanno già scelto MESA per digitalizzare la propria passione.
                   </p>
                   <button 
                    onClick={() => setIsOnboardingOpen(true)}
                    className="px-10 py-5 bg-black text-white rounded-3xl font-black uppercase tracking-widest text-xs hover:bg-white hover:text-black transition-all shadow-2xl active:scale-95 flex items-center gap-3"
                   >
                     <ChefHat className="w-5 h-5" />
                     Inizia l'Onboarding
                   </button>
                </div>
                <div className="w-full lg:w-72 bg-black/10 backdrop-blur-md rounded-[2.5rem] p-8 border border-black/5 relative z-10 flex flex-col items-center text-center">
                   <div className="w-16 h-16 bg-black rounded-2xl flex items-center justify-center text-orange-500 mb-4 shadow-xl">
                      <TrendingUp className="w-8 h-8" />
                   </div>
                   <p className="text-[10px] font-black uppercase text-black/50 tracking-widest mb-1">Crescita stimata</p>
                   <p className="text-3xl font-black text-black italic leading-none">+45%</p>
                   <p className="text-[9px] font-bold text-black/60 uppercase mt-2">Visibilità di Quartiere</p>
                </div>
             </div>
          </div>
        )}

        {currentView === ViewState.HOME && !filters.search && <ActivityFeed />}

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!filters.search && (
              <>
                <div className="text-center mb-12 py-10 bg-black rounded-[3rem] text-white shadow-2xl relative overflow-hidden border-b-8 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-30 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?ixlib=rb-1.2.1&auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center"></div>
                  <div className="relative z-10 px-6">
                    <h1 className="text-5xl md:text-7xl font-black mb-2 tracking-tighter italic leading-none">MESA <span className="text-orange-600 text-3xl align-top">5.5</span></h1>
                    <p className="text-lg font-bold text-orange-500 uppercase tracking-widest mb-6">Market Readiness Edition. Supply Scaling Active.</p>
                    <div className="flex justify-center space-x-4">
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Launch Status</p>
                          <p className="text-xl font-black text-green-500">READY</p>
                       </div>
                       <div className="bg-white/10 backdrop-blur px-4 py-2 rounded-2xl border border-white/20">
                          <p className="text-[10px] font-black uppercase text-gray-400">Versione</p>
                          <p className="text-xl font-black">G-5.5</p>
                       </div>
                    </div>
                  </div>
                </div>
                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
              </>
            )}
            <div className="mb-8 flex items-center justify-between">
              <h2 className="text-2xl font-black text-gray-900">Cuochi Certificati MESA</h2>
            </div>
            <div className="space-y-10">
               {filteredChefs.map(chef => (
                 <ChefCard key={chef.id} chef={chef} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
               ))}
            </div>
          </div>
        )}

        {currentView === ViewState.CHEFS && <MesaChefs chefs={MOCK_CHEFS} onViewProfile={handleViewProfile} />}
        {currentView === ViewState.CULTURE && <CultureSection />}
        {currentView === ViewState.FAVORITES && <FavoritesSection favorites={favorites} chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} onToggleFavorite={handleToggleFavorite} />}
        {currentView === ViewState.ORDERS && (
          selectedOrder 
            ? <OrderTracking order={orders.find(o => o.id === selectedOrder.id) || selectedOrder} onBack={() => setSelectedOrder(null)} />
            : (
              <div className="animate-fade-in space-y-6">
                <h2 className="text-3xl font-black text-gray-900 mb-8 tracking-tight">I Miei Ordini</h2>
                {orders.length === 0 ? <p className="text-gray-400 font-bold py-20 text-center bg-gray-50 rounded-[3rem]">Il motore ordini è pronto per il tuo test!</p> : orders.map(order => (
                  <div key={order.id} onClick={() => setSelectedOrder(order)} className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm hover:shadow-xl transition-all cursor-pointer flex justify-between items-center group">
                    <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">#{order.id.split('-')[0]}</p>
                      <h4 className="font-bold text-xl text-gray-900">{order.chefName}</h4>
                      <p className="text-xs text-gray-500">{order.items.length} piatti • € {order.total.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center space-x-4">
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${order.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700 animate-pulse'}`}>{order.status}</span>
                      {order.status === 'COMPLETED' && !order.isReviewed && (
                        <button 
                          onClick={(e) => { e.stopPropagation(); setReviewOrder(order); }}
                          className="bg-orange-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-black transition-colors"
                        >Recensisci</button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )
        )}
        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile 
            chef={selectedChef} 
            onBack={() => navigateTo(ViewState.HOME)} 
            onAddDish={handleInitiateBooking} 
            favorites={favorites} 
            onToggleFavorite={handleToggleFavorite}
            onNavigateToCulture={() => navigateTo(ViewState.CULTURE)}
          />
        )}
        {currentView === ViewState.AI_MENU_CREATOR && <AiMenuCreator />}
        {currentView === ViewState.ADMIN_DASHBOARD && <AdminDashboard chefs={MOCK_CHEFS} orders={orders} />}
        {[ViewState.ABOUT, ViewState.SAFETY, ViewState.BECOME_CHEF, ViewState.HELP, ViewState.TERMS, ViewState.PRIVACY].includes(currentView) && (
          <InfoPage view={currentView} onBack={() => navigateTo(ViewState.HOME)} />
        )}
      </main>

      <Footer onNavigate={navigateTo} />
      <BottomNav currentView={currentView} onNavigate={navigateTo} />

      <BookingModal isOpen={!!bookingDish} onClose={() => setBookingDish(null)} dish={bookingDish!} chef={MOCK_CHEFS.find(c => c.id === bookingDish?.chefId)} onConfirm={handleConfirmBooking} />
      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} onUpdateQuantity={handleUpdateQuantity} onCheckout={handleCheckout} onAddDish={handleInitiateBooking} availableChefs={MOCK_CHEFS} />
      <PaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} total={checkoutTotal} onSuccess={handlePaymentSuccess} />
      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onAdminLogin={() => navigateTo(ViewState.ADMIN_DASHBOARD)} />
      <OrderReviewModal isOpen={!!reviewOrder} onClose={() => setReviewOrder(null)} order={reviewOrder!} onSubmit={handleReviewSubmit} />
      <ShareModal isOpen={isShareOpen} onClose={() => setIsShareOpen(false)} />
      <ChefOnboarding isOpen={isOnboardingOpen} onClose={() => setIsOnboardingOpen(false)} />
