  const countryOptions = Array.from(new Set(MOCK_CHEFS.map(chef => chef.nationality))).sort();

  const toggleDietary = (option: string) => {
    const current = filters.dietary;
    const next = current.includes(option)
      ? current.filter(d => d !== option)
      : [...current, option];
    onFilterChange({ ...filters, dietary: next });
  };

  const toggleCategory = (option: string) => {
    const current = filters.categories || [];
    const next = current.includes(option)
      ? current.filter(c => c !== option)
      : [...current, option];
    onFilterChange({ ...filters, categories: next });
  };

  const toggleCountry = (option: string) => {
    const current = filters.countries || [];
    const next = current.includes(option)
      ? current.filter(c => c !== option)
      : [...current, option];
    onFilterChange({ ...filters, countries: next });
  };

  const activeFiltersCount = 
    filters.dietary.length + 
    (filters.categories?.length || 0) + 
    (filters.countries?.length || 0) + 
    (filters.maxPrice < 50 ? 1 : 0);

  return (
    <div className="bg-white border-b border-orange-100 py-3 sticky top-20 z-40 shadow-sm transition-all duration-300">
      <div className="max-w-6xl mx-auto px-4">
        <div className="flex items-center gap-2">
          {/* Search Input */}
          <div className="relative flex-1">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Search className="h-4 w-4 text-gray-400" />
            </div>
            <input
              type="text"
              placeholder="Cerca piatti o chef..."
              className="block w-full pl-9 pr-3 py-2.5 border border-gray-200 rounded-2xl bg-gray-50 text-sm focus:outline-none focus:ring-2 focus:ring-orange-500 focus:bg-white transition-all"
              value={filters.search}
              onChange={(e) => onFilterChange({ ...filters, search: e.target.value })}
            />
          </div>

          {/* Toggle Button */}
          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className={`flex items-center gap-2 px-4 py-2.5 rounded-2xl border text-sm font-bold transition-all ${
              isExpanded || activeFiltersCount > 0 
                ? 'bg-orange-600 border-orange-600 text-white' 
                : 'bg-white border-gray-200 text-gray-700 hover:border-orange-300'
            }`}
          >
            <SlidersHorizontal className="w-4 h-4" />
            <span className="hidden sm:inline">Filtri</span>
            {activeFiltersCount > 0 && (
              <span className="bg-white text-orange-600 w-5 h-5 rounded-full flex items-center justify-center text-[10px]">
                {activeFiltersCount}
              </span>
            )}
            {isExpanded ? <ChevronUp className="w-4 h-4 ml-1" /> : <ChevronDown className="w-4 h-4 ml-1" />}
          </button>
        </div>

        {/* Collapsible Section */}
        {isExpanded && (
          <div className="mt-4 pt-4 border-t border-gray-100 animate-fade-in space-y-6">

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {/* Price Range */}
              <div>
                <div className="flex justify-between items-center mb-3">
                  <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Budget Massimo</span>
                  <span className="text-sm font-extrabold text-orange-600 bg-orange-50 px-3 py-1 rounded-xl border border-orange-100">€ {filters.maxPrice}</span>
                </div>
                <input
                  type="range"
                  min="5"
                  max="50"
                  step="1"
                  value={filters.maxPrice}
                  onChange={(e) => onFilterChange({ ...filters, maxPrice: parseInt(e.target.value) })}
                  className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-orange-600"
                />
              </div>

              {/* Category Filters */}
              <div>
                <span className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-3">Tipo di Piatto</span>
                <div className="flex flex-wrap gap-2">
                  {categoryOptions.map(cat => {
                    const Icon = cat.icon;
                    const isSelected = filters.categories?.includes(cat.name);
                    return (
                      <button
                        key={cat.name}
                        onClick={() => toggleCategory(cat.name)}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all border-2 ${
                          isSelected
                            ? 'bg-orange-100 text-orange-800 border-orange-500 shadow-sm'
                            : 'bg-white text-gray-600 border-gray-100 hover:border-orange-200'
                        }`}
                      >
                        <Icon className="w-4 h-4" />
                        <span>{cat.name}</span>
                      </button>
                    );
                  })}
                </div>
              </div>
            </div>

            {/* Countries Filter */}
            <div>
              <div className="flex items-center justify-between mb-3">
                <div className="flex items-center gap-2">
                   <Globe className="w-4 h-4 text-orange-600" />
                   <span className="text-xs font-black text-gray-400 uppercase tracking-widest block">Origine della Cucina</span>
                </div>
                {filters.countries.length > 0 && (
                  <span className="text-[10px] font-black text-orange-600 uppercase tracking-widest animate-pulse">
                    {filters.countries.length} selezionati
                  </span>
                )}
              </div>

              {/* Selected Countries Labels Area */}
              {filters.countries.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-4 animate-fade-in">
                  {filters.countries.map(emoji => (
                    <div key={emoji} className="flex items-center gap-2 px-3 py-1 bg-black text-white rounded-full text-[10px] font-black uppercase tracking-widest">
                      <span>{emoji} {nationalityNames[emoji] || 'Paese'}</span>
                      <button onClick={() => toggleCountry(emoji)} className="hover:text-orange-500">
                        <X className="w-3 h-3" />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div className="flex flex-wrap gap-2">
                {countryOptions.map(country => {
                  const isSelected = filters.countries.includes(country);
                  return (
                    <button
                      key={country}
                      onClick={() => toggleCountry(country)}
                      className={`flex items-center gap-2 px-4 py-2.5 rounded-xl transition-all border-2 ${
                        isSelected
                          ? 'bg-orange-600 border-orange-600 shadow-lg scale-110 z-10 text-white'
                          : 'bg-white border-gray-100 grayscale hover:grayscale-0 hover:border-orange-200 text-lg'
                      }`}
                      title={nationalityNames[country] || `Filtra per ${country}`}
                    >
                      <span>{country}</span>
                      {isSelected && (
                        <span className="text-[10px] font-black uppercase tracking-widest ml-1 hidden sm:inline">
                          {nationalityNames[country]}
                        </span>
                      )}
                    </button>
                  );
                })}
                {filters.countries.length > 0 && (
                   <button 
                    onClick={() => onFilterChange({ ...filters, countries: [] })}
                    className="px-4 py-2.5 text-[10px] font-black uppercase tracking-widest text-gray-400 hover:text-red-500"
                   >
                     Reset Origine
                   </button>
                )}
              </div>
            </div>

            {/* Dietary Filters */}
            <div>
              <span className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-3">Esigenze Alimentari</span>
              <div className="flex flex-wrap gap-2">
                {dietaryOptions.map(option => (
                  <button
                    key={option}
                    onClick={() => toggleDietary(option)}
                    className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-xs font-black uppercase tracking-wider transition-all border-2 ${
                      filters.dietary.includes(option)
                        ? 'bg-green-100 text-green-700 border-green-500'
                        : 'bg-white text-gray-600 border-gray-100 hover:border-green-200'
                    }`}
                  >
                    <Leaf className="w-3.5 h-3.5" />
                    <span>{option}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="flex justify-between items-center pt-4 border-t border-gray-100">
               <button 
                onClick={() => onFilterChange({ search: '', maxPrice: 50, dietary: [], categories: [], countries: [] })}
                className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-300 hover:text-red-500 transition-colors"
               >
                 Azzera tutto
               </button>
               <button 
                onClick={() => setIsExpanded(false)}
                className="px-8 py-3 bg-black text-white text-[10px] font-black uppercase tracking-widest rounded-xl shadow-lg hover:bg-orange-600 transition-all active:scale-95"
               >
                 Applica Filtri
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

