              >
                <ClipboardList className="w-4 h-4" />
                <span className="hidden lg:inline">Ordini</span>
                {orderCount > 0 && (
                  <span className="absolute -top-1.5 -right-2 inline-flex items-center justify-center px-1.5 py-0.5 text-[9px] font-black leading-none text-black bg-orange-500 rounded-full border border-black animate-pulse">
                    {orderCount}
                  </span>
                )}
              </button>

              <button 
                onClick={() => onNavigate(ViewState.CULTURE)}
                className={`flex items-center space-x-1 text-[11px] lg:text-sm font-bold uppercase tracking-wide transition-colors ${currentView === ViewState.CULTURE ? 'text-orange-500' : 'text-gray-400 hover:text-white'}`}
              >
                <Globe className="w-4 h-4" />
