interface FilterBarProps {
  filters: FilterState;
  onFilterChange: (filters: FilterState) => void;
}

export const FilterBar: React.FC<FilterBarProps> = ({ filters, onFilterChange }) => {
  const [isExpanded, setIsExpanded] = useState(false);

  const dietaryOptions = ['Vegetarian', 'Vegan', 'Gluten Free', 'Lactose Free'];
  const categoryOptions = [
    { name: 'Carne', icon: Drumstick },
    { name: 'Pesce', icon: Fish },
    { name: 'Piccante', icon: Flame },
  ];

  const countryOptions = Array.from(new Set(MOCK_CHEFS.map(chef => chef.nationality))).sort();

  const toggleCountry = (option: string) => {
    const current = filters.countries || [];
    const next = current.includes(option)
      ? current.filter(c => c !== option)
      : [...current, option];
    onFilterChange({ ...filters, countries: next });
  };

  const activeFiltersCount = 
    filters.dietary.length + 
    (filters.categories?.length || 0) + 
    (filters.countries?.length || 0) + 
    (filters.maxPrice < 50 ? 1 : 0);

  return (
    <div className="bg-white border-b border-orange-100 py-3 sticky top-20 z-40 shadow-sm">
      <div className="max-w-6xl mx-auto px-4">
        <div className="flex items-center gap-2">
          <div className="relative flex-1">
            <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
              <Search className="h-5 w-5 text-orange-500" />
            </div>
            <input
              type="text"
              placeholder="Cerca piatto (es. Lasagna), nazione (es. Marocco) o chef..."
              className="block w-full pl-12 pr-4 py-3 border-2 border-gray-100 rounded-2xl bg-gray-50 text-sm font-bold focus:outline-none focus:border-orange-500 focus:bg-white transition-all shadow-inner"
              value={filters.search}
              onChange={(e) => onFilterChange({ ...filters, search: e.target.value })}
            />
            {filters.search && (
              <button 
                onClick={() => onFilterChange({ ...filters, search: '' })}
                className="absolute inset-y-0 right-0 pr-4 flex items-center text-gray-400 hover:text-orange-600"
              >
                <X className="h-4 w-4" />
              </button>
            )}
          </div>

          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className={`flex items-center gap-2 px-6 py-3 rounded-2xl border-2 text-sm font-black uppercase tracking-widest transition-all ${
              isExpanded || activeFiltersCount > 0 
                ? 'bg-black border-black text-white' 
                : 'bg-white border-gray-100 text-gray-700 hover:border-orange-500'
            }`}
          >
            <SlidersHorizontal className="w-4 h-4" />
            <span className="hidden sm:inline">Filtri</span>
            {isExpanded ? <ChevronUp className="w-4 h-4 ml-1" /> : <ChevronDown className="w-4 h-4 ml-1" />}
          </button>
        </div>

        {isExpanded && (
          <div className="mt-4 pt-4 border-t border-gray-100 animate-fade-in space-y-6">
            <div>
              <span className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-3">Origine</span>
              <div className="flex flex-wrap gap-2">
                {countryOptions.map(country => (
                  <button
                    key={country}
                    onClick={() => toggleCountry(country)}
                    className={`p-3 rounded-xl transition-all border-2 text-xl ${
                      filters.countries.includes(country)
                        ? 'bg-orange-50 border-orange-500 scale-110 shadow-md'
                        : 'bg-white border-gray-100 grayscale hover:grayscale-0'
                    }`}
                  >
                    {country}
                  </button>
                ))}
              </div>
            </div>
            <div className="flex justify-end">
               <button 
                onClick={() => setIsExpanded(false)}
                className="px-8 py-3 bg-orange-600 text-black text-[10px] font-black uppercase tracking-widest rounded-xl shadow-lg active:scale-95"
               >
                 Chiudi Filtri
               </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
