      <BookingModal isOpen={!!bookingDish} onClose={() => setBookingDish(null)} dish={bookingDish!} chef={MOCK_CHEFS.find(c => c.id === bookingDish?.chefId)} onConfirm={handleConfirmBooking} />
      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} onUpdateQuantity={() => {}} onCheckout={() => {}} onAddDish={handleInitiateBooking} availableChefs={MOCK_CHEFS} />
      <PaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} total={checkoutTotal} onSuccess={() => {}} />
      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onAdminLogin={() => navigateTo(ViewState.ADMIN_DASHBOARD)} />
      <OrderReviewModal isOpen={!!reviewOrder} onClose={() => setReviewOrder(null)} order={reviewOrder!} onSubmit={() => {}} />
      <ShareModal isOpen={isShareOpen} onClose={() => setIsShareOpen(false)} />
      <ChefOnboarding isOpen={isOnboardingOpen} onClose={() => setIsOnboardingOpen(false)} />
      <NotificationToast message={toastMessage} isVisible={isToastVisible} onClose={() => setIsToastVisible(false)} />

      {showTour && <LaunchTour onComplete={() => { setShowTour(false); localStorage.setItem('mesa_launch_tour_v60', 'true'); }} />}
      <AiConcierge />
    </div>
  );
}

export default App;

