                     <span className="ml-2">{expandedDishId === dish.id ? 'Chiudi Dettagli' : 'Segreti della Ricetta'}</span>
                   </button>
                   {expandedDishId === dish.id && (
                     <div className="pt-2 pb-4 space-y-4 animate-fade-in border-t border-white/40">
                        <div>
                          <p className="text-[9px] font-black text-orange-600 uppercase tracking-widest mb-1">Ingredienti di Famiglia</p>
                          <p className="text-xs text-gray-600 leading-relaxed font-medium">{dish.ingredients?.join(', ') || 'Ingredienti segreti'}</p>
                        </div>
                        <div>
                          <p className="text-[9px] font-black text-orange-600 uppercase tracking-widest mb-1">La Tecnica</p>
                          <p className="text-xs text-gray-600 leading-relaxed italic font-medium">"{dish.preparation || 'Metodo segreto tramandato dallo chef.'}"</p>
                        </div>
                     </div>
                   )}
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[3rem] p-8 border border-gray-100 shadow-sm">
          <ReviewList reviews={chef.reviews} />
        </div>
      )}

      {/* Logistics Sidebar-like footer for profile */}
      <div className="mt-12 grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="bg-gray-50 p-8 rounded-[2.5rem] border border-gray-100">
           <h3 className="text-lg font-black text-gray-900 mb-6 flex items-center">
             <Clock className="w-5 h-5 mr-3 text-orange-600" />
             Disponibilità Prossimi Giorni
           </h3>
           <ChefAvailabilityCalendar availableDays={chef.availableDays} />
        </div>
        <div className="bg-orange-50 p-8 rounded-[2.5rem] border border-orange-100 flex flex-col justify-center text-center">
           <Heart className="w-12 h-12 text-orange-600 mx-auto mb-4 fill-current animate-pulse" />
           <h3 className="text-2xl font-black text-orange-900 mb-2">Supporta {chef.name}</h3>
           <p className="text-sm text-orange-700 font-medium mb-6">
             Ogni tuo ordine aiuta a preservare tradizioni culinarie autentiche e sostiene l'economia locale del quartiere.
           </p>
           <button className="px-8 py-4 bg-black text-white rounded-2xl font-black uppercase tracking-widest text-xs hover:bg-orange-600 transition-all shadow-xl">
             Iscriviti ai suoi aggiornamenti
           </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
