  preparation?: string;
}

export type Continent = 'Europa' | 'Asia' | 'Africa' | 'Americhe' | 'Oceania';

export interface Chef {
  id: string;
  name: string;
  nationality: string; 
  continent: Continent;
  bio: string;
  fullBio?: string;
  avatar: string;
  rating: number;
  location: string;
  distance: number; 
  specialties: string[];
  availability: string[]; 
  availableDays: number[]; 
  reviews: Review[];
  dishes: Dish[];
}

export type OrderStatus = 'PLACED' | 'PREPARING' | 'READY' | 'DELIVERING' | 'COMPLETED';

export interface Message {
  id: string;
  sender: 'user' | 'chef';
  text: string;
  timestamp: Date;
}

export interface Order {
  id: string;
  items: CartItem[];
  total: number;
  status: OrderStatus;
  timestamp: Date;
  chefId: string;
  chefName: string;
  deliveryMode: 'delivery' | 'pickup';
  estimatedTime: string;
