import React, { useState, useEffect } from 'react';
import { X, Copy, Check, Share2, QrCode as QrIcon, Mail, MessageCircle, Send, Edit2, Rocket, Briefcase, UserPlus, Link, AlertCircle, ShieldCheck, Smartphone, ExternalLink } from 'lucide-react';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
}

export const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose }) => {
  const [copied, setCopied] = useState(false);
  const [customUrl, setCustomUrl] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState<'investor' | 'tester' | 'partner'>('tester');
  const [isEditingLink, setIsEditingLink] = useState(false);
  const [qrLoaded, setQrLoaded] = useState(false);

  useEffect(() => {
    if (typeof window !== 'undefined' && isOpen && !customUrl) {
      const url = window.location.origin + window.location.pathname;
      setCustomUrl(url);
    }
  }, [isOpen]);

  const templates = {
    investor: {
      label: "Investitore",
      icon: <Briefcase className="w-4 h-4" />,
      text: (url: string) => `Buongiorno, ti invito a visionare l'anteprima funzionale di MESA 5.0, piattaforma di food delivery basata sulla sharing economy. Demo live: ${url}`
    },
    tester: {
      label: "Tester",
      icon: <UserPlus className="w-4 h-4" />,
      text: (url: string) => `Ciao! Sto testando MESA, una nuova app per ordinare piatti fatti in casa da cuochi fantastici. Ti andrebbe di provarla? Link: ${url}`
    },
    partner: {
      label: "Partner/Chef",
      icon: <Rocket className="w-4 h-4" />,
      text: (url: string) => `Ehi, guarda questa nuova piattaforma per cuochi casalinghi. Penso che potresti guadagnare bene condividendo i tuoi piatti! Link: ${url}`
    }
  };

  if (!isOpen) return null;

  const fullMessage = templates[selectedTemplate].text(customUrl);
  const isLocalhost = customUrl.includes('localhost') || customUrl.includes('127.0.0.1');

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(fullMessage);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      alert("Copia fallita. Usa il tasto Condivisione Nativa o inquadra il QR Code.");
    }
  };

  const handleNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: 'MESA 5.0 - Demo',
          text: fullMessage,
          url: customUrl,
        });
      } catch (err) {
        console.log("Condivisione annullata");
      }
    } else {
      handleCopy();
    }
  };

  const handleSocialShare = (platform: 'whatsapp' | 'telegram' | 'email') => {
    const text = encodeURIComponent(fullMessage);
    const links = {
      whatsapp: `https://wa.me/?text=${text}`,
      telegram: `https://t.me/share/url?url=${encodeURIComponent(customUrl)}&text=${text}`,
      email: `mailto:?subject=Invito Progetto MESA&body=${text}`
    };
    window.open(links[platform], '_blank');
  };

  // Usiamo un servizio esterno per generare il QR Code basato sul link attuale
  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(customUrl)}`;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/95 backdrop-blur-xl animate-fade-in" onClick={onClose} />

      <div className="relative bg-white w-full max-w-xl rounded-[4rem] shadow-2xl overflow-hidden animate-fade-in-up border border-gray-100 flex flex-col md:flex-row">

        {/* Lato Sinistro: QR Code & Stato */}
        <div className="bg-black p-10 text-white flex flex-col items-center justify-center text-center md:w-56 shrink-0 border-b md:border-b-0 md:border-r border-white/10">
          <p className="text-[10px] font-black uppercase tracking-[0.3em] text-orange-500 mb-6">Inquadra per Provare</p>
          <div className="relative bg-white p-4 rounded-[2.5rem] shadow-[0_0_40px_rgba(249,115,22,0.3)] group">
             {!qrLoaded && <div className="absolute inset-0 flex items-center justify-center bg-white rounded-[2.5rem]"><div className="w-5 h-5 border-2 border-orange-500 border-t-transparent rounded-full animate-spin"></div></div>}
             <img 
               src={qrCodeUrl} 
               alt="QR Code Link" 
               className="w-32 h-32 md:w-36 md:h-36" 
               onLoad={() => setQrLoaded(true)}
             />
          </div>
          <div className="mt-8 space-y-3">
             <div className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest ${isLocalhost ? 'text-red-500' : 'text-green-500'}`}>
                {isLocalhost ? <AlertCircle className="w-3 h-3" /> : <ShieldCheck className="w-3 h-3" />}
                {isLocalhost ? 'Rilevato Localhost' : 'Link Globale OK'}
             </div>
             <p className="text-[8px] text-gray-500 leading-relaxed font-bold uppercase tracking-tighter">
                {isLocalhost ? 'Questo link non funzionerà sui cellulari altrui. Usa un URL pubblico.' : 'Link testato e pronto per la distribuzione globale.'}
             </p>
          </div>
        </div>

        {/* Lato Destro: Messaggio & Link */}
        <div className="p-8 md:p-10 flex-1">
          <div className="flex justify-between items-center mb-6">
            <h2 className="text-2xl font-black text-gray-900 tracking-tighter italic">Lancio MESA 5.0</h2>
            <button onClick={onClose} className="p-2 text-gray-300 hover:text-black transition-colors">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="mb-6">
            <div className="flex items-center justify-between mb-2">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">URL di Prova</p>
              <button 
                onClick={() => setIsEditingLink(!isEditingLink)}
                className="text-[9px] font-black text-orange-600 uppercase flex items-center gap-1"
              >
                <Edit2 className="w-3 h-3" /> {isEditingLink ? 'Conferma' : 'Modifica'}
              </button>
            </div>
            <div className={`p-4 rounded-2xl border-2 flex items-center gap-3 transition-all ${isEditingLink ? 'border-orange-500 bg-white ring-4 ring-orange-50' : 'border-gray-50 bg-gray-50'}`}>
              <Link className={`w-4 h-4 ${isEditingLink ? 'text-orange-500' : 'text-gray-300'}`} />
              <input 
                type="text"
                value={customUrl}
                readOnly={!isEditingLink}
                onChange={(e) => setCustomUrl(e.target.value)}
                className="bg-transparent flex-1 text-xs font-bold text-gray-700 outline-none"
              />
            </div>
          </div>

          <div className="flex gap-2 mb-8">
            {(Object.keys(templates) as Array<keyof typeof templates>).map((t) => (
              <button
                key={t}
                onClick={() => setSelectedTemplate(t)}
                className={`flex-1 py-3 rounded-2xl text-[9px] font-black uppercase tracking-widest flex items-center justify-center gap-2 transition-all border-2 ${
                  selectedTemplate === t ? 'bg-black text-white border-black shadow-xl' : 'bg-white border-gray-100 text-gray-400 hover:border-orange-200'
                }`}
              >
                {templates[t].label}
              </button>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2.5rem] border border-gray-100 mb-8">
            <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest mb-2">Anteprima</p>
            <p className="text-[11px] font-bold text-gray-600 leading-relaxed italic">"{fullMessage}"</p>
          </div>

          <div className="space-y-3">
             <button 
                onClick={handleNativeShare}
                className="w-full flex items-center justify-center gap-3 py-5 bg-orange-600 text-black rounded-3xl font-black uppercase tracking-widest text-xs hover:bg-black hover:text-white transition-all shadow-xl active:scale-95"
              >
                <Share2 className="w-5 h-5" />
                <span>Condivisione Nativa OS</span>
              </button>

              <div className="flex gap-2">
                <button 
                  onClick={handleCopy}
                  className={`flex-1 flex items-center justify-center gap-2 py-4 rounded-2xl font-black uppercase tracking-widest text-[10px] border-2 transition-all ${copied ? 'bg-green-500 text-white border-green-500' : 'bg-white border-gray-200 text-gray-900'}`}
                >
                  {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                  {copied ? 'Copiato' : 'Copia Testo'}
                </button>
                <button 
                  onClick={() => handleSocialShare('whatsapp')}
                  className="px-6 py-4 bg-green-50 text-green-600 rounded-2xl flex items-center justify-center hover:bg-green-600 hover:text-white transition-all"
                >
                  <MessageCircle className="w-5 h-5" />
                </button>
              </div>
          </div>
        </div>
      </div>
    </div>
  );
};

