import React, { useState, useEffect } from 'react';
import { 
  X, Copy, Check, Share2, Mail, 
  MessageCircle, Send, Edit2, Rocket, Briefcase, 
  UserPlus, Link, AlertCircle, ShieldCheck, 
  ExternalLink, ShoppingCart, Loader2, MessageSquare 
} from 'lucide-react';

interface ShareModalProps {
  isOpen: boolean;
  onClose: () => void;
  initialTemplate?: 'investor' | 'tester' | 'partner' | 'storefront';
  contextChefId?: string;
}

export const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose, initialTemplate = 'storefront', contextChefId }) => {
  const [copied, setCopied] = useState(false);
  const [customUrl, setCustomUrl] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState<'investor' | 'tester' | 'partner' | 'storefront'>(initialTemplate);
  const [isEditingLink, setIsEditingLink] = useState(false);
  const [qrLoaded, setQrLoaded] = useState(false);

  useEffect(() => {
    if (typeof window !== 'undefined' && isOpen) {
      // Cattura il dominio reale o l'URL di anteprima corrente
      const baseUrl = window.location.origin + window.location.pathname;
      const url = contextChefId ? `${baseUrl}?chef=${contextChefId}` : baseUrl;
      setCustomUrl(url);
      setQrLoaded(false);
    }
  }, [isOpen, contextChefId]);

  const templates = {
    storefront: {
      label: "Vetrina",
      icon: <ShoppingCart className="w-4 h-4" />,
      text: (url: string) => contextChefId 
        ? `Fame di qualcosa di autentico? Scopri la mia vetrina su MESA! Piatti fatti in casa pronti per te. Ordina qui: ${url}`
        : `Scopri MESA: il nuovo modo di ordinare piatti fatti in casa dai migliori talenti del quartiere! ${url}`
    },
    investor: {
      label: "Investor",
      icon: <Briefcase className="w-4 h-4" />,
      text: (url: string) => `Buongiorno, ti invito a visionare l'anteprima funzionale di MESA 5.0, piattaforma di food delivery basata sulla sharing economy. Demo live: ${url}`
    },
    tester: {
      label: "Tester",
      icon: <UserPlus className="w-4 h-4" />,
      text: (url: string) => `Ciao! Sto testando MESA, una nuova app per ordinare piatti fatti in casa da cuochi fantastici. Ti andrebbe di provarla? Link: ${url}`
    },
    partner: {
      label: "Partner",
      icon: <Rocket className="w-4 h-4" />,
      text: (url: string) => `Ehi, guarda questa nuova piattaforma per cuochi casalinghi. Penso che potresti guadagnare bene condividendo i tuoi piatti! Link: ${url}`
    }
  };

  if (!isOpen) return null;

  const fullMessage = templates[selectedTemplate].text(customUrl);
  const isLocalhost = customUrl.includes('localhost') || customUrl.includes('127.0.0.1');

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(fullMessage);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Copia fallita", err);
    }
  };

  const handleNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: 'MESA - Vetrina Pubblica',
          text: fullMessage,
          url: customUrl,
        });
      } catch (err) {
        console.log("Condivisione annullata");
      }
    } else {
      handleCopy();
    }
  };

  const handleSocialShare = (platform: 'whatsapp' | 'telegram' | 'email') => {
    const text = encodeURIComponent(fullMessage);
    const links = {
      whatsapp: `https://wa.me/?text=${text}`,
      telegram: `https://t.me/share/url?url=${encodeURIComponent(customUrl)}&text=${text}`,
      email: `mailto:?subject=Invito Progetto MESA&body=${text}`
    };
    window.open(links[platform], '_blank');
  };

  const qrCodeUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(customUrl)}&bgcolor=ffffff&color=000000&margin=1`;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="fixed inset-0 bg-black/95 backdrop-blur-xl animate-fade-in" onClick={onClose} />

      <div className="relative bg-white w-full max-w-2xl rounded-[4rem] shadow-2xl overflow-hidden animate-fade-in-up border border-gray-100 flex flex-col md:flex-row max-h-[90vh]">

        {/* Lato Sinistro: QR Code & Diagnostica */}
        <div className="bg-black p-8 text-white flex flex-col items-center justify-center text-center md:w-64 shrink-0 border-b md:border-b-0 md:border-r border-white/10">
          <div className="w-12 h-12 bg-orange-600 rounded-2xl flex items-center justify-center mb-6 shadow-lg shadow-orange-900/20">
             <Share2 className="w-6 h-6 text-black" />
          </div>
          <p className="text-[10px] font-black uppercase tracking-[0.3em] text-orange-500 mb-6">MESA Access</p>
          <div className="relative bg-white p-4 rounded-[2.5rem] shadow-[0_0_50px_rgba(249,115,22,0.4)] group aspect-square flex items-center justify-center w-full max-w-[180px]">
             {!qrLoaded && <div className="absolute inset-0 flex items-center justify-center bg-white rounded-[2.5rem]"><Loader2 className="w-6 h-6 text-orange-500 animate-spin" /></div>}
             <img 
               src={qrCodeUrl} 
               alt="QR Code" 
               className={`w-full h-full transition-opacity duration-500 ${qrLoaded ? 'opacity-100' : 'opacity-0'}`} 
               onLoad={() => setQrLoaded(true)}
             />
          </div>
          <div className="mt-8 space-y-3">
             <div className={`flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest ${isLocalhost ? 'text-red-500' : 'text-green-500'}`}>
                {isLocalhost ? <AlertCircle className="w-3 h-3" /> : <ShieldCheck className="w-3 h-3" />}
                {isLocalhost ? 'Ambiente Locale' : 'Link Pubblico'}
             </div>
             <p className="text-[9px] text-gray-500 leading-relaxed font-bold uppercase tracking-tight">
                {isLocalhost ? 'Attenzione: condividi questo link solo se sei in produzione.' : 'Il link è pronto per essere distribuito globalmente.'}
             </p>
          </div>
        </div>

        {/* Lato Destro: Configurazione Condivisione */}
        <div className="p-8 md:p-12 flex-1 overflow-y-auto">
          <div className="flex justify-between items-center mb-8">
            <div>
               <h2 className="text-3xl font-black text-gray-900 tracking-tighter italic leading-none">Condividi</h2>
               <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-2">MESA Share v2.7</p>
            </div>
            <button onClick={onClose} className="p-3 text-gray-300 hover:text-black transition-colors rounded-full hover:bg-gray-50">
              <X className="w-6 h-6" />
            </button>
          </div>

          <div className="mb-8">
            <div className="flex items-center justify-between mb-3 px-1">
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">URL Pubblico</p>
              <button 
                onClick={() => setIsEditingLink(!isEditingLink)}
                className="text-[10px] font-black text-orange-600 uppercase flex items-center gap-1.5 hover:underline"
              >
                <Edit2 className="w-3 h-3" /> {isEditingLink ? 'Salva' : 'Modifica'}
              </button>
            </div>
            <div className={`p-5 rounded-3xl border-2 flex items-center gap-4 transition-all ${isEditingLink ? 'border-orange-500 bg-white shadow-xl shadow-orange-50' : 'border-gray-50 bg-gray-50'}`}>
              <div className={`p-2 rounded-xl ${isEditingLink ? 'bg-orange-100 text-orange-600' : 'bg-gray-200 text-gray-400'}`}>
                <Link className="w-4 h-4" />
              </div>
              <input 
                type="text"
                value={customUrl}
                readOnly={!isEditingLink}
                onChange={(e) => setCustomUrl(e.target.value)}
                className="bg-transparent flex-1 text-sm font-bold text-gray-700 outline-none"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-2 mb-8">
            {(Object.keys(templates) as Array<keyof typeof templates>).map((t) => (
              <button
                key={t}
                onClick={() => setSelectedTemplate(t)}
                className={`py-3 rounded-2xl text-[9px] font-black uppercase tracking-widest flex flex-col items-center justify-center gap-2 transition-all border-2 ${
                  selectedTemplate === t ? 'bg-black text-white border-black shadow-lg scale-105' : 'bg-white border-gray-100 text-gray-400 hover:border-orange-200'
                }`}
              >
                {templates[t].icon}
                {templates[t].label}
              </button>
            ))}
          </div>

          <div className="bg-gray-50 p-6 rounded-[2.5rem] border border-gray-100 mb-8 relative">
            <div className="absolute -top-2 -left-2 bg-orange-600 text-black p-1.5 rounded-xl shadow-lg">
               <MessageSquare className="w-3 h-3" />
            </div>
            <p className="text-[10px] font-black text-gray-300 uppercase tracking-widest mb-3">Anteprima Messaggio</p>
            <p className="text-[11px] font-bold text-gray-600 leading-relaxed italic">"{fullMessage}"</p>
          </div>

          <div className="space-y-4">
             <button 
                onClick={handleNativeShare}
                className="w-full flex items-center justify-center gap-4 py-5 bg-orange-600 text-black rounded-[2rem] font-black uppercase tracking-widest text-xs hover:bg-black hover:text-white transition-all shadow-xl active:scale-95 group"
              >
                <Share2 className="w-5 h-5 group-hover:rotate-12 transition-transform" />
                <span>Condividi Ora</span>
              </button>

              <div className="flex gap-3">
                <button 
                  onClick={handleCopy}
                  className={`flex-1 flex items-center justify-center gap-3 py-5 rounded-[2rem] font-black uppercase tracking-widest text-[10px] border-2 transition-all ${copied ? 'bg-green-500 text-white border-green-500 shadow-lg' : 'bg-white border-gray-200 text-gray-900 hover:border-orange-200'}`}
                >
                  {copied ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                  {copied ? 'Copiato' : 'Copia Testo'}
                </button>
                <button 
                  onClick={() => handleSocialShare('whatsapp')}
                  className="px-8 py-5 bg-green-50 text-green-600 rounded-[2rem] flex items-center justify-center hover:bg-green-600 hover:text-white transition-all border border-green-100 shadow-sm"
                >
                  <MessageCircle className="w-5 h-5" />
                </button>
              </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Header } from './components/Header';
import { ChefCard } from './components/ChefCard';
import { CartDrawer } from './components/CartDrawer';
import { AiMenuCreator } from './components/AiMenuCreator';
import { FilterBar, nationalityNames } from './components/FilterBar';
import { ChefProfile } from './components/ChefProfile';
import { BookingModal } from './components/BookingModal';
import { DailySpecials } from './components/DailySpecials';
import { PaymentModal } from './components/PaymentModal';
import { AuthModal } from './components/AuthModal';
import { MesaChefs } from './components/MesaChefs';
import { CultureSection } from './components/CultureSection';
import { ExperiencesSection } from './components/ExperiencesSection';
import { FavoritesSection } from './components/FavoritesSection';
import { Footer } from './components/Footer';
import { NotificationToast } from './components/NotificationToast';
import { BottomNav } from './components/BottomNav';
import { InfoPage } from './components/InfoPage';
import { OrderTracking } from './components/OrderTracking';
import { ActivityFeed } from './components/ActivityFeed';
import { OrderReviewModal } from './components/OrderReviewModal';
import { ShareModal } from './components/ShareModal';
import { AdminDashboard } from './components/AdminDashboard';
import { LaunchTour } from './components/LaunchTour';
import { AiConcierge } from './components/AiConcierge';
import { ChefOnboarding } from './components/ChefOnboarding';
import { ChefGroupSection } from './components/ChefGroupSection';
import { SpaceDesigner } from './components/SpaceDesigner';
import { PublicStorefront } from './components/PublicStorefront';
import { MOCK_CHEFS } from './constants';
import { CartItem, Dish, ViewState, FilterState, Chef, Order, OrderStatus, Continent } from './types';
import { SearchX, ShoppingBag } from 'lucide-react';

function App() {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedChef, setSelectedChef] = useState<Chef | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [favorites, setFavorites] = useState<string[]>([]);

  const [orders, setOrders] = useState<Order[]>([]);
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [reviewOrder, setReviewOrder] = useState<Order | null>(null);

  const [bookingDish, setBookingDish] = useState<Dish | null>(null);
  const [isPaymentOpen, setIsPaymentOpen] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [isShareOpen, setIsShareOpen] = useState(false);
  const [isOnboardingOpen, setIsOnboardingOpen] = useState(false);
  const [showTour, setShowTour] = useState(false);
  const [checkoutTotal, setCheckoutTotal] = useState(0);

  const [toastMessage, setToastMessage] = useState('');
  const [isToastVisible, setIsToastVisible] = useState(false);

  const [filters, setFilters] = useState<FilterState>({
    search: '',
    maxPrice: 50,
    dietary: [],
    categories: [],
    countries: []
  });

  // Gestione parametri URL per link pubblici
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const chefId = params.get('chef');
    if (chefId) {
      const chef = MOCK_CHEFS.find(c => c.id === chefId);
      if (chef) {
        setSelectedChef(chef);
        setCurrentView(ViewState.PUBLIC_STOREFRONT);
      }
    }

    const hasSeenTour = localStorage.getItem('mesa_launch_tour_v60');
    if (!hasSeenTour && !chefId) {
      const timer = setTimeout(() => setShowTour(true), 1500);
      return () => clearTimeout(timer);
    }
  }, []);

  useEffect(() => {
    const activeOrders = orders.filter(o => o.status !== 'COMPLETED');
    if (activeOrders.length === 0) return;

    const timer = setInterval(() => {
      setOrders(prevOrders => {
        return prevOrders.map(order => {
          if (order.status === 'COMPLETED') return order;
          const statusFlow: OrderStatus[] = order.deliveryMode === 'pickup' 
            ? ['PLACED', 'PREPARING', 'READY', 'COMPLETED']
            : ['PLACED', 'PREPARING', 'READY', 'DELIVERING', 'COMPLETED'];

          const currentIndex = statusFlow.indexOf(order.status);
          if (currentIndex < statusFlow.length - 1) {
            const nextStatus = statusFlow[currentIndex + 1];
            if (order.id === orders[0]?.id) {
              const messages = {
                'PREPARING': `👨‍🍳 ${order.chefName} ha iniziato a cucinare!`,
                'READY': `✅ Il tuo piatto è pronto per il ritiro!`,
                'DELIVERING': `🛵 Il rider è partito con il tuo ordine!`,
                'COMPLETED': `🎉 Buon appetito! L'ordine è stato consegnato.`
              };
              showNotification(messages[nextStatus as keyof typeof messages] || "Stato ordine aggiornato");
              if (nextStatus === 'COMPLETED') {
                setTimeout(() => setReviewOrder(order), 2500);
              }
            }
            return { ...order, status: nextStatus };
          }
          return order;
        });
      });
    }, 10000);
    return () => clearInterval(timer);
  }, [orders]);

  const navigateTo = (view: ViewState) => {
    setCurrentView(view);
    if (view !== ViewState.CHEF_PROFILE && view !== ViewState.PUBLIC_STOREFRONT) setSelectedChef(null);
    if (view !== ViewState.ORDERS) setSelectedOrder(null);

    // Pulisci l'URL se si torna alla navigazione standard per evitare loop al refresh
    if (view === ViewState.HOME && window.location.search.includes('chef=')) {
      window.history.replaceState({}, '', window.location.pathname);
    }

    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const showNotification = (message: string) => {
    setToastMessage(message);
    setIsToastVisible(true);
  };

  const handleToggleFavorite = (dishId: string) => {
    setFavorites(prev => {
      if (prev.includes(dishId)) {
        showNotification("Rimosso dai preferiti");
        return prev.filter(id => id !== dishId);
      } else {
        showNotification("Aggiunto ai preferiti ❤️");
        return [...prev, dishId];
      }
    });
  };

  const handleInitiateBooking = (dish: Dish) => setBookingDish(dish);

  const handleConfirmBooking = (date: string, time: string, deliveryMode: 'delivery' | 'pickup', preferences: any) => {
    if (!bookingDish) return;
    setCart(prev => [...prev, { ...bookingDish, quantity: 1, scheduledDate: date, scheduledTime: time, deliveryMode, preferences }]);
    setBookingDish(null);
    setIsCartOpen(true);
    showNotification("Aggiunto al carrello!");
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item).filter(i => i.quantity > 0));
  };

  const handleCheckout = (total: number) => {
    setCheckoutTotal(total);
    setIsCartOpen(false);
    setIsPaymentOpen(true);
  };

  const handlePaymentSuccess = () => {
    const firstChefId = cart[0]?.chefId || 'c1';
    const chefName = MOCK_CHEFS.find(c => c.id === firstChefId)?.name || 'Chef MESA';
    const newOrder: Order = {
      id: `MESA-${Math.random().toString(36).substr(2, 6).toUpperCase()}`,
      items: [...cart],
      total: checkoutTotal,
      status: 'PLACED',
      timestamp: new Date(),
      chefId: firstChefId,
      chefName: chefName,
      deliveryMode: cart[0]?.deliveryMode || 'pickup',
      estimatedTime: 'In arrivo...'
    };
    setOrders(prev => [newOrder, ...prev]);
    setCart([]);
    setSelectedOrder(newOrder);
    setCurrentView(ViewState.ORDERS);
    showNotification("Ordine ricevuto con successo! 🚀");
  };

  const handleReviewSubmit = (rating: number, comment: string) => {
    if (!reviewOrder) return;
    setOrders(prev => prev.map(o => o.id === reviewOrder.id ? { ...o, isReviewed: true } : o));
    setReviewOrder(null);
    showNotification("Grazie per la tua recensione! ⭐");
  };

  const handleViewProfile = (chef: Chef) => {
    setSelectedChef(chef);
    setCurrentView(ViewState.CHEF_PROFILE);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const filteredChefs = useMemo(() => {
    const query = filters.search.toLowerCase().trim();
    return MOCK_CHEFS.filter(chef => {
      const matchesCountry = filters.countries.length === 0 || filters.countries.includes(chef.nationality);
      if (!matchesCountry) return false;
      if (!query) return true;
      const countryKeywords = nationalityNames[chef.nationality] || [];
      const matchesCountryName = countryKeywords.some(keyword => keyword.toLowerCase().includes(query));
      const matchesChefName = chef.name.toLowerCase().includes(query);
      const hasMatchingDish = chef.dishes.some(dish => {
        const matchesDishName = dish.name.toLowerCase().includes(query);
        const matchesDishDesc = dish.description.toLowerCase().includes(query);
        const matchesDishTags = dish.tags.some(tag => tag.toLowerCase().includes(query));
        return matchesDishName || matchesDishDesc || matchesDishTags;
      });
      return matchesCountryName || matchesChefName || hasMatchingDish;
    });
  }, [filters]);

  const chefsByContinent = useMemo(() => {
    const groups: Record<Continent, Chef[]> = {
      'Europa': [],
      'Asia': [],
      'Africa': [],
      'Americhe': [],
      'Oceania': []
    };
    filteredChefs.forEach(chef => {
      groups[chef.continent].push(chef);
    });
    return groups;
  }, [filteredChefs]);

  const cartCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const activeOrdersCount = orders.filter(o => o.status !== 'COMPLETED').length;

  if (currentView === ViewState.PUBLIC_STOREFRONT && selectedChef) {
    return (
      <div className="min-h-screen bg-white font-sans text-gray-900">
        <PublicStorefront 
          chef={selectedChef} 
          onAddDish={handleInitiateBooking} 
          onExit={() => navigateTo(ViewState.HOME)} 
        />
        {bookingDish && (
          <BookingModal 
            isOpen={true} 
            onClose={() => setBookingDish(null)} 
            dish={bookingDish} 
            chef={selectedChef} 
            onConfirm={handleConfirmBooking} 
          />
        )}
        <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} onUpdateQuantity={handleUpdateQuantity} onCheckout={handleCheckout} onAddDish={handleInitiateBooking} availableChefs={MOCK_CHEFS} />
        <PaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} total={checkoutTotal} onSuccess={handlePaymentSuccess} />
        <NotificationToast message={toastMessage} isVisible={isToastVisible} onClose={() => setIsToastVisible(false)} />
        {cartCount > 0 && !isCartOpen && (
          <button 
            onClick={() => setIsCartOpen(true)}
            className="fixed bottom-6 right-6 z-50 bg-black text-white p-6 rounded-full shadow-2xl animate-bounce flex items-center gap-3"
          >
            <ShoppingBag className="w-6 h-6" />
            <span className="font-black">{cartCount}</span>
          </button>
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white font-sans text-gray-900 flex flex-col pb-20 md:pb-0">
      <Header 
        cartCount={cartCount} 
        orderCount={activeOrdersCount} 
        onCartClick={() => setIsCartOpen(true)} 
        currentView={currentView} 
        onNavigate={navigateTo} 
        onAuthClick={() => setIsAuthOpen(true)}
        onShareClick={() => setIsShareOpen(true)}
        onOnboardingClick={() => setIsOnboardingOpen(true)}
      />

      {currentView === ViewState.HOME && <FilterBar filters={filters} onFilterChange={setFilters} />}

      <main className="max-w-6xl mx-auto px-4 py-6 flex-grow w-full mb-8">
        {currentView === ViewState.HOME && !filters.search && <ActivityFeed />}

        {currentView === ViewState.HOME && (
          <div className="animate-fade-in">
            {!filters.search ? (
              <>
                <div className="text-center mb-12 py-16 bg-black rounded-[3rem] text-white shadow-2xl relative overflow-hidden border-b-8 border-orange-600">
                  <div className="absolute top-0 left-0 w-full h-full opacity-20 bg-[url('https://images.unsplash.com/photo-1556910103-1c02745a30bf?auto=format&fit=crop&w=1600&q=80')] bg-cover bg-center"></div>
                  <div className="relative z-10 px-6">
                    <h1 className="text-5xl md:text-8xl font-black mb-4 tracking-tighter italic leading-none">MESA</h1>
                    <p className="text-lg md:text-2xl font-bold text-orange-500 uppercase tracking-[0.2em] mb-4">Cucina Casalinga su Prenotazione</p>
                    <div className="max-w-2xl mx-auto">
                      <p className="text-gray-300 font-medium text-sm md:text-base leading-relaxed bg-white/10 backdrop-blur-md p-6 rounded-3xl border border-white/10">
                        Ogni piatto è preparato in una vera cucina di casa. Sostieni i talenti del tuo quartiere e riscopri il sapore della tradizione autentica.
                      </p>
                    </div>
                  </div>
                </div>

                <DailySpecials chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
                <ChefGroupSection title="Sapori dall'Africa" chefs={chefsByContinent['Africa']} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
                <ChefGroupSection title="Eccellenze Europee" chefs={chefsByContinent['Europa']} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
                <ChefGroupSection title="Tradizioni Asiatiche" chefs={chefsByContinent['Asia']} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
                <ChefGroupSection title="Dalle Americhe" chefs={chefsByContinent['Americhe']} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
              </>
            ) : (
              <div className="space-y-10">
                <div className="flex items-center justify-between border-b pb-6">
                  <div>
                    <h2 className="text-3xl font-black text-gray-900 tracking-tight">Risultati per "{filters.search}"</h2>
                    <p className="text-gray-500 font-bold uppercase text-[10px] tracking-widest mt-1">{filteredChefs.length} cuochi trovati</p>
                  </div>
                  <button onClick={() => setFilters({ ...filters, search: '' })} className="text-xs font-black text-orange-600 uppercase">Torna alla Home</button>
                </div>

                {filteredChefs.length > 0 ? (
                  <div className="grid grid-cols-1 gap-12">
                    {filteredChefs.map(chef => (
                      <ChefCard key={chef.id} chef={chef} onAddDish={handleInitiateBooking} onViewProfile={handleViewProfile} favorites={favorites} onToggleFavorite={handleToggleFavorite} />
                    ))}
                  </div>
                ) : (
                  <div className="py-24 text-center bg-gray-50 rounded-[3rem] border-2 border-dashed border-gray-200">
                    <div className="w-20 h-20 bg-gray-200 rounded-full flex items-center justify-center mx-auto mb-6">
                      <SearchX className="w-10 h-10 text-gray-400" />
                    </div>
                    <h3 className="text-2xl font-black text-gray-400 mb-2">Nessun cuoco trovato</h3>
                    <p className="text-gray-500 font-medium">Prova a cercare termini diversi o esplora le categorie.</p>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {currentView === ViewState.CHEFS && <MesaChefs chefs={filteredChefs} onViewProfile={handleViewProfile} />}
        {currentView === ViewState.SPACE_DESIGNER && <SpaceDesigner />}
        {currentView === ViewState.CULTURE && <CultureSection />}
        {currentView === ViewState.EXPERIENCES && <ExperiencesSection />}
        {currentView === ViewState.FAVORITES && <FavoritesSection favorites={favorites} chefs={MOCK_CHEFS} onAddDish={handleInitiateBooking} onToggleFavorite={handleToggleFavorite} />}
        {currentView === ViewState.ORDERS && (
          selectedOrder 
            ? <OrderTracking order={orders.find(o => o.id === selectedOrder.id) || selectedOrder} onBack={() => setSelectedOrder(null)} />
            : (
              <div className="animate-fade-in space-y-6">
                <h2 className="text-3xl font-black text-gray-900 mb-8 tracking-tight">I Miei Ordini</h2>
                {orders.length === 0 ? <p className="text-gray-400 font-bold py-20 text-center bg-gray-50 rounded-[3rem]">Nessun ordine attivo.</p> : orders.map(order => (
                  <div key={order.id} onClick={() => setSelectedOrder(order)} className="bg-white p-6 rounded-[2.5rem] border border-gray-100 shadow-sm hover:shadow-xl transition-all cursor-pointer flex justify-between items-center group">
                    <div>
                      <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">#{order.id.split('-')[0]}</p>
                      <h4 className="font-bold text-xl text-gray-900">{order.chefName}</h4>
                      <p className="text-xs text-gray-500">{order.items.length} {order.items.length === 1 ? 'piatto' : 'piatti'} • €{order.total.toFixed(2)}</p>
                    </div>
                    <div className="flex items-center space-x-4">
                      <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${order.status === 'COMPLETED' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700 animate-pulse'}`}>{order.status}</span>
                    </div>
                  </div>
                ))}
              </div>
            )
        )}
        {currentView === ViewState.CHEF_PROFILE && selectedChef && (
          <ChefProfile chef={selectedChef} onBack={() => navigateTo(ViewState.HOME)} onAddDish={handleInitiateBooking} favorites={favorites} onToggleFavorite={handleToggleFavorite} onNavigateToCulture={() => navigateTo(ViewState.CULTURE)} />
        )}
        {currentView === ViewState.AI_MENU_CREATOR && <AiMenuCreator />}
        {currentView === ViewState.ADMIN_DASHBOARD && <AdminDashboard chefs={MOCK_CHEFS} orders={orders} />}
        {[ViewState.ABOUT, ViewState.SAFETY, ViewState.BECOME_CHEF, ViewState.HELP, ViewState.TERMS, ViewState.PRIVACY].includes(currentView) && (
          <InfoPage view={currentView} onBack={() => navigateTo(ViewState.HOME)} />
        )}
      </main>

      <Footer onNavigate={navigateTo} />
      <BottomNav currentView={currentView} onNavigate={navigateTo} />

      {bookingDish && (
        <BookingModal 
          isOpen={true} 
          onClose={() => setBookingDish(null)} 
          dish={bookingDish} 
          chef={MOCK_CHEFS.find(c => c.id === bookingDish.chefId)} 
          onConfirm={handleConfirmBooking} 
        />
      )}

      <CartDrawer isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} cart={cart} onUpdateQuantity={handleUpdateQuantity} onCheckout={handleCheckout} onAddDish={handleInitiateBooking} availableChefs={MOCK_CHEFS} />
      <PaymentModal isOpen={isPaymentOpen} onClose={() => setIsPaymentOpen(false)} total={checkoutTotal} onSuccess={handlePaymentSuccess} />
      <AuthModal isOpen={isAuthOpen} onClose={() => setIsAuthOpen(false)} onAdminLogin={() => navigateTo(ViewState.ADMIN_DASHBOARD)} />
      <OrderReviewModal isOpen={!!reviewOrder} onClose={() => setReviewOrder(null)} order={reviewOrder!} onSubmit={handleReviewSubmit} />
      <ShareModal isOpen={isShareOpen} onClose={() => setIsShareOpen(false)} contextChefId={selectedChef?.id} />
      <ChefOnboarding isOpen={isOnboardingOpen} onClose={() => setIsOnboardingOpen(false)} />
      <NotificationToast message={toastMessage} isVisible={isToastVisible} onClose={() => setIsToastVisible(false)} />

      {showTour && (
        <LaunchTour onComplete={() => { 
          setShowTour(false); 
          localStorage.setItem('mesa_launch_tour_v60', 'true'); 
        }} />
      )}
      <AiConcierge />
    </div>
  );
}

export default App;

export interface Ingredient {
  name: string;
}

export interface Review {
  id: string;
  author: string;
  rating: number;
  comment: string;
  date: string;
}

export interface CultureStory {
  id: string;
  title: string;
  country: string;
  flag: string;
  image: string;
  content: string;
  funFact: string;
}

export interface Dish {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  chefId: string;
  tags: string[]; 
  calories?: number;
  dietary?: ('Vegetarian' | 'Vegan' | 'Gluten Free' | 'Lactose Free')[];
  ingredients?: string[];
  preparation?: string;
}

export type Continent = 'Europa' | 'Asia' | 'Africa' | 'Americhe' | 'Oceania';

export interface Chef {
  id: string;
  name: string;
  nationality: string; 
  continent: Continent;
  bio: string;
  fullBio?: string;
  avatar: string;
  rating: number;
  location: string;
  distance: number; 
  specialties: string[];
  availability: string[]; 
  availableDays: number[]; 
  reviews: Review[];
  dishes: Dish[];
}

export type OrderStatus = 'PLACED' | 'PREPARING' | 'READY' | 'DELIVERING' | 'COMPLETED';

export interface Message {
  id: string;
  sender: 'user' | 'chef';
  text: string;
  timestamp: Date;
}

export interface Order {
  id: string;
  items: CartItem[];
  total: number;
  status: OrderStatus;
  timestamp: Date;
  chefId: string;
  chefName: string;
  deliveryMode: 'delivery' | 'pickup';
  estimatedTime: string;
  isReviewed?: boolean;
  messages?: Message[];
}

export interface CartItem extends Dish {
  quantity: number;
  scheduledDate: string; 
  scheduledTime: string; 
  deliveryMode: 'delivery' | 'pickup';
  preferences: {
    spiceLevel: number; 
    saltLevel: 'Low' | 'Normal' | 'High';
    notes: string;
  };
}

export interface Activity {
  id: string;
  user: string;
  action: string;
  item: string;
  time: string;
}

export enum ViewState {
  HOME = 'HOME',
  CHEFS = 'CHEFS',
  CULTURE = 'CULTURE',
  EXPERIENCES = 'EXPERIENCES',
  CHEF_PROFILE = 'CHEF_PROFILE',
  AI_MENU_CREATOR = 'AI_MENU_CREATOR',
  FAVORITES = 'FAVORITES',
  ABOUT = 'ABOUT',
  SAFETY = 'SAFETY',
  TERMS = 'TERMS',
  PRIVACY = 'PRIVACY',
  HELP = 'HELP',
  BECOME_CHEF = 'BECOME_CHEF',
  ORDERS = 'ORDERS',
  ADMIN_DASHBOARD = 'ADMIN_DASHBOARD',
  MESSAGES = 'MESSAGES',
  SPACE_DESIGNER = 'SPACE_DESIGNER',
  PUBLIC_STOREFRONT = 'PUBLIC_STOREFRONT',
  HERITAGE_JOURNEY = 'HERITAGE_JOURNEY'
}

export interface AiMenuResponse {
  dishName: string;
  description: string;
  suggestedPrice: number;
  tags: string[];
}

export interface HeritageStoryResponse {
  story: string;
  sensoryDetails: string;
  ritual: string;
  pairing: string;
}

export interface FilterState {
  search: string;
  maxPrice: number;
  dietary: string[];
  categories: string[];
  countries: string[];
}

import React, { useState, useEffect } from 'react';
import { Chef, Dish, HeritageStoryResponse } from '../types';
import { X, Sparkles, Music, Wind, Coffee, Heart, Loader2, Quote, Compass } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

interface HeritageJourneyProps {
  chef: Chef;
  dish: Dish;
  onClose: () => void;
}

export const HeritageJourney: React.FC<HeritageJourneyProps> = ({ chef, dish, onClose }) => {
  const [data, setData] = useState<HeritageStoryResponse | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const generateStory = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      try {
        const prompt = `
          Agisci come un antropologo del gusto e un poeta gastronomico.
          Racconta la "storia dell'anima" di questo piatto: "${dish.name}" cucinato da "${chef.name}" (${chef.nationality}).
          Lo chef dice di sé: "${chef.fullBio || chef.bio}".
          Ingredienti chiave: "${dish.ingredients?.join(', ') || 'Tradizionali'}".

          Genera un oggetto JSON con:
          1. "story": Un breve paragrafo evocativo che parla delle radici culturali e familiari del piatto.
          2. "sensoryDetails": Una descrizione di ciò che l'utente sentirà al primo morso (profumi, consistenze).
          3. "ritual": Un consiglio su come consumare il piatto (es. "Spegni le luci, accendi una candela...").
          4. "pairing": Una raccomandazione di sottofondo musicale o bevanda.

          Usa un tono caloroso, solenne e artigianale. Rispondi SOLO in formato JSON.
        `;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
          config: {
            responseMimeType: "application/json",
            responseSchema: {
              type: Type.OBJECT,
              properties: {
                story: { type: Type.STRING },
                sensoryDetails: { type: Type.STRING },
                ritual: { type: Type.STRING },
                pairing: { type: Type.STRING }
              },
              required: ["story", "sensoryDetails", "ritual", "pairing"]
            }
          }
        });

        const result = JSON.parse(response.text);
        setData(result);
      } catch (e) {
        console.error(e);
      }
      setLoading(false);
    };

    generateStory();
  }, [chef, dish]);

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-0 md:p-10 animate-fade-in">
      <div className="fixed inset-0 bg-black/95 backdrop-blur-2xl" onClick={onClose}></div>

      <div className="relative w-full max-w-4xl h-full md:h-auto md:max-h-[90vh] bg-white/5 border border-white/10 md:rounded-[4rem] overflow-hidden shadow-[0_0_100px_rgba(234,88,12,0.2)] flex flex-col md:flex-row">

        {/* Immagine Piatto laterale */}
        <div className="w-full md:w-2/5 h-64 md:h-auto relative">
          <img src={dish.image} alt={dish.name} className="w-full h-full object-cover grayscale-[0.3] hover:grayscale-0 transition-all duration-1000" />
          <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent"></div>
          <button 
            onClick={onClose}
            className="absolute top-6 left-6 p-4 bg-white/10 hover:bg-orange-600 backdrop-blur-md rounded-2xl text-white transition-all z-20 md:hidden"
          >
            <X className="w-6 h-6" />
          </button>
          <div className="absolute bottom-10 left-10 text-white">
            <p className="text-[10px] font-black uppercase tracking-[0.4em] text-orange-500 mb-2">Eredità di</p>
            <h2 className="text-4xl font-black italic tracking-tighter leading-none">{chef.name}</h2>
            <div className="mt-4 flex items-center gap-2">
              <span className="text-3xl">{chef.nationality}</span>
              <span className="text-[10px] font-bold uppercase tracking-widest bg-white/10 px-3 py-1 rounded-lg">Piatto del Cuore</span>
            </div>
          </div>
        </div>

        {/* Contenuto Narrativo */}
        <div className="flex-1 p-8 md:p-16 overflow-y-auto custom-scrollbar bg-black/40 backdrop-blur-3xl text-white">
          <button 
            onClick={onClose}
            className="absolute top-10 right-10 p-4 bg-white/5 hover:bg-orange-600 rounded-2xl text-white transition-all hidden md:block"
          >
            <X className="w-6 h-6" />
          </button>

          {loading ? (
            <div className="h-full flex flex-col items-center justify-center gap-6 py-20">
               <div className="relative">
                  <div className="absolute inset-0 bg-orange-600/20 rounded-full blur-2xl animate-pulse"></div>
                  <Loader2 className="w-16 h-16 text-orange-600 animate-spin relative z-10" />
               </div>
               <p className="text-sm font-black uppercase tracking-[0.3em] text-gray-500 animate-pulse text-center">
                  L'AI sta tessendo la storia <br/>delle tradizioni di {chef.name}...
               </p>
            </div>
          ) : data && (
            <div className="space-y-12 animate-fade-in-up">
              <div className="flex items-center gap-3 text-orange-500">
                <Compass className="w-6 h-6" />
                <span className="text-[10px] font-black uppercase tracking-[0.5em]">Viaggio nel Tempo</span>
              </div>

              <section>
                <div className="mb-6 opacity-30">
                  <Quote className="w-12 h-12 rotate-180" />
                </div>
                <p className="text-2xl md:text-3xl font-bold italic leading-relaxed text-gray-200">
                  {data.story}
                </p>
              </section>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-10 pt-10 border-t border-white/10">
                <div className="space-y-4">
                  <h4 className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-orange-500">
                    <Wind className="w-4 h-4" /> Risveglio dei Sensi
                  </h4>
                  <p className="text-sm text-gray-400 leading-relaxed italic">
                    "{data.sensoryDetails}"
                  </p>
                </div>
                <div className="space-y-4">
                  <h4 className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-orange-500">
                    <Music className="w-4 h-4" /> L'Atmosfera
                  </h4>
                  <p className="text-sm text-gray-400 leading-relaxed italic">
                    "{data.pairing}"
                  </p>
                </div>
              </div>

              <div className="bg-orange-600/10 border border-orange-600/30 p-10 rounded-[3rem] relative overflow-hidden group">
