export interface Ingredient {
  name: string;
}

export interface Review {
  id: string;
  author: string;
  rating: number;
  comment: string;
  date: string;
}

export interface CultureStory {
  id: string;
  title: string;
  country: string;
  flag: string;
  image: string;
  content: string;
  funFact: string;
}

export interface Dish {
  id: string;
  name: string;
  description: string;
  price: number;
  image: string;
  chefId: string;
  tags: string[]; 
  calories?: number;
  dietary?: ('Vegetarian' | 'Vegan' | 'Gluten Free' | 'Lactose Free')[];
  ingredients?: string[];
  preparation?: string;
}

export type Continent = 'Europa' | 'Asia' | 'Africa' | 'Americhe' | 'Oceania';

export interface Chef {
  id: string;
  name: string;
  nationality: string; 
  continent: Continent;
  bio: string;
  fullBio?: string;
  avatar: string;
  rating: number;
  location: string;
  distance: number; 
  specialties: string[];
  availability: string[]; 
  availableDays: number[]; 
  reviews: Review[];
  dishes: Dish[];
}

export type OrderStatus = 'PLACED' | 'PREPARING' | 'READY' | 'DELIVERING' | 'COMPLETED';

export interface Message {
  id: string;
  sender: 'user' | 'chef';
  text: string;
  timestamp: Date;
}

export interface Order {
  id: string;
  items: CartItem[];
  total: number;
  status: OrderStatus;
  timestamp: Date;
  chefId: string;
  chefName: string;
  deliveryMode: 'delivery' | 'pickup';
  estimatedTime: string;
  isReviewed?: boolean;
  messages?: Message[];
}

export interface CartItem extends Dish {
  quantity: number;
  scheduledDate: string; 
  scheduledTime: string; 
  deliveryMode: 'delivery' | 'pickup';
  preferences: {
    spiceLevel: number; 
    saltLevel: 'Low' | 'Normal' | 'High';
    notes: string;
  };
}

export interface Activity {
  id: string;
  user: string;
  action: string;
  item: string;
  time: string;
}

